INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C1','kor',5,1,'u1',1,'배려하며 대화하기의 뜻 — 배려하며 대화한다는 것은 상대의 처지에서 생각하고 그 마음에 맞게 말과 태도를 고르는 것이다',ARRAY['6국01-03 듣기·말하기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C2','kor',5,1,'u1',1,'배려하며 대화하면 좋은 점 — 배려하며 대화하면 서로 기분이 상하지 않고 대화를 이어 갈 수 있으며, 배려는 대화에서 이기거나 빨리 끝내는 기술이 아니라 관계를 지키는 태도이다',ARRAY['6국01-03 듣기·말하기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C3','kor',5,1,'u1',1,'생략된 내용의 뜻 — 생략된 내용은 말에 다 드러나지 않은 부분으로, 우리는 서로 알고 있다고 여기는 부분을 줄여서 말하므로 대화에는 늘 빈 곳이 있다',ARRAY['6국01-01 듣기·말하기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C4','kor',5,1,'u1',1,'단서의 뜻 — 단서는 어떤 일을 풀 수 있는 실마리이며, 짐작에는 늘 단서라는 근거가 있어야 한다',ARRAY['6국01-01 듣기·말하기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C5','kor',5,1,'u1',1,'두 가지가 함께 갖추어진 대화 — 상대를 배려하며 대화하기와 생략된 내용을 짐작하며 대화하기가 함께 갖추어질 때 비로소 대화가 오간다',ARRAY['6국01-03 듣기·말하기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C6','kor',5,1,'u1',2,'집중해서 듣기 — 상대를 바라보고 고개를 끄덕이며 끝까지 듣는 것이 배려이며, 말을 끊고 다른 이야기를 꺼내면 상대는 하던 말을 멈추게 된다',ARRAY['6국01-03 듣기·말하기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C7','kor',5,1,'u1',2,'이어서 말하도록 되묻기 — 「그래서 어떻게 했어?」처럼 상대가 하던 말을 이어 가도록 되묻는 것도 잘 듣는 태도이며, 잘 듣는 것은 아무 반응 없이 가만히 있는 것이 아니다',ARRAY['6국01-03 듣기·말하기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C8','kor',5,1,'u1',2,'상대의 기분을 고려하며 말하기 — 상대의 실수나 잘못을 먼저 탓하지 않고 마음을 헤아리며 말하며, 같은 처지였던 내 경험을 꺼내 마음을 나누기도 한다',ARRAY['6국01-03 듣기·말하기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C9','kor',5,1,'u1',2,'대화 예절 지키기 — 상대가 말을 마칠 때까지 기다려 차례를 지키고, 상대를 낮추거나 놀리는 말 대신 바른 말씨를 쓰는 것이 대화 예절이다',ARRAY['6국01-03 듣기·말하기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C10','kor',5,1,'u1',2,'표정과 행동도 말이다 — 같은 말이라도 딴 곳을 보며 하면 마음이 전해지지 않고, 말수가 적어도 눈을 맞추고 고개를 끄덕이면 상대는 말이 받아들여졌다고 느끼므로 배려는 말의 양이 아니라 태도에서 드러난다',ARRAY['6국01-03 듣기·말하기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C11','kor',5,1,'u1',2,'배려에는 정해진 공식이 없다 — 배려하며 대화하는 방법 네 가지는 외울 공식이 아니며, 상황과 상대에 따라 배려하는 방법이 달라지고 내가 찾은 방법도 배려가 될 수 있다',ARRAY['6국01-03 듣기·말하기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C12','kor',5,1,'u1',2,'형식보다 진심 — 배려하는 말투와 표정을 흉내 내는 것보다 상대의 처지를 실제로 생각해 보는 것이 먼저이며, 같은 말이라도 마음이 없으면 상대는 알아챈다',ARRAY['6국01-03 듣기·말하기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C13','kor',5,1,'u1',2,'상황에 어울리는 배려의 말 — 속상한 친구에게는 마음을 알아주는 말, 기뻐하는 친구에게는 함께 기뻐하는 말, 부탁을 어렵게 꺼내는 친구에게는 편하게 말하도록 돕는 말처럼 상황마다 필요한 말이 다르다',ARRAY['6국01-03 듣기·말하기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C14','kor',5,1,'u1',2,'탓하는 말을 마음 받아 주는 말로 — 위로가 필요한 때에 까닭을 따지거나 마음을 가볍게 넘기지 않고, 먼저 마음을 받아 주는 말을 한 뒤 도울 방법을 보태어 바꾸어 말한다',ARRAY['6국01-03 듣기·말하기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C15','kor',5,1,'u1',4,'준비 → 대화 → 점검 — 주제를 정하여 대화할 때에는 말할 내용을 준비하고, 배려하며 대화한 뒤, 대화를 잘했는지 스스로 점검하는 차례로 이어진다',ARRAY['6국01-03 듣기·말하기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C16','kor',5,1,'u1',4,'대화 주제 고르기 — 직접 겪은 일이라면 크고 특별하지 않아도, 즐거운 일이 아니어도(슬펐던 일 · 화났던 일) 주제가 되지만, 아직 겪지 않은 일이나 친구가 숨기고 싶어 하는 비밀은 주제로 알맞지 않다',ARRAY['6국01-03 듣기·말하기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C17','kor',5,1,'u1',4,'말할 내용의 네 항목 — 말할 내용은 언제(그 일이 있었던 때) · 어디에서(그 일이 있었던 곳) · 무슨 일을(실제로 일어난 일) · 생각이나 느낌(그때 든 마음)으로 정리한다',ARRAY['6국01-03 듣기·말하기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C18','kor',5,1,'u1',4,'생각이나 느낌을 빠뜨리지 않기 — 네 항목 가운데 생각이나 느낌이 빠지면 있었던 일만 늘어놓는 이야기가 되므로 그때 든 마음까지 준비한다',ARRAY['6국01-03 듣기·말하기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C19','kor',5,1,'u1',4,'주제는 함께 정하기 — 한쪽이 혼자 주제를 정해 버리면 대화가 시작되기 전에 한 사람이 빠지게 되므로, 서로 의논해서 두 사람이 모두 이야기하고 싶은 주제를 함께 정한다',ARRAY['6국01-03 듣기·말하기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C20','kor',5,1,'u1',4,'반응하는 말 — 상대의 말을 이어받아 더 묻거나(물 주는 걸 잊은 날은 없었어?) 마음을 알아주는 말(그래서 더 마음이 갔겠다)은 듣고 있다는 신호이며, 「그건 별일 아니네」 · 「내 이야기 먼저 할게」는 대화를 끊는다',ARRAY['6국01-03 듣기·말하기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C21','kor',5,1,'u1',4,'스스로 점검하고 칭찬하기 — 대화가 끝나면 듣기 · 기분 고려 · 예절 · 표정과 행동을 스스로 점검하고, 친구가 잘한 점을 「끝까지 들어 줘서 고마웠어」처럼 무엇이 좋았는지 짚어 칭찬한다',ARRAY['6국01-03 듣기·말하기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C22','kor',5,1,'u1',6,'짐작의 네 가지 단서 — 생략된 내용은 말에서 단서 확인하기 · 행동이나 표정에서 단서 확인하기 · 자신의 경험이나 배경지식 떠올리기 · 그때의 상황 고려하기로 짐작한다',ARRAY['6국01-01 듣기·말하기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C23','kor',5,1,'u1',6,'같은 말, 다른 짐작 — 같은 말을 들어도 사람마다 주목한 단서와 떠올린 경험이 달라 다르게 짐작할 수 있으며, 누구의 짐작이 맞았는지보다 무엇을 보고 그렇게 생각했는지가 중요하다',ARRAY['6국01-01 듣기·말하기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C24','kor',5,1,'u1',6,'짐작의 두 걸음 — 짐작은 실제로 들은 말과 본 행동 같은 드러난 것을 먼저 확인하고, 그것을 내 경험이나 아는 것 · 그때의 상황과 이어 보는 두 걸음이며, 첫 걸음을 건너뛰면 짐작이 아니라 넘겨짚기가 된다',ARRAY['6국01-01 듣기·말하기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C25','kor',5,1,'u1',6,'근거가 있는 짐작 — 알맞은 짐작은 대화에 나온 말이나 행동에서 근거를 찾을 수 있는 것이며, 대화 어디에도 근거가 없는 내용은 짐작이 아니라 지어낸 생각이다',ARRAY['6국01-01 듣기·말하기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C26','kor',5,1,'u1',6,'짐작은 단정이 아니다 — 짐작은 아직 맞는지 모르는 생각이므로 「그럴 것이다」를 「그렇다」로 굳히지 않고, 상대에게 물어 확인하거나 친구의 생각과 견주어 보며, 짐작을 잘하면 대화가 부드러워지고 잘못 짐작하면 오해가 생긴다',ARRAY['6국01-01 듣기·말하기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C27','kor',5,1,'u1',6,'짐작이 필요한 때 — 대부분의 말은 말한 그대로가 전부이며, 말이 갑자기 짧아지거나 말과 표정이 어긋나거나 되물어야 이해될 때 짐작하며 듣고, 아무 말에나 숨은 뜻을 붙이면 그것도 오해가 된다',ARRAY['6국01-01 듣기·말하기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C28','kor',5,1,'u1',8,'이야기에 남겨 둔 빈 곳 — 글쓴이는 모든 것을 알려 주지 않고 독자가 단서를 모아 채우도록 남겨 두므로, 제목을 보고 떠오른 물음을 담고 이야기 속 단서를 찾으며 읽는다',ARRAY['6국01-01 듣기·말하기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C29','kor',5,1,'u1',8,'흩어진 단서 모으기 — 이야기 곳곳에 흩어진 물건 · 행동 · 때의 단서를 하나로 모아 생략된 내용을 짐작하며, 짐작과 관계없는 사실은 단서가 되지 않는다',ARRAY['6국01-01 듣기·말하기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C30','kor',5,1,'u1',8,'인물의 말과 행동에 담긴 생략 — 인물이 「그냥」이라고 말하거나 물건을 슬그머니 감추는 행동에는 말하기 쑥스럽거나 어려운 까닭이 생략되어 있을 수 있으므로, 앞뒤의 다른 단서와 함께 짐작한다',ARRAY['6국01-01 듣기·말하기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C31','kor',5,1,'u1',8,'이야기 흐름 간추리기 — 이야기는 처음 · 가운데 · 끝의 중요한 일만 차례대로 골라 간추리며, 분위기를 보여 주는 작은 묘사는 간추릴 때 빼도 된다',ARRAY['6국01-01 듣기·말하기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C32','kor',5,1,'u1',8,'문맥으로 낱말 뜻 짐작하기 — 모르는 낱말을 만나면 사전을 펴기 전에 앞뒤 문장을 다시 읽어 글쓴이가 남긴 단서로 뜻을 짐작한다(흙을 눌렀더니 물기가 배어 나왔다 → 눅눅하다 = 축축한 기운이 있다)',ARRAY['6국01-01 듣기·말하기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C33','kor',5,1,'u1',11,'고민을 배려하며 듣기 — 친구의 고민은 끝까지 듣고 마음을 먼저 알아주며 자세히 물어 확인하고, 가벼운 일이라고 넘기거나 다른 친구에게 옮기지 않는다',ARRAY['6국01-03 듣기·말하기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C34','kor',5,1,'u1',11,'고민 글에 적히지 않은 마음 — 고민 글에는 지금의 마음이 다 적혀 있지 않으므로 「그래서 요즘은 그냥 가만히 있습니다」 같은 말을 단서로 마음을 짐작하고, 짐작이 맞는지 물어본다',ARRAY['6국01-01 듣기·말하기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C35','kor',5,1,'u1',11,'조언을 건네는 요령 — 조언은 먼저 마음을 알아주는 말을 하고, 내가 해 본 방법을 구체적으로 말한 뒤, 「이렇게 해 보면 어떨까?」처럼 고르도록 권하는 말투로 맺어 상대에게 고를 여지를 남긴다',ARRAY['6국01-03 듣기·말하기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C36','kor',5,1,'u1',11,'고민에 맞는 조언 — 고민마다 가장 어려워하는 부분이 달라 필요한 도움도 다르므로, 고민의 어려운 곳을 짚어 그에 맞는 방법을 건넨다',ARRAY['6국01-03 듣기·말하기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C37','kor',5,1,'u1',11,'실천 활동은 반에서 함께 정한다 — 배운 것을 실천하는 활동은 고민 상담소 하나로 정해져 있지 않고, 대화 빙고 놀이 · 이야기에서 짐작하기처럼 반에서 함께 정해 할 수 있다',ARRAY['6국01-03 듣기·말하기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C38','kor',5,1,'u1',11,'배려와 짐작은 서로 돕는다 — 상대를 배려하기 때문에 말과 행동을 눈여겨보게 되고, 눈여겨보기 때문에 생략된 마음을 짐작할 수 있어, 배려와 짐작은 따로 있지 않고 서로를 돕는다',ARRAY['6국01-01 듣기·말하기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C39','kor',5,1,'u1',11,'소리의 길이로 뜻 가르기 — 우리말에는 글자는 같지만 소리의 길이가 다른 낱말이 있어(말[말] 사람이 타는 동물 · 말[말ː] 생각을 나타내는 소리, 밤[밤] 해가 진 뒤 · 밤[밤ː] 밤나무의 열매) 길이에 따라 뜻이 달라지며, 길게 소리 낼 때에는 [ː] 표시를 한다 (기초 다지기)',ARRAY['기초 다지기(장단)']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u1-C40','kor',5,1,'u1',11,'문장 속 뜻을 보고 장단 정하기 — 문장에서 그 낱말이 어떤 뜻으로 쓰였는지 먼저 보고 짧은소리와 긴소리를 골라 발음한다(눈[눈] 보는 몸의 부분 · 눈[눈ː] 하늘에서 내리는 것, 벌[벌] 잘못에 주는 괴로움 · 벌[벌ː] 꿀을 모으는 곤충) (기초 다지기)',ARRAY['기초 다지기(장단)']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X01','kor',5,'u1',ARRAY['K5-1-u1-C1']::text[],'배려를 듣기 좋은 말로 꾸미는 기술로 여겨 상대의 처지를 생각하지 않는다','상대의 처지에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X02','kor',5,'u1',ARRAY['K5-1-u1-C2']::text[],'배려하며 대화하는 까닭을 대화에서 이기거나 빨리 끝내기 위해서라고 여긴다','관계를 지키는 태도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X03','kor',5,'u1',ARRAY['K5-1-u1-C3']::text[],'말한 것만이 대화의 전부라고 여겨 다 드러나지 않은 부분이 있는 줄 모른다','말에는 빈 곳이 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X04','kor',5,'u1',ARRAY['K5-1-u1-C4']::text[],'단서 없이 느낌이나 바람대로 짐작한다','무엇을 보고?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X05','kor',5,'u1',ARRAY['K5-1-u1-C5','K5-1-u1-C38']::text[],'배려하며 대화하기와 짐작하며 대화하기를 서로 관계없는 따로 떨어진 일로 여긴다','서로를 도와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X06','kor',5,'u1',ARRAY['K5-1-u1-C6']::text[],'상대가 말하는 도중에 말을 끊고 내 이야기나 다른 이야기를 꺼낸다','끝까지 들어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X07','kor',5,'u1',ARRAY['K5-1-u1-C7']::text[],'잘 듣는 것을 아무 반응 없이 가만히 있는 것으로만 여겨 이어 묻지 않는다','되묻는 것도 듣기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X08','kor',5,'u1',ARRAY['K5-1-u1-C8']::text[],'상대의 실수나 잘못을 먼저 탓하거나 내 자랑을 앞세운다','마음부터 헤아려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X09','kor',5,'u1',ARRAY['K5-1-u1-C9']::text[],'마음만 있으면 차례를 어기거나 놀리는 말을 섞어도 괜찮다고 여긴다','차례 · 바른 말씨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X10','kor',5,'u1',ARRAY['K5-1-u1-C10']::text[],'말만 바르면 딴 곳을 보거나 다른 일을 하며 대화해도 마음이 전해진다고 여긴다','표정과 행동도 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X11','kor',5,'u1',ARRAY['K5-1-u1-C10']::text[],'배려는 말을 길게 많이 해 주는 것이라고 여긴다','양이 아니라 태도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X12','kor',5,'u1',ARRAY['K5-1-u1-C11']::text[],'배려하는 방법 네 가지를 외워 그대로만 하면 되고 다른 방법은 배려가 아니라고 여긴다','정해진 공식은 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X13','kor',5,'u1',ARRAY['K5-1-u1-C12']::text[],'배려하는 말이나 말투만 흉내 내면 마음이 없어도 전해진다고 여긴다','상대는 알아채요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X14','kor',5,'u1',ARRAY['K5-1-u1-C13']::text[],'상황과 상관없이 같은 말로 반응해, 기뻐하는 친구를 위로하거나 속상한 친구에게 축하하듯 말한다','지금 무엇을 바라나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X15','kor',5,'u1',ARRAY['K5-1-u1-C14']::text[],'위로가 필요한 때에 까닭을 따지거나 「다음에 잘하면 되잖아」처럼 속상한 마음을 가볍게 넘긴다','마음을 먼저 받아 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X16','kor',5,'u1',ARRAY['K5-1-u1-C15']::text[],'준비 없이 대화를 시작하거나 대화가 끝나면 점검하지 않는다','준비 → 대화 → 점검') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X17','kor',5,'u1',ARRAY['K5-1-u1-C16']::text[],'대화 주제는 크고 특별하거나 즐거운 일이어야만 한다고 여긴다','겪은 일이면 무엇이든') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X18','kor',5,'u1',ARRAY['K5-1-u1-C16']::text[],'아직 겪지 않은 일이나 친구가 숨기고 싶어 하는 비밀을 대화 주제로 고른다','내가 겪은 일인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X19','kor',5,'u1',ARRAY['K5-1-u1-C17']::text[],'언제 · 어디에서 · 무슨 일을 · 생각이나 느낌의 네 항목을 헷갈려 엉뚱한 칸에 넣는다','때 · 곳 · 일 · 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X20','kor',5,'u1',ARRAY['K5-1-u1-C18']::text[],'생각이나 느낌을 빼고 있었던 일만 늘어놓는다','그때 든 마음은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X21','kor',5,'u1',ARRAY['K5-1-u1-C19']::text[],'주제를 한쪽이 혼자 정하거나, 상대가 정한 대로 말없이 따라가기만 한다','함께 의논해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X22','kor',5,'u1',ARRAY['K5-1-u1-C20']::text[],'「그건 별일 아니네」처럼 상대의 말을 가볍게 넘기거나 반응 없이 내 이야기로 넘어간다','이어받아 반응해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X23','kor',5,'u1',ARRAY['K5-1-u1-C21']::text[],'대화를 점검하지 않거나, 친구를 칭찬할 때 무엇이 좋았는지 짚지 않고 「그냥 다 잘했어」로 넘긴다','잘한 점을 짚어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X24','kor',5,'u1',ARRAY['K5-1-u1-C22']::text[],'짐작의 단서를 말에서만 찾고 행동 · 경험 · 상황은 살피지 않는다','네 가지 단서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X25','kor',5,'u1',ARRAY['K5-1-u1-C22']::text[],'짐작에 쓴 단서가 말인지 · 행동인지 · 경험인지 · 상황인지 헷갈린다','무엇을 보고 · 들었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X26','kor',5,'u1',ARRAY['K5-1-u1-C23']::text[],'나와 다르게 짐작한 친구는 틀렸다고 여기거나 누구의 짐작이 맞았는지만 따진다','무엇을 보고 그렇게?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X27','kor',5,'u1',ARRAY['K5-1-u1-C24']::text[],'드러난 말과 행동을 확인하지 않고 바로 넘겨짚는다','드러난 것부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X28','kor',5,'u1',ARRAY['K5-1-u1-C25']::text[],'대화 어디에도 근거가 없는 내용까지 알맞게 짐작했다고 여긴다','대화에 근거가 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X29','kor',5,'u1',ARRAY['K5-1-u1-C26']::text[],'짐작한 내용을 확인하지 않고 사실처럼 믿거나 다른 사람에게 알린다','짐작은 단정이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X30','kor',5,'u1',ARRAY['K5-1-u1-C27']::text[],'모든 말에 숨은 뜻이 있다고 여겨 아무 말에나 뜻을 붙인다','대부분은 말 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X31','kor',5,'u1',ARRAY['K5-1-u1-C28']::text[],'이야기는 글쓴이가 모든 것을 다 알려 준다고 여겨 빈 곳을 채우며 읽지 않는다','남겨 둔 빈 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X32','kor',5,'u1',ARRAY['K5-1-u1-C29']::text[],'짐작과 관계없는 사실까지 단서로 삼거나 단서 하나만 보고 판단한다','흩어진 단서를 모아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X33','kor',5,'u1',ARRAY['K5-1-u1-C30']::text[],'인물이 「그냥」이라고 하면 정말 아무 까닭이 없다고 여기거나, 행동에 담긴 마음을 엉뚱하게 짐작한다','말하지 못한 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X34','kor',5,'u1',ARRAY['K5-1-u1-C31']::text[],'간추릴 때 중요하지 않은 묘사까지 넣거나 일의 차례를 뒤섞는다','중요한 일만 차례대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X35','kor',5,'u1',ARRAY['K5-1-u1-C32']::text[],'모르는 낱말을 앞뒤 문장을 보지 않고 넘기거나 엉뚱한 뜻으로 짐작한다','앞뒤에 단서가 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X36','kor',5,'u1',ARRAY['K5-1-u1-C33']::text[],'친구의 고민을 가벼운 일로 넘기거나 다른 친구에게 옮긴다','끝까지 · 마음 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X37','kor',5,'u1',ARRAY['K5-1-u1-C34']::text[],'고민 글에 적힌 말만 읽고 적히지 않은 마음은 살피지 않는다','「그래서 …」가 단서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X38','kor',5,'u1',ARRAY['K5-1-u1-C35']::text[],'조언을 「이렇게 해」처럼 시키거나 탓하는 말로 하고, 마음을 알아주는 말을 빠뜨린다','마음 → 방법 → 권하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X39','kor',5,'u1',ARRAY['K5-1-u1-C36']::text[],'고민에서 어려워하는 부분과 맞지 않는 조언을 건넨다','어디가 어려운가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X40','kor',5,'u1',ARRAY['K5-1-u1-C37']::text[],'배운 것을 실천하는 활동은 정해진 한 가지뿐이라고 여긴다','반에서 함께 정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X41','kor',5,'u1',ARRAY['K5-1-u1-C39']::text[],'글자가 같으면 소리의 길이도 같다고 여겨 장단으로 뜻이 갈리는 줄 모른다','길이에 따라 뜻이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u1-X42','kor',5,'u1',ARRAY['K5-1-u1-C40']::text[],'문장 속 뜻을 보지 않고 짧은소리와 긴소리를 거꾸로 고른다','뜻을 먼저 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#1','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C1',1,'mc','auto','「배려하며 대화한다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X01','K5-1-u1-X02','K5-1-u1-X30']::text[],false,'{"seq":1,"concept":"K5-1-u1-C1","difficulty":1,"kind":"mc","stem":"「배려하며 대화한다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"상대의 처지에서 생각하고 그 마음에 맞게 말과 태도를 고르는 것","correct":true},{"t":"듣기 좋은 말을 예쁘게 꾸며 많이 하는 것","mis":"K5-1-u1-X01"},{"t":"대화에서 내 생각을 끝까지 밀고 나가는 것","mis":"K5-1-u1-X02"},{"t":"상대가 말하지 않은 비밀을 알아내는 것","mis":"K5-1-u1-X30"}],"explanation":["꾸미는 기술이 아니에요.","이기려는 대화가 아니에요.","상대의 처지에서 말과 태도를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#2','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C1',1,'mc','auto','도현이가 아무 말도 하지 못한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X04']::text[],false,'{"seq":2,"concept":"K5-1-u1-C1","difficulty":1,"kind":"mc","stem":"도현이가 아무 말도 하지 못한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"유나가 아픈 마음을 헤아리지 않고 말했기 때문이다","correct":true},{"t":"유나의 목소리가 너무 컸기 때문이다","mis":"K5-1-u1-X04"},{"t":"도현이가 피구를 하기 싫었기 때문이다","mis":"K5-1-u1-X04"},{"t":"도현이는 원래 말수가 적기 때문이다","mis":"K5-1-u1-X04"}],"explanation":["대화에 목소리 이야기는 없어요.","피구 이야기는 유나가 꺼냈어요.","아픈 마음을 탓하는 말로 받았어요."],"asset":{"type":"speech","turns":[{"who":"도현","text":"어제 줄넘기를 하다가 넘어져서 무릎이 까졌어. 아직도 쓰라려."},{"who":"유나","text":"(딴 곳을 보며) 그러게 조심 좀 하지. 난 오늘 피구 하러 갈 건데 넌 못 하겠네."},{"who":"도현","text":"……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#3','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C2',1,'ox','auto','상대를 배려하며 대화하면 대화를 더 빨리 끝낼 수 있어서 좋아요.',ARRAY['K5-1-u1-X02']::text[],false,'{"seq":3,"concept":"K5-1-u1-C2","difficulty":1,"kind":"ox","stem":"상대를 배려하며 대화하면 대화를 더 빨리 끝낼 수 있어서 좋아요.","answer":"X","reason_options":[{"t":"배려는 서로 기분이 상하지 않고 대화를 이어 가게 해 주기 때문에","correct":true},{"t":"배려하면 말을 적게 해도 되기 때문에","mis":"K5-1-u1-X02"}],"mis":"K5-1-u1-X02","explanation":["빨리 끝내려는 것이 아니에요.","말의 양과도 관계없어요.","대화를 기분 좋게 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#4','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C4',1,'sa','auto','어떤 일을 풀 수 있는 실마리를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u1-C4","difficulty":1,"kind":"sa","stem":"어떤 일을 풀 수 있는 실마리를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["단서"],"explanation":["짐작에는 근거가 있어요.","그 근거를 이르는 말이에요.","단서는 어떤 일을 풀 수 있는 실마리예요."],"mis":"K5-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#5','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C3',2,'mc','auto','서준이의 첫 말에서 생략된 내용은 무엇인가요?',ARRAY['K5-1-u1-X03','K5-1-u1-X04']::text[],false,'{"seq":5,"concept":"K5-1-u1-C3","difficulty":2,"kind":"mc","stem":"서준이의 첫 말에서 생략된 내용은 무엇인가요?","options":[{"t":"급식실에 늦게 간 까닭","correct":true},{"t":"함께 간 친구의 이름","mis":"K5-1-u1-X03"},{"t":"급식실이 있는 곳","mis":"K5-1-u1-X03"},{"t":"하린이가 물어본 까닭","mis":"K5-1-u1-X04"}],"explanation":["친구 이야기는 묻지 않았어요.","급식실 위치는 서로 알아요.","하린이가 「왜 늦게 갔어?」라고 되물었어요."],"asset":{"type":"speech","turns":[{"who":"서준","text":"오늘 급식실에 늦게 갔어."},{"who":"하린","text":"어? 그런데 왜 늦게 갔어?"},{"who":"서준","text":"청소 당번이었거든. 교실 정리를 다 하고 나서야 갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#6','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C3',2,'mc','auto','대화에서 생략된 내용이 생기는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X03','K5-1-u1-X30']::text[],false,'{"seq":6,"concept":"K5-1-u1-C3","difficulty":2,"kind":"mc","stem":"대화에서 생략된 내용이 생기는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 알고 있다고 여기는 부분은 줄여서 말하기 때문이다","correct":true},{"t":"대화를 잘 못하는 사람만 말을 빼먹기 때문이다","mis":"K5-1-u1-X03"},{"t":"글로 적지 않은 말은 모두 생략된 것이기 때문이다","mis":"K5-1-u1-X03"},{"t":"모든 말에는 숨은 뜻이 있기 때문이다","mis":"K5-1-u1-X30"}],"explanation":["누구나 줄여서 말해요.","말로 한 것은 생략이 아니에요.","아는 것을 다 말하지 않아서 빈 곳이 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#7','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C22',2,'match','auto','친구가 짐작한 내용과 짐작한 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-1-u1-C22","difficulty":2,"kind":"match","stem":"친구가 짐작한 내용과 짐작한 방법을 알맞게 이으세요.","pairs":[{"l":"몹시 급한 일이 있나 보다","r":"숨을 몰아쉬며 빨리 말한 것을 듣고"},{"l":"어제 늦게 잤나 보다","r":"하품하는 행동을 보고"},{"l":"우산이 없어서 그러나 보다","r":"비가 쏟아지는 상황을 보고"}],"mis":"K5-1-u1-X25","explanation":["들은 말이 단서예요.","본 행동이 단서예요.","그때의 상황도 단서가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#8','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C2',2,'mc','auto','상대를 배려하며 대화하면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X02']::text[],false,'{"seq":8,"concept":"K5-1-u1-C2","difficulty":2,"kind":"mc","stem":"상대를 배려하며 대화하면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 기분이 상하지 않고 대화를 이어 갈 수 있다","correct":true},{"t":"대화에서 이길 수 있다","mis":"K5-1-u1-X02"},{"t":"대화를 훨씬 짧게 끝낼 수 있다","mis":"K5-1-u1-X02"},{"t":"상대가 내 말을 무조건 따르게 된다","mis":"K5-1-u1-X02"}],"explanation":["이기고 지는 대화가 아니에요.","짧게 끝내려는 것이 아니에요.","관계를 지키며 대화를 이어 가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#9','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C1',2,'error','auto','유나의 말과 태도를 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X08','K5-1-u1-X10']::text[],false,'{"seq":9,"concept":"K5-1-u1-C1","difficulty":2,"kind":"error","stem":"유나의 말과 태도를 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「유나는 말이 짧아서 배려하지 않은 것이다.」","correct":true,"mis_target":"K5-1-u1-X11"},{"t":"「아픈 마음을 헤아리지 않고 잘못을 먼저 탓했다.」","mis":"K5-1-u1-X08"},{"t":"「딴 곳을 보며 말해 마음이 전해지지 않았다.」","mis":"K5-1-u1-X10"}],"explanation":["잘못을 먼저 탓했어요.","딴 곳을 본 태도도 문제예요.","말의 길이가 문제가 아니라 마음을 헤아리지 않은 것이 문제예요."],"asset":{"type":"speech","turns":[{"who":"도현","text":"어제 줄넘기를 하다가 넘어져서 무릎이 까졌어. 아직도 쓰라려."},{"who":"유나","text":"(딴 곳을 보며) 그러게 조심 좀 하지. 난 오늘 피구 하러 갈 건데 넌 못 하겠네."},{"who":"도현","text":"……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_basic#10','kor',5,1,'u1','L01','g5_1_kor_u1_L01_basic','lesson_basic','K5-1-u1-C5',3,'mc','auto','이 단원에서 배우는 두 가지가 함께 갖추어져야 하는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X05']::text[],false,'{"seq":10,"concept":"K5-1-u1-C5","difficulty":3,"kind":"mc","stem":"이 단원에서 배우는 두 가지가 함께 갖추어져야 하는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"배려해야 상대의 말과 행동을 눈여겨보게 되고, 그래야 말하지 않은 마음도 짐작할 수 있기 때문이다","correct":true},{"t":"두 가지는 서로 다른 때에만 쓰기 때문이다","mis":"K5-1-u1-X05"},{"t":"짐작만 잘하면 배려는 하지 않아도 되기 때문이다","mis":"K5-1-u1-X05"},{"t":"배려하면 짐작할 필요가 없어지기 때문이다","mis":"K5-1-u1-X05"}],"explanation":["함께 쓰여요.","짐작만으로는 마음이 다쳐요.","두 가지가 함께여야 대화가 오가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#1','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C4',2,'mc','auto','「짐작에는 늘 근거가 있다」에서 근거가 되는 것은 어느 것인가요?',ARRAY['K5-1-u1-X04','K5-1-u1-X26']::text[],false,'{"seq":1,"concept":"K5-1-u1-C4","difficulty":2,"kind":"mc","stem":"「짐작에는 늘 근거가 있다」에서 근거가 되는 것은 어느 것인가요?","options":[{"t":"말 · 행동 · 경험과 배경지식 · 상황 같은 단서","correct":true},{"t":"그냥 드는 느낌","mis":"K5-1-u1-X04"},{"t":"친구들이 가장 많이 고른 생각","mis":"K5-1-u1-X26"},{"t":"내가 바라는 대로의 결과","mis":"K5-1-u1-X04"}],"explanation":["느낌은 근거가 아니에요.","많이 골랐다고 근거가 되지는 않아요.","단서가 짐작의 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#2','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C3',2,'ox','auto','말에 드러나지 않은 부분은 대화에서 아무 뜻이 없어요.',ARRAY['K5-1-u1-X03']::text[],false,'{"seq":2,"concept":"K5-1-u1-C3","difficulty":2,"kind":"ox","stem":"말에 드러나지 않은 부분은 대화에서 아무 뜻이 없어요.","answer":"X","reason_options":[{"t":"서로 안다고 여겨 줄인 부분에 중요한 내용이 담기기도 하기 때문에","correct":true},{"t":"말한 것만이 대화의 전부이기 때문에","mis":"K5-1-u1-X03"}],"mis":"K5-1-u1-X03","explanation":["빈 곳에도 뜻이 있어요.","서준이의 첫 말에도 까닭이 빠져 있었어요.","생략된 내용을 짐작하며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#3','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C1',3,'mc','auto','유나가 배려하며 대답했다면 어떤 말이 알맞았을까요?',ARRAY['K5-1-u1-X08','K5-1-u1-X13','K5-1-u1-X01']::text[],false,'{"seq":3,"concept":"K5-1-u1-C1","difficulty":3,"kind":"mc","stem":"유나가 배려하며 대답했다면 어떤 말이 알맞았을까요?","options":[{"t":"「많이 아팠겠다. 오늘은 무리하지 말고 쉬어. 준비물 챙기는 것 도와줄까?」","correct":true},{"t":"「그러니까 조심했어야지. 다음엔 넘어지지 마.」","mis":"K5-1-u1-X08"},{"t":"(공책을 보며) 「아, 그래. 아프겠다.」","mis":"K5-1-u1-X13"},{"t":"「나도 저번에 넘어졌는데 나는 하나도 안 아팠어.」","mis":"K5-1-u1-X01"}],"explanation":["여전히 잘못을 탓해요.","딴 곳을 보는 말은 마음이 전해지지 않아요.","아픈 마음을 헤아리고 도울 방법을 보태요."],"asset":{"type":"speech","turns":[{"who":"도현","text":"어제 줄넘기를 하다가 넘어져서 무릎이 까졌어. 아직도 쓰라려."},{"who":"유나","text":"(딴 곳을 보며) 그러게 조심 좀 하지. 난 오늘 피구 하러 갈 건데 넌 못 하겠네."},{"who":"도현","text":"……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#4','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C3',3,'mc','auto','대화에서 생략된 내용을 짐작하는 힘이 필요한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X30','K5-1-u1-X27']::text[],false,'{"seq":4,"concept":"K5-1-u1-C3","difficulty":3,"kind":"mc","stem":"대화에서 생략된 내용을 짐작하는 힘이 필요한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리는 아는 것을 모두 말하지 않아 빠진 내용을 채워야 서로 이해할 수 있기 때문이다","correct":true},{"t":"상대의 비밀을 알아내야 하기 때문이다","mis":"K5-1-u1-X30"},{"t":"상대가 하는 말은 모두 거짓이기 때문이다","mis":"K5-1-u1-X30"},{"t":"짐작을 하면 상대의 말을 덜 들어도 되기 때문이다","mis":"K5-1-u1-X27"}],"explanation":["비밀을 캐려는 것이 아니에요.","말을 의심하는 것이 아니에요.","빈 곳을 채워 서로 이해해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#5','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C22',3,'mc','auto','비가 쏟아지는 것을 보고 「친구가 우산이 없어서 저러나 보다」라고 짐작했어요. 이때 쓴 단서는 어느 것인가요?',ARRAY['K5-1-u1-X25','K5-1-u1-X04']::text[],false,'{"seq":5,"concept":"K5-1-u1-C22","difficulty":3,"kind":"mc","stem":"비가 쏟아지는 것을 보고 「친구가 우산이 없어서 저러나 보다」라고 짐작했어요. 이때 쓴 단서는 어느 것인가요?","options":[{"t":"그때의 상황","correct":true},{"t":"친구가 한 말","mis":"K5-1-u1-X25"},{"t":"친구의 표정","mis":"K5-1-u1-X25"},{"t":"내가 어제 꾼 꿈","mis":"K5-1-u1-X04"}],"explanation":["친구는 아무 말도 하지 않았어요.","표정 이야기는 없어요.","비가 쏟아지는 상황을 보았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#6','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C2',3,'error','auto','배려하며 대화하는 까닭을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X02','K5-1-u1-X01']::text[],false,'{"seq":6,"concept":"K5-1-u1-C2","difficulty":3,"kind":"error","stem":"배려하며 대화하는 까닭을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「배려하면 말다툼에서 이길 수 있으니까.」","correct":true,"mis_target":"K5-1-u1-X02"},{"t":"「상대의 마음이 다치지 않게 하려고.」","mis":"K5-1-u1-X01"},{"t":"「대화를 기분 좋게 이어 가려고.」","mis":"K5-1-u1-X02"}],"explanation":["마음을 지켜요.","대화를 이어 가요.","배려는 이기려는 기술이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#7','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C26',3,'mc','auto','하린이가 「왜 늦게 갔어?」라고 물은 일에서 알 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u1-X30','K5-1-u1-X07','K5-1-u1-X04']::text[],false,'{"seq":7,"concept":"K5-1-u1-C26","difficulty":3,"kind":"mc","stem":"하린이가 「왜 늦게 갔어?」라고 물은 일에서 알 수 있는 것은 어느 것인가요?","options":[{"t":"빠진 내용이 있으면 물어 확인하며 대화를 이어 갈 수 있다","correct":true},{"t":"모든 말에는 숨은 뜻이 있다","mis":"K5-1-u1-X30"},{"t":"묻는 것은 배려가 아니다","mis":"K5-1-u1-X07"},{"t":"서준이가 거짓말을 했다","mis":"K5-1-u1-X04"}],"explanation":["숨은 뜻을 캐려던 게 아니에요.","되묻는 것도 잘 듣는 태도예요.","물어 확인해서 빈 곳을 채웠어요."],"asset":{"type":"speech","turns":[{"who":"서준","text":"오늘 급식실에 늦게 갔어."},{"who":"하린","text":"어? 그런데 왜 늦게 갔어?"},{"who":"서준","text":"청소 당번이었거든. 교실 정리를 다 하고 나서야 갔어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#8','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C22',4,'mc','auto','친구가 교실에 들어오며 「아, 춥다.」 하고 손을 비볐어요. 여러 단서를 함께 써서 짐작한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X27','K5-1-u1-X04']::text[],false,'{"seq":8,"concept":"K5-1-u1-C22","difficulty":4,"kind":"mc","stem":"친구가 교실에 들어오며 「아, 춥다.」 하고 손을 비볐어요. 여러 단서를 함께 써서 짐작한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「춥다고 말하며 손을 비비는 걸 보니, 바람이 찬 길을 걸어왔나 보다.」","correct":true},{"t":"「춥다고 했으니 감기에 걸렸겠다.」","mis":"K5-1-u1-X27"},{"t":"「손을 비비니 손을 다쳤나 보다.」","mis":"K5-1-u1-X04"},{"t":"「나는 안 추우니 친구도 춥지 않을 거야.」","mis":"K5-1-u1-X04"}],"explanation":["드러난 것을 넘어 넘겨짚었어요.","단서와 이어지지 않아요.","말과 행동을 함께 단서로 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#9','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C1',4,'essay','teacher','최근에 친구나 가족과 나눈 대화 하나를 떠올려, 상대를 배려한 점이나 배려하지 못한 점을 쓰고 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u1-C1","difficulty":4,"kind":"essay","stem":"최근에 친구나 가족과 나눈 대화 하나를 떠올려, 상대를 배려한 점이나 배려하지 못한 점을 쓰고 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 어제 동생이 블록 탑이 무너졌다고 울 때 「그거 다시 쌓으면 되잖아.」라고 했다. 동생이 오래 쌓은 탑이라 속상했을 텐데 그 마음을 헤아리지 않고 가볍게 넘겼다. 「오래 쌓았는데 속상하겠다. 같이 다시 쌓을까?」라고 말했으면 좋았겠다.","scoring_points":["대화 장면을 떠올려 썼는가","배려한 점이나 배려하지 못한 점을 썼는가","상대의 마음과 이어 까닭을 썼는가"]},"explanation":["최근 대화를 떠올려요.","상대의 처지에서 다시 봐요.","까닭을 마음과 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L01_challenge#10','kor',5,1,'u1','L01','g5_1_kor_u1_L01_challenge','lesson_challenge','K5-1-u1-C5',4,'essay','teacher','「배려하며 대화하기」와 「생략된 내용을 짐작하며 대화하기」가 각각 무엇인지 쓰고, 두 가지가 함께 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u1-C5","difficulty":4,"kind":"essay","stem":"「배려하며 대화하기」와 「생략된 내용을 짐작하며 대화하기」가 각각 무엇인지 쓰고, 두 가지가 함께 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 배려하며 대화하기는 상대의 처지에서 생각하고 그 마음에 맞게 말과 태도를 고르는 것이다. 짐작하며 대화하기는 말 · 행동 · 경험 · 상황을 단서로 말에 드러나지 않은 내용을 채우는 것이다. 상대를 배려해야 말과 행동을 눈여겨보게 되고, 눈여겨보아야 말하지 않은 마음을 짐작할 수 있으므로 두 가지가 함께 갖추어질 때 대화가 오간다.","scoring_points":["배려하며 대화하기의 뜻을 썼는가","짐작하며 대화하기의 뜻을 썼는가","함께 필요한 까닭을 썼는가"]},"explanation":["두 가지 뜻을 떠올려요.","단서를 함께 써요.","서로 돕는 관계로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#1','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C6',1,'mc','auto','지완이가 말을 멈춘 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X04','K5-1-u1-X09']::text[],false,'{"seq":1,"concept":"K5-1-u1-C6","difficulty":1,"kind":"mc","stem":"지완이가 말을 멈춘 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"나경이가 말을 끊고 다른 이야기를 꺼내서","correct":true},{"t":"숙제 이야기가 어려워서","mis":"K5-1-u1-X04"},{"t":"지완이가 원래 말을 짧게 해서","mis":"K5-1-u1-X04"},{"t":"나경이가 목소리를 높여서","mis":"K5-1-u1-X09"}],"explanation":["숙제가 어렵다는 말은 없어요.","지완이는 말을 이어 가려 했어요.","나경이가 필통 이야기로 넘어갔어요."],"asset":{"type":"speech","turns":[{"who":"지완","text":"어제 만들기 숙제를 하다가 풀이 다 굳어서……."},{"who":"나경","text":"(지완이 쪽을 보지 않고 필통을 만지며) 어? 너 필통 새로 샀네? 그거 어디서 샀어?"},{"who":"지완","text":"……."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#2','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C6',1,'mc','auto','배려하며 대화하는 방법에 들지 않는 것은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X08','K5-1-u1-X09']::text[],false,'{"seq":2,"concept":"K5-1-u1-C6","difficulty":1,"kind":"mc","stem":"배려하며 대화하는 방법에 들지 않는 것은 어느 것인가요?","options":[{"t":"내 이야기를 먼저 끝내기","correct":true},{"t":"상대의 말을 집중해서 듣기","mis":"K5-1-u1-X06"},{"t":"상대의 기분을 고려하며 말하기","mis":"K5-1-u1-X08"},{"t":"대화 예절 지키기","mis":"K5-1-u1-X09"}],"explanation":["집중해서 듣기는 배려예요.","기분을 고려하는 것도 배려예요.","내 이야기를 앞세우면 상대가 빠져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#3','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C10',1,'ox','auto','말을 바르게만 하면 딴 곳을 보며 말해도 마음이 전해져요.',ARRAY['K5-1-u1-X10']::text[],false,'{"seq":3,"concept":"K5-1-u1-C10","difficulty":1,"kind":"ox","stem":"말을 바르게만 하면 딴 곳을 보며 말해도 마음이 전해져요.","answer":"X","reason_options":[{"t":"표정과 행동도 말이어서 딴 곳을 보면 마음이 전해지지 않기 때문에","correct":true},{"t":"마음은 말로만 전해지기 때문에","mis":"K5-1-u1-X10"}],"mis":"K5-1-u1-X10","explanation":["태도도 말이에요.","눈을 맞추면 받아들여졌다고 느껴요.","배려는 태도에서 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#4','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C13',1,'match','auto','상황과 그 상황에 어울리는 배려의 말을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u1-C13","difficulty":1,"kind":"match","stem":"상황과 그 상황에 어울리는 배려의 말을 알맞게 이으세요.","pairs":[{"l":"친구가 시험을 못 봐 속상해할 때","r":"많이 아쉬웠겠다. 그동안 애썼잖아."},{"l":"친구가 상을 받아 기뻐할 때","r":"정말 잘됐다. 나도 기분이 좋아."},{"l":"친구가 부탁을 어렵게 꺼낼 때","r":"편하게 말해도 돼. 무슨 일인데?"}],"mis":"K5-1-u1-X14","explanation":["속상할 땐 마음을 알아줘요.","기쁠 땐 함께 기뻐해요.","어려워할 땐 편하게 해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#5','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C7',2,'mc','auto','나경이가 「아, 그래서 어떻게 했어? 계속 말해 봐.」라고 한 말이 좋은 까닭은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X02','K5-1-u1-X08']::text[],false,'{"seq":5,"concept":"K5-1-u1-C7","difficulty":2,"kind":"mc","stem":"나경이가 「아, 그래서 어떻게 했어? 계속 말해 봐.」라고 한 말이 좋은 까닭은 어느 것인가요?","options":[{"t":"지완이가 하던 말을 이어서 할 수 있게 되물었기 때문이다","correct":true},{"t":"나경이가 자기 이야기를 꺼냈기 때문이다","mis":"K5-1-u1-X06"},{"t":"대화를 빨리 끝냈기 때문이다","mis":"K5-1-u1-X02"},{"t":"지완이의 잘못을 짚어 주었기 때문이다","mis":"K5-1-u1-X08"}],"explanation":["자기 이야기는 꺼내지 않았어요.","오히려 대화가 이어졌어요.","되묻기로 말할 길을 열어 주었어요."],"asset":{"type":"speech","turns":[{"who":"지완","text":"어제 만들기 숙제를 하다가 풀이 다 굳어서……."},{"who":"나경","text":"(지완이를 바라보며 고개를 끄덕이고) 아, 그래서 어떻게 했어? 계속 말해 봐."},{"who":"지완","text":"밤늦게까지 다시 붙였는데, 그래도 다 못 끝냈어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#6','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C8',2,'mc','auto','태윤이가 대답 ㉯를 듣고 고마워한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X02','K5-1-u1-X08']::text[],false,'{"seq":6,"concept":"K5-1-u1-C8","difficulty":2,"kind":"mc","stem":"태윤이가 대답 ㉯를 듣고 고마워한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"실수를 탓하지 않고 마음을 헤아려 주어서","correct":true},{"t":"서아가 리코더를 더 잘 불어서","mis":"K5-1-u1-X02"},{"t":"대답을 빨리 해 주어서","mis":"K5-1-u1-X02"},{"t":"서아가 바쁘다고 솔직하게 말해서","mis":"K5-1-u1-X08"}],"explanation":["잘 부는 것과는 관계없어요.","빠르기 때문이 아니에요.","같은 경험을 나누며 탓하지 않았어요."],"asset":{"type":"passage","lines":["태윤 — 「리코더 운지가 자꾸 틀려. 좀 알려 줄 수 있어?」","서아의 대답 ㉮ — 「그걸 아직도 못 해? 난 지금 바빠.」","서아의 대답 ㉯ — 「나도 처음에는 계속 틀렸어. 여기 손가락부터 같이 해 볼까?」"],"title":"도움을 부탁하는 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#7','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C11',2,'ox','auto','배려하며 대화하는 방법은 네 가지뿐이라서 그대로 외워 써야 해요.',ARRAY['K5-1-u1-X12']::text[],false,'{"seq":7,"concept":"K5-1-u1-C11","difficulty":2,"kind":"ox","stem":"배려하며 대화하는 방법은 네 가지뿐이라서 그대로 외워 써야 해요.","answer":"X","reason_options":[{"t":"상황과 상대에 따라 배려하는 방법이 달라지고 내가 찾은 방법도 배려이기 때문에","correct":true},{"t":"정해진 방법을 따라야 실수가 없기 때문에","mis":"K5-1-u1-X12"}],"mis":"K5-1-u1-X12","explanation":["외울 공식이 아니에요.","상황마다 달라져요.","중요한 것은 상대를 향한 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#8','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C14',2,'mc','auto','다율이의 말에서 고칠 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X10','K5-1-u1-X15']::text[],false,'{"seq":8,"concept":"K5-1-u1-C14","difficulty":2,"kind":"mc","stem":"다율이의 말에서 고칠 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"위로가 필요한 때에 까닭을 따지고 속상한 마음을 가볍게 넘겼다","correct":true},{"t":"말이 너무 길어서 은우가 지루했다","mis":"K5-1-u1-X11"},{"t":"목소리가 작아서 들리지 않았다","mis":"K5-1-u1-X10"},{"t":"다음에 잘하라고 해서 은우가 신났다","mis":"K5-1-u1-X15"}],"explanation":["말은 오히려 짧았어요.","목소리 이야기는 없어요.","속상한 마음을 먼저 받아 주지 않았어요."],"asset":{"type":"speech","turns":[{"who":"은우","text":"달리기 대회에서 넘어져서 너무 속상해. 한 달이나 연습했는데."},{"who":"다율","text":"연습을 덜 했나 보지. 다음에 잘하면 되잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#9','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C9',2,'mc','auto','대화 예절을 지킨 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X09']::text[],false,'{"seq":9,"concept":"K5-1-u1-C9","difficulty":2,"kind":"mc","stem":"대화 예절을 지킨 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구가 말을 마칠 때까지 기다렸다가 차례를 지켜 말한다","correct":true},{"t":"친구 말이 길면 중간에 끼어들어 정리해 준다","mis":"K5-1-u1-X06"},{"t":"친한 사이니까 놀리는 말을 섞어 말한다","mis":"K5-1-u1-X09"},{"t":"마음만 있으면 말씨는 아무래도 괜찮다고 여긴다","mis":"K5-1-u1-X09"}],"explanation":["끼어들면 말이 끊겨요.","놀리는 말은 마음을 다치게 해요.","차례를 지키고 바른 말씨를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_basic#10','kor',5,1,'u1','L02','g5_1_kor_u1_L02_basic','lesson_basic','K5-1-u1-C12',3,'mc','auto','두 말 가운데 「진심이 담긴 말」이 상대에게 더 잘 전해지는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X13','K5-1-u1-X10']::text[],false,'{"seq":10,"concept":"K5-1-u1-C12","difficulty":3,"kind":"mc","stem":"두 말 가운데 「진심이 담긴 말」이 상대에게 더 잘 전해지는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하던 일을 멈추고 바라보며 상대의 처지를 실제로 생각했기 때문이다","correct":true},{"t":"말이 더 길기 때문이다","mis":"K5-1-u1-X11"},{"t":"「힘들었겠다」라는 낱말을 썼기 때문이다","mis":"K5-1-u1-X13"},{"t":"휴대 전화로 더 빨리 답했기 때문이다","mis":"K5-1-u1-X10"}],"explanation":["길이 때문이 아니에요.","같은 낱말도 마음이 없으면 전해지지 않아요.","흉내보다 진심이 먼저예요."],"asset":{"type":"passage","lines":["형식만 갖춘 말 — (휴대 전화를 보며) 「아, 그렇구나. 힘들었겠다.」","진심이 담긴 말 — (하던 일을 멈추고 바라보며) 「그랬구나. 언제부터 그랬어?」"],"title":"같은 위로, 다른 말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#1','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C10',2,'mc','auto','배려가 드러나는 모습을 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X10','K5-1-u1-X07']::text[],false,'{"seq":1,"concept":"K5-1-u1-C10","difficulty":2,"kind":"mc","stem":"배려가 드러나는 모습을 바르게 말한 것은 어느 것인가요?","options":[{"t":"말수가 적어도 눈을 맞추고 고개를 끄덕이면 상대는 말이 받아들여졌다고 느낀다","correct":true},{"t":"배려는 말을 많이 해 줄수록 커진다","mis":"K5-1-u1-X11"},{"t":"표정은 대화와 관계가 없다","mis":"K5-1-u1-X10"},{"t":"듣는 사람은 가만히만 있으면 된다","mis":"K5-1-u1-X07"}],"explanation":["말의 양이 아니에요.","표정도 말이에요.","태도에서 배려가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#2','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C7',2,'ox','auto','잘 듣는다는 것은 아무 반응 없이 가만히 있는 거예요.',ARRAY['K5-1-u1-X07']::text[],false,'{"seq":2,"concept":"K5-1-u1-C7","difficulty":2,"kind":"ox","stem":"잘 듣는다는 것은 아무 반응 없이 가만히 있는 거예요.","answer":"X","reason_options":[{"t":"이어서 말하도록 되묻거나 고개를 끄덕이는 반응도 잘 듣는 태도이기 때문에","correct":true},{"t":"듣는 사람이 말을 하면 끼어드는 것이기 때문에","mis":"K5-1-u1-X07"}],"mis":"K5-1-u1-X07","explanation":["되묻기는 끼어들기와 달라요.","끄덕임도 듣고 있다는 신호예요.","반응하며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#3','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C14',3,'mc','auto','다율이의 말을 배려하는 말로 알맞게 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u1-X08','K5-1-u1-X15']::text[],false,'{"seq":3,"concept":"K5-1-u1-C14","difficulty":3,"kind":"mc","stem":"다율이의 말을 배려하는 말로 알맞게 바꾼 것은 어느 것인가요?","options":[{"t":"「많이 속상했겠다. 넘어진 데는 괜찮아? 한 달이나 준비했는데 아쉽겠어.」","correct":true},{"t":"「그래도 넌 원래 느리잖아.」","mis":"K5-1-u1-X08"},{"t":"「그 얘기는 그만하고 놀자.」","mis":"K5-1-u1-X15"},{"t":"「연습을 덜 했나 보지.」","mis":"K5-1-u1-X15"}],"explanation":["탓하는 말이에요.","마음을 가볍게 넘겨요.","마음을 먼저 받아 주고 걱정해 주었어요."],"asset":{"type":"speech","turns":[{"who":"은우","text":"달리기 대회에서 넘어져서 너무 속상해. 한 달이나 연습했는데."},{"who":"다율","text":"연습을 덜 했나 보지. 다음에 잘하면 되잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#4','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C13',3,'mc','auto','친구가 오래 연습한 줄넘기를 처음으로 백 번 넘게 했다며 기뻐해요. 알맞은 말은 어느 것인가요?',ARRAY['K5-1-u1-X14','K5-1-u1-X08']::text[],false,'{"seq":4,"concept":"K5-1-u1-C13","difficulty":3,"kind":"mc","stem":"친구가 오래 연습한 줄넘기를 처음으로 백 번 넘게 했다며 기뻐해요. 알맞은 말은 어느 것인가요?","options":[{"t":"「정말 잘됐다. 그동안 애쓴 보람이 있네!」","correct":true},{"t":"「많이 아쉬웠겠다.」","mis":"K5-1-u1-X14"},{"t":"「나는 이백 번도 해.」","mis":"K5-1-u1-X08"},{"t":"「편하게 말해도 돼. 무슨 일인데?」","mis":"K5-1-u1-X14"}],"explanation":["기쁜 친구에게 위로는 어울리지 않아요.","내 자랑을 앞세웠어요.","함께 기뻐해 주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#5','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C12',3,'error','auto','배려를 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X13','K5-1-u1-X01']::text[],false,'{"seq":5,"concept":"K5-1-u1-C12","difficulty":3,"kind":"error","stem":"배려를 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「배려하는 말투와 표정만 잘 흉내 내면 마음이 없어도 괜찮아.」","correct":true,"mis_target":"K5-1-u1-X13"},{"t":"「같은 말이라도 마음이 없으면 상대가 알아채.」","mis":"K5-1-u1-X13"},{"t":"「상대의 처지를 실제로 생각해 보는 게 먼저야.」","mis":"K5-1-u1-X01"}],"explanation":["상대는 알아채요.","처지를 생각하는 게 먼저예요.","흉내만으로는 배려가 전해지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#6','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C11',3,'mc','auto','「배려에는 정해진 공식이 없다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X09','K5-1-u1-X12']::text[],false,'{"seq":6,"concept":"K5-1-u1-C11","difficulty":3,"kind":"mc","stem":"「배려에는 정해진 공식이 없다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"상황과 상대에 따라 배려하는 방법이 달라지므로 내가 찾은 방법도 배려가 될 수 있다","correct":true},{"t":"배려는 아무렇게나 해도 된다","mis":"K5-1-u1-X09"},{"t":"네 가지 방법을 외워 차례대로 쓰면 된다","mis":"K5-1-u1-X12"},{"t":"배려하는 방법은 아무도 알 수 없다","mis":"K5-1-u1-X12"}],"explanation":["예절은 지켜요.","외울 공식이 아니에요.","상대를 향한 마음에서 방법을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#7','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C8',3,'mc','auto','서아가 대답 ㉯에서 「나도 처음에는 계속 틀렸어」라고 먼저 말한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X08','K5-1-u1-X02']::text[],false,'{"seq":7,"concept":"K5-1-u1-C8","difficulty":3,"kind":"mc","stem":"서아가 대답 ㉯에서 「나도 처음에는 계속 틀렸어」라고 먼저 말한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"태윤이가 부끄럽지 않도록 같은 처지였던 경험을 나누려고","correct":true},{"t":"자기가 더 잘한다는 것을 알리려고","mis":"K5-1-u1-X08"},{"t":"대화를 빨리 끝내려고","mis":"K5-1-u1-X02"},{"t":"태윤이의 실수를 짚어 주려고","mis":"K5-1-u1-X08"}],"explanation":["자랑하려는 말이 아니에요.","오히려 함께 해 보자고 했어요.","경험을 나누어 마음을 헤아렸어요."],"asset":{"type":"passage","lines":["태윤 — 「리코더 운지가 자꾸 틀려. 좀 알려 줄 수 있어?」","서아의 대답 ㉮ — 「그걸 아직도 못 해? 난 지금 바빠.」","서아의 대답 ㉯ — 「나도 처음에는 계속 틀렸어. 여기 손가락부터 같이 해 볼까?」"],"title":"도움을 부탁하는 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#8','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C14',4,'mc','auto','「준비물을 또 안 가져왔어? 너는 늘 그러더라.」를 배려하는 말로 바꾼 것 가운데 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X08','K5-1-u1-X13']::text[],false,'{"seq":8,"concept":"K5-1-u1-C14","difficulty":4,"kind":"mc","stem":"「준비물을 또 안 가져왔어? 너는 늘 그러더라.」를 배려하는 말로 바꾼 것 가운데 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「준비물을 못 챙겨 와서 당황했겠다. 내 것 같이 쓸래?」","correct":true},{"t":"「다음부터는 꼭 챙겨 와. 알겠지?」","mis":"K5-1-u1-X08"},{"t":"(책을 보며) 「아, 그렇구나. 괜찮아.」","mis":"K5-1-u1-X13"},{"t":"「너는 늘 그러니까 이제 익숙해.」","mis":"K5-1-u1-X08"}],"explanation":["여전히 잘못을 짚어요.","딴 곳을 보는 말은 전해지지 않아요.","마음을 먼저 헤아리고 도울 방법을 보탰어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#9','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C14',4,'essay','teacher','형의 말을 배려하는 말로 바꾸어 쓰고, 배려하며 대화하는 방법 가운데 무엇을 썼는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u1-C14","difficulty":4,"kind":"essay","stem":"형의 말을 배려하는 말로 바꾸어 쓰고, 배려하며 대화하는 방법 가운데 무엇을 썼는지 쓰세요.","answer_guide":{"answer":"예: 「종이비행기가 자꾸 떨어져서 속상했겠다. 날개 끝을 조금 접어 보면 어떨까? 같이 해 보자.」 상대의 기분을 고려하며 말하기를 썼다. 탓하지 않고 속상한 마음을 먼저 알아준 뒤 도울 방법을 보탰다.","scoring_points":["탓하는 말을 마음 받아 주는 말로 바꾸었는가","도울 방법을 보탰는가","쓴 방법을 밝혔는가"]},"explanation":["동생의 마음을 먼저 봐요.","도울 방법을 보태요.","쓴 방법을 밝혀요."],"asset":{"type":"speech","turns":[{"who":"동생","text":"형, 내가 만든 종이비행기가 자꾸 바로 떨어져."},{"who":"형","text":"그것도 못 날려? 그러니까 내가 접어 준다고 했잖아."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L02_challenge#10','kor',5,1,'u1','L02','g5_1_kor_u1_L02_challenge','lesson_challenge','K5-1-u1-C11',4,'essay','teacher','배려하며 대화하는 방법 네 가지 말고 내가 찾은 배려 방법을 한 가지 쓰고, 그것이 왜 배려가 되는지 상대의 마음과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u1-C11","difficulty":4,"kind":"essay","stem":"배려하며 대화하는 방법 네 가지 말고 내가 찾은 배려 방법을 한 가지 쓰고, 그것이 왜 배려가 되는지 상대의 마음과 이어 쓰세요.","answer_guide":{"answer":"예: 친구가 말을 잘 꺼내지 못할 때 재촉하지 않고 기다려 준다. 말하기 어려운 이야기일수록 서두르면 더 말하기 힘들어지는데, 기다려 주면 친구가 편한 만큼 천천히 말할 수 있기 때문이다.","scoring_points":["내가 찾은 방법을 썼는가","상대의 마음과 이어 까닭을 썼는가","상황에 맞는 방법인가"]},"explanation":["정해진 공식은 없어요.","상대의 마음에서 출발해요.","까닭을 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#1','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C15',1,'mc','auto','주제를 정하여 대화할 때 이어지는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X16']::text[],false,'{"seq":1,"concept":"K5-1-u1-C15","difficulty":1,"kind":"mc","stem":"주제를 정하여 대화할 때 이어지는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"준비 → 대화 → 점검","correct":true},{"t":"대화 → 준비 → 점검","mis":"K5-1-u1-X16"},{"t":"점검 → 대화 → 준비","mis":"K5-1-u1-X16"},{"t":"대화만 하고 끝낸다","mis":"K5-1-u1-X16"}],"explanation":["준비가 먼저예요.","점검은 대화 뒤에 해요.","준비하고 대화하고 점검해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#2','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C17',1,'match','auto','하준이가 정리한 내용과 그 항목을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K5-1-u1-C17","difficulty":1,"kind":"match","stem":"하준이가 정리한 내용과 그 항목을 알맞게 이으세요.","pairs":[{"l":"지난 주말에","r":"언제"},{"l":"학교 뒤 텃밭에서","r":"어디에서"},{"l":"두 달 동안 기른 상추를 처음 뜯었다","r":"무슨 일을"},{"l":"뿌듯하고 신기했다","r":"생각이나 느낌"}],"mis":"K5-1-u1-X19","explanation":["때와 곳을 나누어요.","실제로 일어난 일을 찾아요.","그때 든 마음이 생각이나 느낌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#3','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C16',1,'ox','auto','대화 주제는 크고 특별한 일이어야 해요.',ARRAY['K5-1-u1-X17']::text[],false,'{"seq":3,"concept":"K5-1-u1-C16","difficulty":1,"kind":"ox","stem":"대화 주제는 크고 특별한 일이어야 해요.","answer":"X","reason_options":[{"t":"직접 겪은 일이라면 작은 일도 주제가 될 수 있기 때문에","correct":true},{"t":"특별한 일이어야 상대가 들어 주기 때문에","mis":"K5-1-u1-X17"}],"mis":"K5-1-u1-X17","explanation":["작은 일도 괜찮아요.","겪은 일이면 돼요.","다양한 마음을 나누면 대화가 깊어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#4','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C18',1,'mc','auto','하준이의 준비에서 빠진 것은 어느 것인가요?',ARRAY['K5-1-u1-X19']::text[],false,'{"seq":4,"concept":"K5-1-u1-C18","difficulty":1,"kind":"mc","stem":"하준이의 준비에서 빠진 것은 어느 것인가요?","options":[{"t":"그때의 생각이나 느낌","correct":true},{"t":"그 일이 있었던 때","mis":"K5-1-u1-X19"},{"t":"그 일이 있었던 곳","mis":"K5-1-u1-X19"},{"t":"실제로 일어난 일","mis":"K5-1-u1-X19"}],"explanation":["「지난 주말에」가 있어요.","「학교 뒤 텃밭에서」가 있어요.","비어 있는 칸은 생각이나 느낌이에요."],"asset":{"type":"passage","lines":["대화 주제 — 처음으로 상추를 길러 본 일","언제 — 지난 주말에 / 어디에서 — 학교 뒤 텃밭에서","무슨 일을 — 두 달 동안 물을 주며 키운 상추를 처음으로 뜯어서 집에 가져갔다.","　　저녁에 가족이 함께 먹었다.","생각이나 느낌 — ?"],"title":"하준이가 준비한 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#5','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C16',2,'mc','auto','대화 주제로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u1-X17']::text[],false,'{"seq":5,"concept":"K5-1-u1-C16","difficulty":2,"kind":"mc","stem":"대화 주제로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구가 숨기고 싶어 하는 비밀","correct":true},{"t":"동생과 다투고 화해한 일","mis":"K5-1-u1-X17"},{"t":"키우던 화분이 시든 일","mis":"K5-1-u1-X17"},{"t":"처음 자전거를 탄 날","mis":"K5-1-u1-X17"}],"explanation":["다툰 일도 겪은 일이에요.","슬펐던 일도 주제가 돼요.","친구의 비밀은 주제로 삼지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#6','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C19',2,'mc','auto','시우의 말에서 고칠 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X21','K5-1-u1-X16']::text[],false,'{"seq":6,"concept":"K5-1-u1-C19","difficulty":2,"kind":"mc","stem":"시우의 말에서 고칠 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"혼자 주제를 정해 버려 채원이가 대화에서 빠지게 되었다","correct":true},{"t":"주제를 너무 오래 의논했다","mis":"K5-1-u1-X21"},{"t":"채원이의 말을 그대로 따랐다","mis":"K5-1-u1-X21"},{"t":"주제를 정하지 않고 대화를 시작했다","mis":"K5-1-u1-X16"}],"explanation":["의논하지 않았어요.","시우가 혼자 정했어요.","함께 정해야 두 사람이 모두 참여해요."],"asset":{"type":"speech","turns":[{"who":"채원","text":"나는 다른 주제로 이야기하고 싶은데, 같이 정하면 안 될까?"},{"who":"시우","text":"시간도 없는데 그냥 내가 정한 걸로 하자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#7','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C20',2,'mc','auto','채원이가 「물 주는 걸 잊은 날은 없었어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X08','K5-1-u1-X06','K5-1-u1-X22']::text[],false,'{"seq":7,"concept":"K5-1-u1-C20","difficulty":2,"kind":"mc","stem":"채원이가 「물 주는 걸 잊은 날은 없었어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하준이의 이야기를 이어받아 더 듣고 싶어서","correct":true},{"t":"하준이의 잘못을 찾으려고","mis":"K5-1-u1-X08"},{"t":"자기 이야기로 넘어가려고","mis":"K5-1-u1-X06"},{"t":"대화를 빨리 끝내려고","mis":"K5-1-u1-X22"}],"explanation":["탓하려는 물음이 아니에요.","채원이는 하준이 이야기를 이어 갔어요.","이어 묻기는 듣고 있다는 신호예요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"두 달 동안 키운 상추를 처음 뜯어서 저녁에 가족이 같이 먹었어. 내가 기른 걸 먹으니까 뿌듯하더라."},{"who":"채원","text":"두 달이나 돌봤구나. 물 주는 걸 잊은 날은 없었어?"},{"who":"하준","text":"한 번 잊었는데 잎이 축 처져서 얼마나 놀랐는지 몰라."},{"who":"채원","text":"그래서 더 마음이 갔겠다. 나도 다음에 한번 길러 보고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#8','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C18',2,'mc','auto','말할 내용에서 「생각이나 느낌」이 빠지면 이야기는 어떻게 되나요?',ARRAY['K5-1-u1-X20','K5-1-u1-X19']::text[],false,'{"seq":8,"concept":"K5-1-u1-C18","difficulty":2,"kind":"mc","stem":"말할 내용에서 「생각이나 느낌」이 빠지면 이야기는 어떻게 되나요?","options":[{"t":"있었던 일만 늘어놓는 이야기가 된다","correct":true},{"t":"더 재미있는 이야기가 된다","mis":"K5-1-u1-X20"},{"t":"언제 일어난 일인지 알 수 없게 된다","mis":"K5-1-u1-X19"},{"t":"대화가 저절로 길어진다","mis":"K5-1-u1-X20"}],"explanation":["마음이 빠지면 밋밋해져요.","때는 「언제」 칸에 있어요.","그때 든 마음까지 준비해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#9','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C21',2,'mc','auto','대화가 끝난 뒤 친구를 칭찬한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X23','K5-1-u1-X08','K5-1-u1-X22']::text[],false,'{"seq":9,"concept":"K5-1-u1-C21","difficulty":2,"kind":"mc","stem":"대화가 끝난 뒤 친구를 칭찬한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「내 말을 끝까지 들어 줘서 고마웠어.」","correct":true},{"t":"「그냥 다 잘했어.」","mis":"K5-1-u1-X23"},{"t":"「다음엔 말을 좀 줄여.」","mis":"K5-1-u1-X08"},{"t":"「내 이야기가 더 재미있었지?」","mis":"K5-1-u1-X22"}],"explanation":["무엇이 좋았는지 빠졌어요.","칭찬이 아니라 지적이에요.","잘한 점을 짚어 칭찬했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_basic#10','kor',5,1,'u1','L04','g5_1_kor_u1_L04_basic','lesson_basic','K5-1-u1-C20',3,'mc','auto','하준이와 채원이의 대화가 잘 이어진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X22','K5-1-u1-X06','K5-1-u1-X21']::text[],false,'{"seq":10,"concept":"K5-1-u1-C20","difficulty":3,"kind":"mc","stem":"하준이와 채원이의 대화가 잘 이어진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"채원이가 하준이의 말을 이어받아 묻고 마음을 알아주는 말로 반응했기 때문이다","correct":true},{"t":"하준이가 혼자 길게 말했기 때문이다","mis":"K5-1-u1-X22"},{"t":"채원이가 자기 경험만 이야기했기 때문이다","mis":"K5-1-u1-X06"},{"t":"두 사람이 같은 주제를 말없이 따라갔기 때문이다","mis":"K5-1-u1-X21"}],"explanation":["혼자 말한 대화가 아니에요.","채원이는 하준이 이야기를 먼저 들었어요.","이어 묻고 마음을 알아주었어요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"두 달 동안 키운 상추를 처음 뜯어서 저녁에 가족이 같이 먹었어. 내가 기른 걸 먹으니까 뿌듯하더라."},{"who":"채원","text":"두 달이나 돌봤구나. 물 주는 걸 잊은 날은 없었어?"},{"who":"하준","text":"한 번 잊었는데 잎이 축 처져서 얼마나 놀랐는지 몰라."},{"who":"채원","text":"그래서 더 마음이 갔겠다. 나도 다음에 한번 길러 보고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#1','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C16',2,'mc','auto','슬펐던 일이나 화났던 일도 대화 주제가 될 수 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X17','K5-1-u1-X02']::text[],false,'{"seq":1,"concept":"K5-1-u1-C16","difficulty":2,"kind":"mc","stem":"슬펐던 일이나 화났던 일도 대화 주제가 될 수 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"다양한 마음을 나눌수록 대화가 깊어지기 때문이다","correct":true},{"t":"즐거운 일은 이미 다 이야기했기 때문이다","mis":"K5-1-u1-X17"},{"t":"화난 일을 말하면 대화에서 이기기 때문이다","mis":"K5-1-u1-X02"},{"t":"슬픈 일은 짧게 끝낼 수 있기 때문이다","mis":"K5-1-u1-X17"}],"explanation":["즐거운 일만 주제가 되는 것이 아니에요.","이기려는 대화가 아니에요.","여러 마음을 나누어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#2','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C19',2,'ox','auto','먼저 말한 사람이 고른 주제로 정하면 대화가 공평해요.',ARRAY['K5-1-u1-X21']::text[],false,'{"seq":2,"concept":"K5-1-u1-C19","difficulty":2,"kind":"ox","stem":"먼저 말한 사람이 고른 주제로 정하면 대화가 공평해요.","answer":"X","reason_options":[{"t":"서로 의논해 함께 정해야 두 사람이 모두 대화에 참여할 수 있기 때문에","correct":true},{"t":"먼저 말한 사람이 더 하고 싶은 것이기 때문에","mis":"K5-1-u1-X21"}],"mis":"K5-1-u1-X21","explanation":["먼저 말한 사람만의 주제가 돼요.","한 사람이 빠질 수 있어요.","함께 의논해 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#3','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C17',3,'mc','auto','네 항목으로 정리한 것 가운데 항목이 잘못 들어간 것은 어느 것인가요?',ARRAY['K5-1-u1-X19','K5-1-u1-X20']::text[],false,'{"seq":3,"concept":"K5-1-u1-C17","difficulty":3,"kind":"mc","stem":"네 항목으로 정리한 것 가운데 항목이 잘못 들어간 것은 어느 것인가요?","options":[{"t":"어디에서 — 오래 기다린 만큼 기뻤다","correct":true},{"t":"언제 — 지난 방학 첫날","mis":"K5-1-u1-X19"},{"t":"무슨 일을 — 동생과 처음으로 떡볶이를 만들었다","mis":"K5-1-u1-X19"},{"t":"생각이나 느낌 — 맵지만 뿌듯했다","mis":"K5-1-u1-X20"}],"explanation":["때가 알맞게 들어갔어요.","일어난 일이 알맞게 들어갔어요.","「기뻤다」는 생각이나 느낌 칸에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#4','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C15',3,'mc','auto','대화하기 전에 네 항목으로 정리해 두면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X16','K5-1-u1-X22']::text[],false,'{"seq":4,"concept":"K5-1-u1-C15","difficulty":3,"kind":"mc","stem":"대화하기 전에 네 항목으로 정리해 두면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"말할 내용을 빠뜨리지 않고 생각이나 느낌까지 담아 말할 수 있다","correct":true},{"t":"상대의 말을 듣지 않아도 된다","mis":"K5-1-u1-X06"},{"t":"대화를 하지 않고도 점검을 마칠 수 있다","mis":"K5-1-u1-X16"},{"t":"적어 둔 대로만 읽으면 반응할 필요가 없다","mis":"K5-1-u1-X22"}],"explanation":["듣기는 여전히 중요해요.","대화를 해야 점검할 수 있어요.","준비는 빠뜨리지 않으려고 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#5','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C20',3,'error','auto','하준이의 말에 대한 반응이에요. 알맞지 않은 반응은 어느 것인가요?',ARRAY['K5-1-u1-X22']::text[],false,'{"seq":5,"concept":"K5-1-u1-C20","difficulty":3,"kind":"error","stem":"하준이의 말에 대한 반응이에요. 알맞지 않은 반응은 어느 것인가요?","options":[{"t":"「그건 별일 아니네. 내 이야기 먼저 할게.」","correct":true,"mis_target":"K5-1-u1-X22"},{"t":"「두 달이나 돌봤구나.」","mis":"K5-1-u1-X22"},{"t":"「그래서 더 마음이 갔겠다.」","mis":"K5-1-u1-X22"}],"explanation":["이어받아 알아준 말이에요.","마음을 알아준 말이에요.","가볍게 넘기고 내 이야기로 넘어가면 대화가 끊겨요."],"asset":{"type":"speech","turns":[{"who":"하준","text":"두 달 동안 키운 상추를 처음 뜯어서 저녁에 가족이 같이 먹었어. 내가 기른 걸 먹으니까 뿌듯하더라."},{"who":"채원","text":"두 달이나 돌봤구나. 물 주는 걸 잊은 날은 없었어?"},{"who":"하준","text":"한 번 잊었는데 잎이 축 처져서 얼마나 놀랐는지 몰라."},{"who":"채원","text":"그래서 더 마음이 갔겠다. 나도 다음에 한번 길러 보고 싶어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#6','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C21',3,'mc','auto','대화를 잘했는지 스스로 점검할 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u1-X23']::text[],false,'{"seq":6,"concept":"K5-1-u1-C21","difficulty":3,"kind":"mc","stem":"대화를 잘했는지 스스로 점검할 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"친구보다 말을 더 많이 했는가","correct":true},{"t":"상대의 말을 집중해서 들었는가","mis":"K5-1-u1-X23"},{"t":"상대의 기분을 고려하며 말했는가","mis":"K5-1-u1-X23"},{"t":"상황에 어울리는 표정과 행동으로 대화했는가","mis":"K5-1-u1-X23"}],"explanation":["듣기를 점검해요.","기분 고려를 점검해요.","말의 양은 점검할 거리가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#7','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C19',3,'mc','auto','채원이와 시우가 주제를 정할 때 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X21','K5-1-u1-X16']::text[],false,'{"seq":7,"concept":"K5-1-u1-C19","difficulty":3,"kind":"mc","stem":"채원이와 시우가 주제를 정할 때 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「너는 무슨 이야기 하고 싶어? 둘 다 하고 싶은 걸로 정하자.」","correct":true},{"t":"「시간 없으니 내가 정할게.」","mis":"K5-1-u1-X21"},{"t":"(말없이 시우를 따라간다)","mis":"K5-1-u1-X21"},{"t":"「주제는 아무거나 상관없어. 그냥 시작하자.」","mis":"K5-1-u1-X16"}],"explanation":["혼자 정하는 말이에요.","말없이 따르면 한 사람이 빠져요.","서로 묻고 함께 정해요."],"asset":{"type":"speech","turns":[{"who":"채원","text":"나는 다른 주제로 이야기하고 싶은데, 같이 정하면 안 될까?"},{"who":"시우","text":"시간도 없는데 그냥 내가 정한 걸로 하자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#8','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C18',4,'mc','auto','하준이의 준비에서 빈칸을 채울 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X20','K5-1-u1-X19']::text[],false,'{"seq":8,"concept":"K5-1-u1-C18","difficulty":4,"kind":"mc","stem":"하준이의 준비에서 빈칸을 채울 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「내가 기른 상추를 가족이 맛있게 먹어서 뿌듯하고 신기했다.」","correct":true},{"t":"「저녁에 가족이 함께 먹었다.」","mis":"K5-1-u1-X20"},{"t":"「학교 뒤 텃밭에서」","mis":"K5-1-u1-X19"},{"t":"「두 달 동안」","mis":"K5-1-u1-X19"}],"explanation":["있었던 일이에요.","곳을 나타내요.","그때 든 마음을 담았어요."],"asset":{"type":"passage","lines":["대화 주제 — 처음으로 상추를 길러 본 일","언제 — 지난 주말에 / 어디에서 — 학교 뒤 텃밭에서","무슨 일을 — 두 달 동안 물을 주며 키운 상추를 처음으로 뜯어서 집에 가져갔다.","　　저녁에 가족이 함께 먹었다.","생각이나 느낌 — ?"],"title":"하준이가 준비한 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#9','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C17',4,'essay','teacher','내가 겪은 일 하나를 대화 주제로 정해 언제 · 어디에서 · 무슨 일을 · 생각이나 느낌으로 정리해 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u1-C17","difficulty":4,"kind":"essay","stem":"내가 겪은 일 하나를 대화 주제로 정해 언제 · 어디에서 · 무슨 일을 · 생각이나 느낌으로 정리해 쓰세요.","answer_guide":{"answer":"예: 주제 — 강아지를 처음 목욕시킨 일. 언제 — 지난 토요일 저녁에. 어디에서 — 우리 집 욕실에서. 무슨 일을 — 강아지가 물을 싫어해서 이리저리 도망쳐 온 바닥이 젖었다. 생각이나 느낌 — 힘들었지만 보송보송해진 강아지를 안으니 뿌듯했다.","scoring_points":["직접 겪은 일을 주제로 골랐는가","네 항목을 알맞게 채웠는가","생각이나 느낌을 담았는가"]},"explanation":["겪은 일을 골라요.","네 칸을 채워요.","그때 든 마음을 꼭 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L04_challenge#10','kor',5,1,'u1','L04','g5_1_kor_u1_L04_challenge','lesson_challenge','K5-1-u1-C20',4,'essay','teacher','친구가 「어제 처음으로 혼자 김밥을 말아 봤어.」라고 말했어요. 반응하는 말을 두 가지 쓰고, 각각 어떤 점에서 배려가 되는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u1-C20","difficulty":4,"kind":"essay","stem":"친구가 「어제 처음으로 혼자 김밥을 말아 봤어.」라고 말했어요. 반응하는 말을 두 가지 쓰고, 각각 어떤 점에서 배려가 되는지 쓰세요.","answer_guide":{"answer":"예: 「처음인데 잘 말렸어? 어떤 재료를 넣었어?」 — 이야기를 이어받아 더 물어 친구가 계속 말할 수 있게 한다. 「혼자 해냈다니 정말 뿌듯했겠다.」 — 친구의 마음을 알아주어 듣고 있다는 것을 보여 준다.","scoring_points":["반응하는 말을 두 가지 썼는가","이어 묻는 말이나 마음을 알아주는 말인가","배려가 되는 까닭을 썼는가"]},"explanation":["이어받아 물어요.","마음을 알아줘요.","듣고 있다는 신호를 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#1','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C22',1,'mc','auto','생략된 내용을 짐작하는 방법이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u1-X24']::text[],false,'{"seq":1,"concept":"K5-1-u1-C22","difficulty":1,"kind":"mc","stem":"생략된 내용을 짐작하는 방법이 아닌 것은 어느 것인가요?","options":[{"t":"내가 바라는 대로 정하기","correct":true},{"t":"말에서 단서를 확인하기","mis":"K5-1-u1-X24"},{"t":"행동에서 단서를 확인하기","mis":"K5-1-u1-X24"},{"t":"그때의 상황을 고려하기","mis":"K5-1-u1-X24"}],"explanation":["말도 단서예요.","행동도 단서예요.","바람은 단서가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#2','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C22',1,'match','auto','친구의 짐작과 짐작한 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K5-1-u1-C22","difficulty":1,"kind":"match","stem":"친구의 짐작과 짐작한 방법을 알맞게 이으세요.","pairs":[{"l":"은호 — 열쇠를 잃어버렸나 보다","r":"준서의 말에서 단서를 찾아서"},{"l":"하람 — 몹시 급한 일이 있나 보다","r":"숨을 몰아쉬며 뛰어 들어온 행동을 보고"},{"l":"서윤 — 수업 준비 때문일 거야","r":"자신의 경험을 떠올려서"},{"l":"다인 — 곧 체육 시간이라서겠지","r":"그때의 상황을 고려해서"}],"mis":"K5-1-u1-X25","explanation":["들은 말과 본 행동을 나누어요.","서윤이는 「나도 지난번에」라고 했어요.","체육 시간은 상황이에요."],"asset":{"type":"passage","lines":["점심시간, 준서가 숨을 몰아쉬며 교실로 뛰어 들어와 물었다.","「얘들아, 혹시 체육관 열쇠 봤어?」","은호 — 열쇠를 잃어버렸나 보다.","하람 — 몹시 급한 일이 있나 보다.","서윤 — 나도 지난번에 그랬지. 수업 준비 때문일 거야.","다인 — 곧 체육 시간이니 그 때문이겠지."],"title":"체육관 열쇠를 찾는 준서와 네 친구의 짐작"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#3','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C26',1,'ox','auto','단서를 보고 짐작한 내용은 맞는 생각이니 그대로 믿어도 돼요.',ARRAY['K5-1-u1-X29']::text[],false,'{"seq":3,"concept":"K5-1-u1-C26","difficulty":1,"kind":"ox","stem":"단서를 보고 짐작한 내용은 맞는 생각이니 그대로 믿어도 돼요.","answer":"X","reason_options":[{"t":"짐작은 아직 맞는지 모르는 생각이어서 물어 확인해야 하기 때문에","correct":true},{"t":"단서를 보고 짐작했으니 틀릴 수 없기 때문에","mis":"K5-1-u1-X29"}],"mis":"K5-1-u1-X29","explanation":["짐작은 단정이 아니에요.","단서가 있어도 틀릴 수 있어요.","물어 확인하고 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#4','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C22',1,'mc','auto','도담이가 「피곤해 보인다」고 짐작한 단서는 어느 것인가요?',ARRAY['K5-1-u1-X24','K5-1-u1-X25']::text[],false,'{"seq":4,"concept":"K5-1-u1-C22","difficulty":1,"kind":"mc","stem":"도담이가 「피곤해 보인다」고 짐작한 단서는 어느 것인가요?","options":[{"t":"연달아 하품하는 행동","correct":true},{"t":"주말이라는 말","mis":"K5-1-u1-X24"},{"t":"사촌 동생이 왔다는 말","mis":"K5-1-u1-X24"},{"t":"도담이가 어제 늦게 잔 경험","mis":"K5-1-u1-X25"}],"explanation":["주말이라는 말만으로는 알 수 없어요.","사촌 이야기는 짐작한 뒤에 들었어요.","하품이라는 행동을 보았어요."],"asset":{"type":"speech","turns":[{"who":"도담","text":"주말 잘 보냈어?"},{"who":"유월","text":"(연달아 하품을 하며) 응, 뭐……."},{"who":"도담","text":"피곤해 보인다. 잠을 못 잤어?"},{"who":"유월","text":"응, 사촌 동생들이 와서 밤늦게까지 시끄러웠거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#5','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C23',2,'mc','auto','네 친구가 같은 말을 듣고 다르게 짐작한 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X26']::text[],false,'{"seq":5,"concept":"K5-1-u1-C23","difficulty":2,"kind":"mc","stem":"네 친구가 같은 말을 듣고 다르게 짐작한 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"주목한 단서와 떠올린 경험이 달라서","correct":true},{"t":"준서의 말을 제대로 못 들어서","mis":"K5-1-u1-X26"},{"t":"준서에게 관심이 없어서","mis":"K5-1-u1-X26"},{"t":"한 사람만 맞고 나머지는 틀려서","mis":"K5-1-u1-X26"}],"explanation":["모두 같은 말을 들었어요.","관심이 없어서가 아니에요.","무엇을 보고 떠올렸는지가 달랐어요."],"asset":{"type":"passage","lines":["점심시간, 준서가 숨을 몰아쉬며 교실로 뛰어 들어와 물었다.","「얘들아, 혹시 체육관 열쇠 봤어?」","은호 — 열쇠를 잃어버렸나 보다.","하람 — 몹시 급한 일이 있나 보다.","서윤 — 나도 지난번에 그랬지. 수업 준비 때문일 거야.","다인 — 곧 체육 시간이니 그 때문이겠지."],"title":"체육관 열쇠를 찾는 준서와 네 친구의 짐작"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#6','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C24',2,'mc','auto','짐작의 두 걸음 가운데 첫 걸음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X27','K5-1-u1-X26','K5-1-u1-X29']::text[],false,'{"seq":6,"concept":"K5-1-u1-C24","difficulty":2,"kind":"mc","stem":"짐작의 두 걸음 가운데 첫 걸음으로 알맞은 것은 어느 것인가요?","options":[{"t":"실제로 들은 말과 본 행동을 먼저 확인하기","correct":true},{"t":"내 경험과 바로 이어 보기","mis":"K5-1-u1-X27"},{"t":"친구의 짐작을 그대로 따라 하기","mis":"K5-1-u1-X26"},{"t":"짐작한 것을 친구에게 알리기","mis":"K5-1-u1-X29"}],"explanation":["경험과 잇기는 둘째 걸음이에요.","따라 하면 내 짐작이 아니에요.","드러난 것에서 출발해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#7','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C25',2,'mc','auto','대화 ㉮에서 알맞게 짐작한 것은 어느 것인가요?',ARRAY['K5-1-u1-X28']::text[],false,'{"seq":7,"concept":"K5-1-u1-C25","difficulty":2,"kind":"mc","stem":"대화 ㉮에서 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"물놀이를 다녀왔구나","correct":true},{"t":"어제 비가 왔구나","mis":"K5-1-u1-X28"},{"t":"물이 아주 따뜻했구나","mis":"K5-1-u1-X28"},{"t":"수영을 아주 잘하는구나","mis":"K5-1-u1-X28"}],"explanation":["비 이야기는 대화에 없어요.","물이 차다고 했어요.","발끝을 담갔다는 말이 단서예요."],"asset":{"type":"passage","lines":["대화 ㉮ 「어제 잘 다녀왔어?」","　　　 「물이 어찌나 차던지 발끝만 담갔다가 나왔어.」","대화 ㉯ 「오늘 발표는 잘 마쳤니?」","　　　 「그…… 그냥 그랬어요.」"],"title":"두 대화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#8','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C26',2,'mc','auto','생략된 내용을 짐작한 뒤에 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X29']::text[],false,'{"seq":8,"concept":"K5-1-u1-C26","difficulty":2,"kind":"mc","stem":"생략된 내용을 짐작한 뒤에 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"상대에게 물어 확인하고 친구의 생각과 견주어 본다","correct":true},{"t":"짐작한 내용을 사실처럼 알린다","mis":"K5-1-u1-X29"},{"t":"더 묻지 않고 대화를 끝낸다","mis":"K5-1-u1-X29"},{"t":"짐작이 맞을 때까지 혼자 계속 생각한다","mis":"K5-1-u1-X29"}],"explanation":["사실처럼 알리면 오해가 생겨요.","묻지 않으면 확인이 안 돼요.","물어 확인하고 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#9','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C27',2,'mc','auto','생략된 내용을 짐작하며 들어야 하는 때로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X30']::text[],false,'{"seq":9,"concept":"K5-1-u1-C27","difficulty":2,"kind":"mc","stem":"생략된 내용을 짐작하며 들어야 하는 때로 알맞은 것은 어느 것인가요?","options":[{"t":"말과 표정이 어긋날 때","correct":true},{"t":"친구가 「내일 보자」고 인사할 때","mis":"K5-1-u1-X30"},{"t":"선생님께서 숙제를 또렷이 알려 주실 때","mis":"K5-1-u1-X30"},{"t":"모든 말을 들을 때마다","mis":"K5-1-u1-X30"}],"explanation":["말 그대로의 인사예요.","또렷한 말은 그대로 들어요.","말과 표정이 어긋나면 짐작이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_basic#10','kor',5,1,'u1','L06','g5_1_kor_u1_L06_basic','lesson_basic','K5-1-u1-C24',3,'mc','auto','드러난 것을 확인하지 않고 바로 넘겨짚은 짐작은 어느 것인가요?',ARRAY['K5-1-u1-X27']::text[],false,'{"seq":10,"concept":"K5-1-u1-C24","difficulty":3,"kind":"mc","stem":"드러난 것을 확인하지 않고 바로 넘겨짚은 짐작은 어느 것인가요?","options":[{"t":"친구가 「오늘 숙제 했어?」라고 묻자 「나를 의심하는구나」라고 생각한다","correct":true},{"t":"친구가 우산을 털며 들어오는 것을 보고 「밖에 비가 오나 보다」라고 생각한다","mis":"K5-1-u1-X27"},{"t":"친구가 하품하는 것을 보고 「졸린가 보다」라고 생각한다","mis":"K5-1-u1-X27"},{"t":"친구가 숨을 몰아쉬는 것을 보고 「뛰어왔나 보다」라고 생각한다","mis":"K5-1-u1-X27"}],"explanation":["우산을 턴 행동이 단서예요.","하품이 단서예요.","묻는 말 어디에도 의심한다는 단서가 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#1','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C23',2,'mc','auto','「누구의 짐작이 맞았는지보다 무엇을 보고 그렇게 생각했는지가 중요하다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X26','K5-1-u1-X04']::text[],false,'{"seq":1,"concept":"K5-1-u1-C23","difficulty":2,"kind":"mc","stem":"「누구의 짐작이 맞았는지보다 무엇을 보고 그렇게 생각했는지가 중요하다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"짐작은 단서를 따라가는 과정이 중요하다","correct":true},{"t":"짐작은 누가 맞히는지 겨루는 놀이다","mis":"K5-1-u1-X26"},{"t":"나와 다른 짐작은 모두 틀렸다","mis":"K5-1-u1-X26"},{"t":"짐작에는 단서가 없어도 된다","mis":"K5-1-u1-X04"}],"explanation":["겨루기가 아니에요.","다른 짐작도 근거가 있을 수 있어요.","무엇을 보고 생각했는지를 따라가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#2','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C27',2,'ox','auto','친구의 모든 말에는 숨은 뜻이 있으니 늘 짐작하며 들어야 해요.',ARRAY['K5-1-u1-X30']::text[],false,'{"seq":2,"concept":"K5-1-u1-C27","difficulty":2,"kind":"ox","stem":"친구의 모든 말에는 숨은 뜻이 있으니 늘 짐작하며 들어야 해요.","answer":"X","reason_options":[{"t":"대부분의 말은 말한 그대로가 전부이고 아무 말에나 뜻을 붙이면 오해가 되기 때문에","correct":true},{"t":"짐작을 많이 할수록 대화를 잘하는 것이기 때문에","mis":"K5-1-u1-X30"}],"mis":"K5-1-u1-X30","explanation":["대부분은 말 그대로예요.","많이 짐작한다고 잘하는 게 아니에요.","신호가 있을 때 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#3','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C25',3,'mc','auto','대화 ㉯에서 알맞게 짐작한 것을 담은 것은 어느 것인가요?',ARRAY['K5-1-u1-X28']::text[],false,'{"seq":3,"concept":"K5-1-u1-C25","difficulty":3,"kind":"mc","stem":"대화 ㉯에서 알맞게 짐작한 것을 담은 것은 어느 것인가요?","options":[{"t":"발표가 마음에 들지 않았고, 자세히 말하고 싶지 않은 것 같다","correct":true},{"t":"발표를 하지 않은 것 같다","mis":"K5-1-u1-X28"},{"t":"발표가 아주 잘되어 쑥스러운 것 같다","mis":"K5-1-u1-X28"},{"t":"발표 이야기를 듣고 화가 난 것 같다","mis":"K5-1-u1-X28"}],"explanation":["「그냥 그랬어요」는 했다는 말이에요.","잘된 일이라는 근거가 없어요.","머뭇거림과 「그냥」이 단서예요."],"asset":{"type":"passage","lines":["대화 ㉮ 「어제 잘 다녀왔어?」","　　　 「물이 어찌나 차던지 발끝만 담갔다가 나왔어.」","대화 ㉯ 「오늘 발표는 잘 마쳤니?」","　　　 「그…… 그냥 그랬어요.」"],"title":"두 대화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#4','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C26',3,'mc','auto','도담이가 짐작한 뒤 「잠을 못 잤어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X09','K5-1-u1-X29','K5-1-u1-X22']::text[],false,'{"seq":4,"concept":"K5-1-u1-C26","difficulty":3,"kind":"mc","stem":"도담이가 짐작한 뒤 「잠을 못 잤어?」라고 물은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"짐작이 맞는지 상대에게 확인하려고","correct":true},{"t":"유월이를 놀리려고","mis":"K5-1-u1-X09"},{"t":"짐작한 것을 사실로 굳히려고","mis":"K5-1-u1-X29"},{"t":"대화를 끝내려고","mis":"K5-1-u1-X22"}],"explanation":["놀리는 말이 아니에요.","굳히지 않고 물었어요.","물어서 짐작을 확인했어요."],"asset":{"type":"speech","turns":[{"who":"도담","text":"주말 잘 보냈어?"},{"who":"유월","text":"(연달아 하품을 하며) 응, 뭐……."},{"who":"도담","text":"피곤해 보인다. 잠을 못 잤어?"},{"who":"유월","text":"응, 사촌 동생들이 와서 밤늦게까지 시끄러웠거든."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#5','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C27',3,'mc','auto','짐작이 필요하다는 신호가 아닌 것은 어느 것인가요?',ARRAY['K5-1-u1-X30']::text[],false,'{"seq":5,"concept":"K5-1-u1-C27","difficulty":3,"kind":"mc","stem":"짐작이 필요하다는 신호가 아닌 것은 어느 것인가요?","options":[{"t":"말한 그대로 뜻이 또렷한 말","correct":true},{"t":"말이 갑자기 짧아진다","mis":"K5-1-u1-X30"},{"t":"말과 표정이 어긋난다","mis":"K5-1-u1-X30"},{"t":"되물어야 이해된다","mis":"K5-1-u1-X30"}],"explanation":["갑자기 짧아지면 살펴봐요.","어긋나면 살펴봐요.","또렷한 말은 그대로 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#6','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C24',3,'error','auto','짐작하는 과정을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X27','K5-1-u1-X24']::text[],false,'{"seq":6,"concept":"K5-1-u1-C24","difficulty":3,"kind":"error","stem":"짐작하는 과정을 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「드러난 것은 건너뛰고 바로 내 경험으로 넘겨짚으면 돼.」","correct":true,"mis_target":"K5-1-u1-X27"},{"t":"「먼저 실제로 들은 말과 본 행동을 붙잡아.」","mis":"K5-1-u1-X27"},{"t":"「그다음 내 경험이나 그때 상황과 이어 봐.」","mis":"K5-1-u1-X24"}],"explanation":["첫 걸음이에요.","둘째 걸음이에요.","건너뛰면 넘겨짚기가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#7','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C22',3,'mc','auto','친구가 「오늘은 동생 것까지 우산을 두 개나 챙겨 왔어.」라고 말했어요. 생략된 내용을 짐작한 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X28']::text[],false,'{"seq":7,"concept":"K5-1-u1-C22","difficulty":3,"kind":"mc","stem":"친구가 「오늘은 동생 것까지 우산을 두 개나 챙겨 왔어.」라고 말했어요. 생략된 내용을 짐작한 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"오늘 비가 올 것 같아 동생과 함께 쓰려고 챙겼나 보다","correct":true},{"t":"동생이 우산을 싫어하나 보다","mis":"K5-1-u1-X28"},{"t":"비가 오지 않는다는 것을 알았나 보다","mis":"K5-1-u1-X28"},{"t":"우산을 팔려고 가져왔나 보다","mis":"K5-1-u1-X28"}],"explanation":["싫어한다는 단서가 없어요.","우산을 챙긴 것과 맞지 않아요.","「동생 것까지」가 단서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#8','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C23',4,'mc','auto','서윤이의 짐작을 두고 한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X25','K5-1-u1-X26','K5-1-u1-X29']::text[],false,'{"seq":8,"concept":"K5-1-u1-C23","difficulty":4,"kind":"mc","stem":"서윤이의 짐작을 두고 한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「서윤이는 자기 경험을 떠올렸으니, 준서에게 물어 확인하면 좋겠어.」","correct":true},{"t":"「경험은 단서가 아니니 서윤이 짐작은 근거가 없어.」","mis":"K5-1-u1-X25"},{"t":"「서윤이 짐작이 맞으니 다른 친구들은 틀렸어.」","mis":"K5-1-u1-X26"},{"t":"「서윤이처럼 짐작했으면 더 물을 필요 없어.」","mis":"K5-1-u1-X29"}],"explanation":["경험도 짐작의 단서예요.","다른 짐작도 근거가 있어요.","경험으로 짐작하고 물어 확인해요."],"asset":{"type":"passage","lines":["점심시간, 준서가 숨을 몰아쉬며 교실로 뛰어 들어와 물었다.","「얘들아, 혹시 체육관 열쇠 봤어?」","은호 — 열쇠를 잃어버렸나 보다.","하람 — 몹시 급한 일이 있나 보다.","서윤 — 나도 지난번에 그랬지. 수업 준비 때문일 거야.","다인 — 곧 체육 시간이니 그 때문이겠지."],"title":"체육관 열쇠를 찾는 준서와 네 친구의 짐작"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#9','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C22',4,'essay','teacher','친구가 땀에 젖은 채 교실 문을 열고 들어와 시계를 보며 「휴, 다행이다.」라고 했어요. 생략된 내용을 짐작하고, 어떤 단서를 썼는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u1-C22","difficulty":4,"kind":"essay","stem":"친구가 땀에 젖은 채 교실 문을 열고 들어와 시계를 보며 「휴, 다행이다.」라고 했어요. 생략된 내용을 짐작하고, 어떤 단서를 썼는지 쓰세요.","answer_guide":{"answer":"예: 늦을까 봐 뛰어왔는데 수업 시작 전에 도착해서 안심한 것 같다. 땀에 젖은 모습(행동)을 보고 뛰어왔다고 생각했고, 시계를 보는 행동과 「다행이다」라는 말을 듣고 늦지 않아 안심했다고 짐작했다. 아침 시간이라는 상황도 함께 고려했다.","scoring_points":["생략된 내용을 짐작했는가","말 · 행동 · 상황 가운데 쓴 단서를 밝혔는가","단서와 짐작이 이어지는가"]},"explanation":["드러난 것을 먼저 붙잡아요.","단서를 이어 봐요.","무엇을 보고 짐작했는지 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L06_challenge#10','kor',5,1,'u1','L06','g5_1_kor_u1_L06_challenge','lesson_challenge','K5-1-u1-C26',4,'essay','teacher','짐작한 내용을 사실처럼 굳혀 버리면 어떤 일이 생길 수 있는지 예를 들어 쓰고, 그렇게 되지 않으려면 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u1-C26","difficulty":4,"kind":"essay","stem":"짐작한 내용을 사실처럼 굳혀 버리면 어떤 일이 생길 수 있는지 예를 들어 쓰고, 그렇게 되지 않으려면 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 친구가 인사를 받지 않고 지나가서 「나한테 화가 났구나」라고 굳혀 버리면, 나도 그 친구를 피하게 되어 사이가 멀어질 수 있다. 사실은 친구가 나를 보지 못했을 수도 있다. 그러니 짐작한 뒤에는 「아까 나 못 봤어?」처럼 물어 확인하고, 다른 친구의 생각과도 견주어 보아야 한다.","scoring_points":["굳혀 버렸을 때 생길 일을 예로 썼는가","짐작이 틀릴 수 있음을 썼는가","물어 확인하거나 견주는 방법을 썼는가"]},"explanation":["짐작은 아직 모르는 생각이에요.","오해가 생길 수 있어요.","물어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#1','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C28',1,'mc','auto','이야기에 생략된 내용이 있는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X31']::text[],false,'{"seq":1,"concept":"K5-1-u1-C28","difficulty":1,"kind":"mc","stem":"이야기에 생략된 내용이 있는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"글쓴이가 모든 것을 알려 주지 않고 독자가 단서를 모아 채우도록 남겨 두기 때문이다","correct":true},{"t":"글쓴이가 실수로 빼먹었기 때문이다","mis":"K5-1-u1-X31"},{"t":"이야기는 모든 것을 다 알려 주기 때문이다","mis":"K5-1-u1-X31"},{"t":"독자가 읽지 않아도 되는 부분이기 때문이다","mis":"K5-1-u1-X31"}],"explanation":["실수가 아니라 남겨 둔 것이에요.","모든 것을 알려 주지 않아요.","독자가 단서로 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#2','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C29',1,'mc','auto','다온이가 걸음을 멈춘 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X32']::text[],false,'{"seq":2,"concept":"K5-1-u1-C29","difficulty":1,"kind":"mc","stem":"다온이가 걸음을 멈춘 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"자신이 물을 주지 않았는데도 흙이 젖어 있어서","correct":true},{"t":"화분이 시들어 있어서","mis":"K5-1-u1-X32"},{"t":"화분 하나가 사라져서","mis":"K5-1-u1-X32"},{"t":"창틀이 깨져 있어서","mis":"K5-1-u1-X32"}],"explanation":["시들었다는 말은 없어요.","화분은 넷 그대로예요.","화요일에 준 뒤로 젖을 까닭이 없었어요."],"asset":{"type":"passage","lines":["다온이는 이번 학기 화분 당번이다. 창가에 놓인 화분 넷에 물을 준다.","화요일에 물을 주고 금요일에 다시 주는 것이 규칙이었다.","그런데 목요일 아침, 다온이는 걸음을 멈췄다. 흙이 눅눅했다.","손가락을 살짝 눌러 보니 물기가 배어 나왔다.","「내가 준 게 화요일인데…….」","창틀에는 물이 흐른 자국이 가늘게 말라 있었다."],"title":"「젖어 있는 화분」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#3','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C32',1,'ox','auto','이야기에서 모르는 낱말이 나오면 앞뒤 문장을 보지 말고 바로 넘어가요.',ARRAY['K5-1-u1-X35']::text[],false,'{"seq":3,"concept":"K5-1-u1-C32","difficulty":1,"kind":"ox","stem":"이야기에서 모르는 낱말이 나오면 앞뒤 문장을 보지 말고 바로 넘어가요.","answer":"X","reason_options":[{"t":"앞뒤 문장에 그 낱말의 뜻을 알려 주는 단서가 있는 경우가 많기 때문에","correct":true},{"t":"모르는 낱말은 이야기와 관계가 없기 때문에","mis":"K5-1-u1-X35"}],"mis":"K5-1-u1-X35","explanation":["넘기면 뜻을 놓쳐요.","글쓴이가 단서를 남겨 둬요.","앞뒤 문장을 다시 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#4','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C32',1,'mc','auto','「흙이 눅눅했다」에서 「눅눅하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X35']::text[],false,'{"seq":4,"concept":"K5-1-u1-C32","difficulty":1,"kind":"mc","stem":"「흙이 눅눅했다」에서 「눅눅하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"축축한 기운이 있다","correct":true},{"t":"단단하게 굳어 있다","mis":"K5-1-u1-X35"},{"t":"바싹 말라 있다","mis":"K5-1-u1-X35"},{"t":"따뜻하게 데워져 있다","mis":"K5-1-u1-X35"}],"explanation":["굳었다는 단서는 없어요.","물기가 배어 나왔어요.","눌렀더니 물기가 나왔다는 문장이 단서예요."],"asset":{"type":"passage","lines":["다온이는 이번 학기 화분 당번이다. 창가에 놓인 화분 넷에 물을 준다.","화요일에 물을 주고 금요일에 다시 주는 것이 규칙이었다.","그런데 목요일 아침, 다온이는 걸음을 멈췄다. 흙이 눅눅했다.","손가락을 살짝 눌러 보니 물기가 배어 나왔다.","「내가 준 게 화요일인데…….」","창틀에는 물이 흐른 자국이 가늘게 말라 있었다."],"title":"「젖어 있는 화분」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#5','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C29',2,'mc','auto','하율이가 물을 주었다고 볼 수 있는 단서가 아닌 것은 어느 것인가요?',ARRAY['K5-1-u1-X32']::text[],false,'{"seq":5,"concept":"K5-1-u1-C29","difficulty":2,"kind":"mc","stem":"하율이가 물을 주었다고 볼 수 있는 단서가 아닌 것은 어느 것인가요?","options":[{"t":"지난달에 전학 왔다는 사실","correct":true},{"t":"뚜껑이 열린 물병","mis":"K5-1-u1-X32"},{"t":"창가 쪽에 서 있던 모습","mis":"K5-1-u1-X32"},{"t":"물병을 가방 뒤로 민 행동","mis":"K5-1-u1-X32"}],"explanation":["물병이 단서예요.","창가에 화분이 있어요.","전학 온 때는 물 주기와 관계없어요."],"asset":{"type":"passage","lines":["다온이는 다음 날 평소보다 이십 분 일찍 학교에 갔다. 복도는 아직 조용했다.","교실 문을 여니 창가 쪽에서 누군가 고개를 갸웃하고 있었다.","지난달에 전학 온 하율이었다. 하율이의 신발주머니는 이미 사물함에 걸려 있었고,","책상 위에는 뚜껑이 열린 물병이 놓여 있었다.","다온이와 눈이 마주치자 하율이는 물병을 슬그머니 가방 뒤로 밀었다."],"title":"「젖어 있는 화분」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#6','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C30',2,'mc','auto','하율이의 「그냥」에 생략된 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X33']::text[],false,'{"seq":6,"concept":"K5-1-u1-C30","difficulty":2,"kind":"mc","stem":"하율이의 「그냥」에 생략된 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"일찍 온 교실에서 혼자 있기 어색해 화분을 돌보았다는 까닭","correct":true},{"t":"화분 당번을 빼앗고 싶다는 뜻","mis":"K5-1-u1-X33"},{"t":"다온이가 밉다는 마음","mis":"K5-1-u1-X33"},{"t":"정말 아무 까닭도 없다는 뜻","mis":"K5-1-u1-X33"}],"explanation":["빼앗으려는 단서가 없어요.","미워한다는 단서가 없어요.","늘 먼저 오고 아무와도 말하지 않았다는 부분이 단서예요."],"asset":{"type":"passage","lines":["다온 「혹시… 네가 화분에 물 줬어?」　하율 「…응.」","다온 「왜? 당번은 난데.」","하율 「그냥.」 (손끝으로 책상 모서리를 문지른다.)","하율이는 더 말하지 않았다. 다온이는 「그냥」이라는 말을 오래 곱씹었다.","하율이는 늘 교실에 가장 먼저 왔다.","그리고 아무와도 말하지 않은 채 제 책상에 앉아 있었다."],"title":"「젖어 있는 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#7','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C30',2,'match','auto','이야기 속 장면과 그 장면에서 짐작할 수 있는 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K5-1-u1-C30","difficulty":2,"kind":"match","stem":"이야기 속 장면과 그 장면에서 짐작할 수 있는 내용을 알맞게 이으세요.","pairs":[{"l":"물병을 가방 뒤로 밀었다","r":"들키고 싶지 않았다"},{"l":"「이 화분이 제일 목말라 해.」라고 말했다","r":"오래 눈여겨보아 왔다"},{"l":"늘 가장 먼저 교실에 왔다","r":"아직 어울릴 친구가 없었다"}],"mis":"K5-1-u1-X33","explanation":["감추는 행동에 마음이 있어요.","화분 사정을 잘 알아요.","혼자 있는 시간이 길었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#8','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C31',2,'mc','auto','「젖어 있는 화분」의 흐름을 차례대로 알맞게 간추린 것은 어느 것인가요?',ARRAY['K5-1-u1-X34']::text[],false,'{"seq":8,"concept":"K5-1-u1-C31","difficulty":2,"kind":"mc","stem":"「젖어 있는 화분」의 흐름을 차례대로 알맞게 간추린 것은 어느 것인가요?","options":[{"t":"흙이 젖어 이상하게 여김 → 일찍 가서 하율이를 봄 → 함께 물을 주자고 함","correct":true},{"t":"함께 물을 주자고 함 → 흙이 젖어 이상하게 여김 → 일찍 가서 하율이를 봄","mis":"K5-1-u1-X34"},{"t":"일찍 가서 하율이를 봄 → 함께 물을 주자고 함 → 흙이 젖어 이상하게 여김","mis":"K5-1-u1-X34"},{"t":"복도가 조용함 → 신발주머니가 걸려 있음 → 물병 뚜껑이 열려 있음","mis":"K5-1-u1-X34"}],"explanation":["차례가 뒤섞였어요.","처음 일이 맨 뒤로 갔어요.","중요한 일을 차례대로 골랐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#9','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C32',2,'mc','auto','「고개를 갸웃하고 있었다」에서 「갸웃하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X35']::text[],false,'{"seq":9,"concept":"K5-1-u1-C32","difficulty":2,"kind":"mc","stem":"「고개를 갸웃하고 있었다」에서 「갸웃하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"고개를 한쪽으로 살짝 기울이다","correct":true},{"t":"고개를 크게 끄덕이다","mis":"K5-1-u1-X35"},{"t":"고개를 푹 숙이다","mis":"K5-1-u1-X35"},{"t":"고개를 세차게 흔들다","mis":"K5-1-u1-X35"}],"explanation":["끄덕임과 달라요.","숙인 것과 달라요.","화분을 살피며 고개를 기울인 모습이에요."],"asset":{"type":"passage","lines":["다온이는 다음 날 평소보다 이십 분 일찍 학교에 갔다. 복도는 아직 조용했다.","교실 문을 여니 창가 쪽에서 누군가 고개를 갸웃하고 있었다.","지난달에 전학 온 하율이었다. 하율이의 신발주머니는 이미 사물함에 걸려 있었고,","책상 위에는 뚜껑이 열린 물병이 놓여 있었다.","다온이와 눈이 마주치자 하율이는 물병을 슬그머니 가방 뒤로 밀었다."],"title":"「젖어 있는 화분」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_basic#10','kor',5,1,'u1','L08','g5_1_kor_u1_L08_basic','lesson_basic','K5-1-u1-C28',3,'mc','auto','제목 「젖어 있는 화분」을 보고 떠올린 물음을 담고 읽으면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X31','K5-1-u1-X26']::text[],false,'{"seq":10,"concept":"K5-1-u1-C28","difficulty":3,"kind":"mc","stem":"제목 「젖어 있는 화분」을 보고 떠올린 물음을 담고 읽으면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"이야기 속 단서를 찾아 생략된 내용을 채우며 읽을 수 있다","correct":true},{"t":"물음의 답이 이야기 첫 줄에 꼭 나온다","mis":"K5-1-u1-X31"},{"t":"제목만 읽으면 이야기를 다 알 수 있다","mis":"K5-1-u1-X31"},{"t":"물음이 맞았는지만 확인하면 된다","mis":"K5-1-u1-X26"}],"explanation":["답이 바로 나오지 않아요.","제목은 시작일 뿐이에요.","물음을 따라 단서를 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#1','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C32',2,'mc','auto','「하율이가 다온이를 돌아보며 반색했다」에서 「반색하다」의 뜻을 짐작하게 해 주는 단서로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X35','K5-1-u1-X32']::text[],false,'{"seq":1,"concept":"K5-1-u1-C32","difficulty":2,"kind":"mc","stem":"「하율이가 다온이를 돌아보며 반색했다」에서 「반색하다」의 뜻을 짐작하게 해 주는 단서로 알맞은 것은 어느 것인가요?","options":[{"t":"돌아보며 물병을 내밀고 화분 이야기를 해 준 것","correct":true},{"t":"다음 날 아침이라는 때","mis":"K5-1-u1-X35"},{"t":"하율이가 창가에 서 있었다는 것","mis":"K5-1-u1-X32"},{"t":"다온이가 일찍 나섰다는 것","mis":"K5-1-u1-X32"}],"explanation":["때는 뜻을 알려 주지 않아요.","서 있던 곳도 뜻과 관계없어요.","반가워하는 행동이 뒤에 이어져요."],"asset":{"type":"passage","lines":["다음 날 아침, 다온이는 다시 일찍 나섰다. 하율이가 창가에 서 있었다.","「나도 일찍 왔어. 같이 줄래?」","하율이가 다온이를 돌아보며 반색했다. 그리고 물병을 내밀었다.","「여기, 이 화분이 제일 목말라 해.」","다온이는 웃었다. 하율이가 화분 넷의 사정을 자신보다 훨씬 잘 알고 있다는 것을,","그제야 알았다."],"title":"「젖어 있는 화분」 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#2','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C30',2,'ox','auto','인물이 「그냥」이라고 대답하면 정말 아무 까닭이 없는 거예요.',ARRAY['K5-1-u1-X33']::text[],false,'{"seq":2,"concept":"K5-1-u1-C30","difficulty":2,"kind":"ox","stem":"인물이 「그냥」이라고 대답하면 정말 아무 까닭이 없는 거예요.","answer":"X","reason_options":[{"t":"말하기 쑥스럽거나 어려운 까닭이 생략되었을 수 있어 행동과 다른 단서를 함께 보아야 하기 때문에","correct":true},{"t":"인물이 말한 그대로가 언제나 전부이기 때문에","mis":"K5-1-u1-X33"}],"mis":"K5-1-u1-X33","explanation":["「그냥」 뒤에 마음이 숨을 수 있어요.","행동이 함께 말해 줘요.","앞뒤 단서와 함께 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#3','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C29',3,'mc','auto','「하율이는 늘 교실에 가장 먼저 왔다. 그리고 아무와도 말하지 않은 채 제 책상에 앉아 있었다.」가 알려 주는 것으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X33','K5-1-u1-X32']::text[],false,'{"seq":3,"concept":"K5-1-u1-C29","difficulty":3,"kind":"mc","stem":"「하율이는 늘 교실에 가장 먼저 왔다. 그리고 아무와도 말하지 않은 채 제 책상에 앉아 있었다.」가 알려 주는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"하율이가 아직 어울릴 친구가 없어 혼자 화분을 돌보며 아침을 보냈다는 것","correct":true},{"t":"하율이가 다온이를 싫어한다는 것","mis":"K5-1-u1-X33"},{"t":"하율이가 화분 당번이라는 것","mis":"K5-1-u1-X32"},{"t":"하율이가 말하는 것을 싫어한다는 것","mis":"K5-1-u1-X33"}],"explanation":["싫어한다는 단서가 없어요.","당번은 다온이에요.","전학 온 지 얼마 안 된 하율이의 아침이 보여요."],"asset":{"type":"passage","lines":["다온 「혹시… 네가 화분에 물 줬어?」　하율 「…응.」","다온 「왜? 당번은 난데.」","하율 「그냥.」 (손끝으로 책상 모서리를 문지른다.)","하율이는 더 말하지 않았다. 다온이는 「그냥」이라는 말을 오래 곱씹었다.","하율이는 늘 교실에 가장 먼저 왔다.","그리고 아무와도 말하지 않은 채 제 책상에 앉아 있었다."],"title":"「젖어 있는 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#4','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C30',3,'mc','auto','하율이가 「여기, 이 화분이 제일 목말라 해.」라고 한 말에서 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u1-X33','K5-1-u1-X32']::text[],false,'{"seq":4,"concept":"K5-1-u1-C30","difficulty":3,"kind":"mc","stem":"하율이가 「여기, 이 화분이 제일 목말라 해.」라고 한 말에서 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"하율이가 오랫동안 화분을 눈여겨보아 왔다","correct":true},{"t":"화분이 정말 말을 한다","mis":"K5-1-u1-X33"},{"t":"하율이가 화분을 처음 보았다","mis":"K5-1-u1-X32"},{"t":"하율이가 다온이를 시험하려 한다","mis":"K5-1-u1-X33"}],"explanation":["빗대어 한 말이에요.","처음 본 사람은 알 수 없는 일이에요.","화분마다 사정을 알 만큼 오래 돌보았어요."],"asset":{"type":"passage","lines":["다음 날 아침, 다온이는 다시 일찍 나섰다. 하율이가 창가에 서 있었다.","「나도 일찍 왔어. 같이 줄래?」","하율이가 다온이를 돌아보며 반색했다. 그리고 물병을 내밀었다.","「여기, 이 화분이 제일 목말라 해.」","다온이는 웃었다. 하율이가 화분 넷의 사정을 자신보다 훨씬 잘 알고 있다는 것을,","그제야 알았다."],"title":"「젖어 있는 화분」 ④"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#5','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C31',3,'mc','auto','이야기를 간추릴 때 넣지 않아도 되는 내용은 어느 것인가요?',ARRAY['K5-1-u1-X34']::text[],false,'{"seq":5,"concept":"K5-1-u1-C31","difficulty":3,"kind":"mc","stem":"이야기를 간추릴 때 넣지 않아도 되는 내용은 어느 것인가요?","options":[{"t":"복도는 아직 조용했다","correct":true},{"t":"다온이는 흙이 젖어 있는 것을 이상하게 여겼다","mis":"K5-1-u1-X34"},{"t":"일찍 간 다온이는 하율이가 물을 주어 왔음을 알게 되었다","mis":"K5-1-u1-X34"},{"t":"함께 물을 주자고 하자 하율이가 반가워했다","mis":"K5-1-u1-X34"}],"explanation":["처음의 중요한 일이에요.","가운데의 중요한 일이에요.","분위기를 보여 주는 묘사는 빼도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#6','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C28',3,'error','auto','「젖어 있는 화분」을 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X31','K5-1-u1-X33','K5-1-u1-X32']::text[],false,'{"seq":6,"concept":"K5-1-u1-C28","difficulty":3,"kind":"error","stem":"「젖어 있는 화분」을 읽은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「이야기에 나오지 않은 건 알 수 없으니까 짐작하지 말아야 해.」","correct":true,"mis_target":"K5-1-u1-X31"},{"t":"「물병을 민 행동에서 들키고 싶지 않은 마음이 보여.」","mis":"K5-1-u1-X33"},{"t":"「젖은 흙과 물 자국이 첫 단서였어.」","mis":"K5-1-u1-X32"}],"explanation":["행동에서 마음을 짐작했어요.","단서를 알맞게 찾았어요.","나오지 않은 빈 곳을 단서로 채우며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#7','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C32',3,'mc','auto','문맥에서 낱말의 뜻을 짐작하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X35']::text[],false,'{"seq":7,"concept":"K5-1-u1-C32","difficulty":3,"kind":"mc","stem":"문맥에서 낱말의 뜻을 짐작하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"그 낱말 앞뒤 문장을 다시 읽어 단서를 찾는다","correct":true},{"t":"낱말의 글자 수를 센다","mis":"K5-1-u1-X35"},{"t":"비슷하게 생긴 낱말의 뜻을 그대로 쓴다","mis":"K5-1-u1-X35"},{"t":"모르는 낱말은 빼고 읽는다","mis":"K5-1-u1-X35"}],"explanation":["글자 수와 뜻은 관계없어요.","생김새가 비슷해도 뜻은 달라요.","앞뒤 문장에 단서가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#8','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C29',4,'mc','auto','다온이가 「하율이가 물을 주어 왔다」고 알게 되기까지 모은 단서를 알맞게 묶은 것은 어느 것인가요?',ARRAY['K5-1-u1-X32','K5-1-u1-X29']::text[],false,'{"seq":8,"concept":"K5-1-u1-C29","difficulty":4,"kind":"mc","stem":"다온이가 「하율이가 물을 주어 왔다」고 알게 되기까지 모은 단서를 알맞게 묶은 것은 어느 것인가요?","options":[{"t":"젖은 흙과 물 자국 → 일찍 와서 창가에 있던 하율이 → 열린 물병과 그것을 민 행동","correct":true},{"t":"신발주머니 → 전학 온 때 → 조용한 복도","mis":"K5-1-u1-X32"},{"t":"열린 물병 하나만 보고 알았다","mis":"K5-1-u1-X32"},{"t":"다온이의 짐작만으로 확인할 필요가 없었다","mis":"K5-1-u1-X29"}],"explanation":["물 주기와 관계없는 사실이에요.","단서 하나로는 부족해요.","흩어진 단서를 하나로 모았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#9','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C30',4,'essay','teacher','하율이가 「그냥」이라고만 대답한 까닭을 짐작하고, 그렇게 짐작한 단서를 이야기에서 두 가지 찾아 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u1-C30","difficulty":4,"kind":"essay","stem":"하율이가 「그냥」이라고만 대답한 까닭을 짐작하고, 그렇게 짐작한 단서를 이야기에서 두 가지 찾아 쓰세요.","answer_guide":{"answer":"예: 하율이는 아직 친구가 없어 일찍 온 교실에서 혼자 있기 어색했고, 그래서 화분을 돌보았다는 것을 말하기 쑥스러웠던 것 같다. 단서는 하율이가 늘 교실에 가장 먼저 와서 아무와도 말하지 않았다는 것과, 다온이와 눈이 마주치자 물병을 가방 뒤로 민 행동이다.","scoring_points":["「그냥」에 생략된 까닭을 짐작했는가","이야기에서 단서를 두 가지 찾았는가","단서와 짐작이 이어지는가"]},"explanation":["「그냥」 뒤의 마음을 봐요.","행동과 상황에서 단서를 찾아요.","단서와 짐작을 이어요."],"asset":{"type":"passage","lines":["다온 「혹시… 네가 화분에 물 줬어?」　하율 「…응.」","다온 「왜? 당번은 난데.」","하율 「그냥.」 (손끝으로 책상 모서리를 문지른다.)","하율이는 더 말하지 않았다. 다온이는 「그냥」이라는 말을 오래 곱씹었다.","하율이는 늘 교실에 가장 먼저 왔다.","그리고 아무와도 말하지 않은 채 제 책상에 앉아 있었다."],"title":"「젖어 있는 화분」 ③"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L08_challenge#10','kor',5,1,'u1','L08','g5_1_kor_u1_L08_challenge','lesson_challenge','K5-1-u1-C31',4,'essay','teacher','「젖어 있는 화분」을 처음 · 가운데 · 끝으로 간추리고, 가장 인상 깊은 장면과 그 장면에서 짐작한 내용을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u1-C31","difficulty":4,"kind":"essay","stem":"「젖어 있는 화분」을 처음 · 가운데 · 끝으로 간추리고, 가장 인상 깊은 장면과 그 장면에서 짐작한 내용을 쓰세요.","answer_guide":{"answer":"예: 처음 — 화분 당번 다온이는 자기가 물을 주지 않은 날에도 흙이 젖어 있는 것을 이상하게 여겼다. 가운데 — 일찍 학교에 간 다온이는 하율이가 화분에 물을 주어 왔음을 알게 되었다. 끝 — 다온이가 함께 물을 주자고 하자 하율이는 반가워하며 화분에 대해 알려 주었다. 인상 깊은 장면은 하율이가 물병을 가방 뒤로 민 장면이다. 혼자 한 일을 들키면 부끄러울까 봐 감추고 싶었던 것 같다.","scoring_points":["처음 · 가운데 · 끝으로 간추렸는가","인상 깊은 장면을 골랐는가","그 장면에서 짐작한 내용을 썼는가"]},"explanation":["중요한 일만 차례대로 골라요.","마음에 남은 장면을 골라요.","그 장면의 빈 곳을 채워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#1','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C33',1,'mc','auto','친구의 고민을 들을 때 알맞지 않은 태도는 어느 것인가요?',ARRAY['K5-1-u1-X36']::text[],false,'{"seq":1,"concept":"K5-1-u1-C33","difficulty":1,"kind":"mc","stem":"친구의 고민을 들을 때 알맞지 않은 태도는 어느 것인가요?","options":[{"t":"들은 고민을 다른 친구에게 옮긴다","correct":true},{"t":"끝까지 듣는다","mis":"K5-1-u1-X36"},{"t":"마음을 먼저 알아준다","mis":"K5-1-u1-X36"},{"t":"자세히 물어 확인한다","mis":"K5-1-u1-X36"}],"explanation":["끝까지 들어요.","마음을 먼저 알아줘요.","고민은 다른 친구에게 옮기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#2','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C33',1,'ox','auto','친구의 고민이 작아 보이면 가벼운 일이라고 말해 주는 게 좋아요.',ARRAY['K5-1-u1-X36']::text[],false,'{"seq":2,"concept":"K5-1-u1-C33","difficulty":1,"kind":"ox","stem":"친구의 고민이 작아 보이면 가벼운 일이라고 말해 주는 게 좋아요.","answer":"X","reason_options":[{"t":"고민한 사람에게는 무거운 일일 수 있어 마음을 먼저 알아주어야 하기 때문에","correct":true},{"t":"가볍다고 하면 고민이 바로 사라지기 때문에","mis":"K5-1-u1-X36"}],"mis":"K5-1-u1-X36","explanation":["내 눈에 작아도 친구에겐 클 수 있어요.","가볍게 넘기면 마음이 다쳐요.","마음을 먼저 알아줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#3','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C35',1,'mc','auto','고민에 대한 해결 방법을 건넬 때 맨 먼저 할 말은 어느 것인가요?',ARRAY['K5-1-u1-X38']::text[],false,'{"seq":3,"concept":"K5-1-u1-C35","difficulty":1,"kind":"mc","stem":"고민에 대한 해결 방법을 건넬 때 맨 먼저 할 말은 어느 것인가요?","options":[{"t":"마음을 알아주는 말","correct":true},{"t":"잘못을 짚어 주는 말","mis":"K5-1-u1-X38"},{"t":"반드시 따라야 할 규칙","mis":"K5-1-u1-X38"},{"t":"내 고민 이야기","mis":"K5-1-u1-X38"}],"explanation":["탓하는 말은 나중에도 하지 않아요.","규칙을 시키는 말투는 피해요.","마음을 먼저 알아줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#4','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C36',1,'match','auto','고민과 그 고민에 알맞은 조언을 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u1-C36","difficulty":1,"kind":"match","stem":"고민과 그 고민에 알맞은 조언을 이으세요.","pairs":[{"l":"아침마다 서두르게 된다","r":"전날 밤에 가방을 싸 두면 어떨까?"},{"l":"발표할 때 목소리가 떨린다","r":"짝 앞에서 먼저 연습해 보면 어떨까?"},{"l":"의견이 잘 받아들여지지 않는다","r":"까닭을 함께 말해 보면 어떨까?"}],"mis":"K5-1-u1-X39","explanation":["아침 준비를 덜어 줘요.","작은 무대에서 먼저 연습해요.","의견에 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#5','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C35',2,'mc','auto','두 대답 가운데 도움이 되는 대답과 그 까닭을 바르게 고른 것은 어느 것인가요?',ARRAY['K5-1-u1-X38']::text[],false,'{"seq":5,"concept":"K5-1-u1-C35","difficulty":2,"kind":"mc","stem":"두 대답 가운데 도움이 되는 대답과 그 까닭을 바르게 고른 것은 어느 것인가요?","options":[{"t":"㉯ — 마음을 알아주고 해 볼 방법을 건네서","correct":true},{"t":"㉮ — 잘못을 분명히 알려 주어서","mis":"K5-1-u1-X38"},{"t":"㉮ — 대답이 짧고 빨라서","mis":"K5-1-u1-X38"},{"t":"㉯ — 내 이야기를 길게 해서","mis":"K5-1-u1-X38"}],"explanation":["탓하는 말은 도움이 안 돼요.","빠르기는 까닭이 아니에요.","마음 → 해 본 방법 → 권하기였어요."],"asset":{"type":"passage","lines":["고민 ①에 대한 대답","㉮ 「그건 네가 게을러서 그래. 일찍 자면 되잖아.」","㉯ 「아침마다 마음이 급하겠다. 나는 가방을 전날 밤에 싸 두니까 조금 나았어. 한번 해 볼래?」"],"title":"같은 고민, 다른 대답"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#6','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C34',2,'mc','auto','고민 ③에서 짐작할 수 있는 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X37']::text[],false,'{"seq":6,"concept":"K5-1-u1-C34","difficulty":2,"kind":"mc","stem":"고민 ③에서 짐작할 수 있는 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"말해도 소용없다고 느껴 속상하다","correct":true},{"t":"모둠 활동이 재미있어졌다","mis":"K5-1-u1-X37"},{"t":"의견이 원래 없다","mis":"K5-1-u1-X37"},{"t":"모둠 친구들이 모두 밉다","mis":"K5-1-u1-X37"}],"explanation":["재미있다는 단서는 없어요.","의견을 말했었다고 했어요.","「그래서 가만히 있습니다」가 단서예요."],"asset":{"type":"passage","lines":["고민 ① 아침마다 늦잠을 자서 늘 서두르게 됩니다. 밥도 못 먹고 뛰어나올 때가 많습니다.","　　　 일찍 자려고 해도 잘 안 됩니다.","고민 ② 발표할 때 목소리가 떨립니다. 준비를 많이 해도 앞에 서면 머릿속이 하얘집니다.","고민 ③ 모둠 활동에서 제 의견을 말하면 잘 받아들여지지 않습니다.","　　　 그래서 요즘은 그냥 가만히 있습니다."],"title":"고민 상담소에 들어온 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#7','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C35',2,'mc','auto','「이렇게 해.」보다 「이렇게 해 보면 어떨까?」가 더 좋은 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X38']::text[],false,'{"seq":7,"concept":"K5-1-u1-C35","difficulty":2,"kind":"mc","stem":"「이렇게 해.」보다 「이렇게 해 보면 어떨까?」가 더 좋은 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"상대에게 고를 여지를 남겨 주기 때문이다","correct":true},{"t":"말이 더 길어서 정성스러워 보이기 때문이다","mis":"K5-1-u1-X11"},{"t":"상대가 꼭 따르게 만들기 때문이다","mis":"K5-1-u1-X38"},{"t":"묻는 말이라 대답하지 않아도 되기 때문이다","mis":"K5-1-u1-X38"}],"explanation":["길이 때문이 아니에요.","따르게 하는 말이 아니에요.","고를 여지를 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#8','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C34',2,'mc','auto','고민 ①을 쓴 친구에게 글에 적히지 않은 마음을 짐작해 건넬 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X38','K5-1-u1-X37']::text[],false,'{"seq":8,"concept":"K5-1-u1-C34","difficulty":2,"kind":"mc","stem":"고민 ①을 쓴 친구에게 글에 적히지 않은 마음을 짐작해 건넬 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「아침마다 마음이 급하고 지치겠다.」","correct":true},{"t":"「늦잠은 게을러서 그래.」","mis":"K5-1-u1-X38"},{"t":"「밥은 안 먹어도 괜찮아.」","mis":"K5-1-u1-X37"},{"t":"「일찍 자면 다 해결돼.」","mis":"K5-1-u1-X38"}],"explanation":["탓하는 말이에요.","적힌 말만 보고 넘겼어요.","서두르는 아침의 마음을 짐작했어요."],"asset":{"type":"passage","lines":["고민 ① 아침마다 늦잠을 자서 늘 서두르게 됩니다. 밥도 못 먹고 뛰어나올 때가 많습니다.","　　　 일찍 자려고 해도 잘 안 됩니다.","고민 ② 발표할 때 목소리가 떨립니다. 준비를 많이 해도 앞에 서면 머릿속이 하얘집니다.","고민 ③ 모둠 활동에서 제 의견을 말하면 잘 받아들여지지 않습니다.","　　　 그래서 요즘은 그냥 가만히 있습니다."],"title":"고민 상담소에 들어온 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#9','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C37',2,'mc','auto','배운 것을 실천하는 활동에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X40']::text[],false,'{"seq":9,"concept":"K5-1-u1-C37","difficulty":2,"kind":"mc","stem":"배운 것을 실천하는 활동에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"고민 상담소 말고도 대화 빙고 놀이처럼 반에서 함께 정해 할 수 있다","correct":true},{"t":"실천 활동은 고민 상담소 하나뿐이다","mis":"K5-1-u1-X40"},{"t":"선생님께서 정해 주신 활동만 할 수 있다","mis":"K5-1-u1-X40"},{"t":"배운 것은 국어 시간에만 쓴다","mis":"K5-1-u1-X40"}],"explanation":["여러 활동이 있어요.","반에서 함께 정해요.","배운 것을 쓸 곳은 많아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_basic#10','kor',5,1,'u1','L11','g5_1_kor_u1_L11_basic','lesson_basic','K5-1-u1-C34',3,'mc','auto','고민 ②에 적히지 않은 마음을 짐작하고 확인하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X38','K5-1-u1-X37']::text[],false,'{"seq":10,"concept":"K5-1-u1-C34","difficulty":3,"kind":"mc","stem":"고민 ②에 적히지 않은 마음을 짐작하고 확인하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「준비를 많이 했는데 앞에 서면 속상하겠다. 혹시 친구들이 쳐다보는 게 걱정돼?」","correct":true},{"t":"「떨리면 발표를 안 하면 돼.」","mis":"K5-1-u1-X38"},{"t":"「너는 준비를 덜 해서 그래.」","mis":"K5-1-u1-X38"},{"t":"「발표는 원래 재미없어.」","mis":"K5-1-u1-X37"}],"explanation":["방법이 고민과 맞지 않아요.","탓하는 말이에요.","마음을 짐작하고 물어 확인했어요."],"asset":{"type":"passage","lines":["고민 ① 아침마다 늦잠을 자서 늘 서두르게 됩니다. 밥도 못 먹고 뛰어나올 때가 많습니다.","　　　 일찍 자려고 해도 잘 안 됩니다.","고민 ② 발표할 때 목소리가 떨립니다. 준비를 많이 해도 앞에 서면 머릿속이 하얘집니다.","고민 ③ 모둠 활동에서 제 의견을 말하면 잘 받아들여지지 않습니다.","　　　 그래서 요즘은 그냥 가만히 있습니다."],"title":"고민 상담소에 들어온 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#1','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C36',2,'mc','auto','「발표할 때 목소리가 떨린다」는 고민에 알맞은 조언은 어느 것인가요?',ARRAY['K5-1-u1-X39','K5-1-u1-X38']::text[],false,'{"seq":1,"concept":"K5-1-u1-C36","difficulty":2,"kind":"mc","stem":"「발표할 때 목소리가 떨린다」는 고민에 알맞은 조언은 어느 것인가요?","options":[{"t":"「짝 앞에서 먼저 연습해 보면 어떨까?」","correct":true},{"t":"「전날 밤에 가방을 싸 두면 어떨까?」","mis":"K5-1-u1-X39"},{"t":"「의견에 까닭을 함께 말해 보면 어떨까?」","mis":"K5-1-u1-X39"},{"t":"「발표는 그냥 빼 달라고 해.」","mis":"K5-1-u1-X38"}],"explanation":["아침 고민에 맞는 조언이에요.","모둠 고민에 맞는 조언이에요.","떨림을 줄일 연습을 권했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#2','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C34',2,'ox','auto','고민 글은 적힌 내용만 읽으면 돼요.',ARRAY['K5-1-u1-X37']::text[],false,'{"seq":2,"concept":"K5-1-u1-C34","difficulty":2,"kind":"ox","stem":"고민 글은 적힌 내용만 읽으면 돼요.","answer":"X","reason_options":[{"t":"글에 다 적히지 않은 마음이 있어 단서로 짐작하고 맞는지 물어보아야 하기 때문에","correct":true},{"t":"고민을 쓴 사람이 모든 마음을 다 적었기 때문에","mis":"K5-1-u1-X37"}],"mis":"K5-1-u1-X37","explanation":["다 적지 못한 마음이 있어요.","「그래서 …」 같은 말이 단서예요.","짐작하고 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#3','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C35',3,'mc','auto','조언을 건네는 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X38']::text[],false,'{"seq":3,"concept":"K5-1-u1-C35","difficulty":3,"kind":"mc","stem":"조언을 건네는 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"마음을 알아주는 말 → 내가 해 본 방법 → 고르도록 권하는 말투","correct":true},{"t":"내가 해 본 방법 → 잘못 짚기 → 시키는 말투","mis":"K5-1-u1-X38"},{"t":"권하는 말투 → 마음 알아주기 → 내 고민 이야기","mis":"K5-1-u1-X38"},{"t":"잘못 짚기 → 마음 알아주기 → 지켜야 할 규칙","mis":"K5-1-u1-X38"}],"explanation":["잘못 짚기는 넣지 않아요.","차례가 뒤섞였어요.","마음 → 방법 → 권하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#4','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C33',3,'mc','auto','고민 상담소에서 배려하며 듣기와 짐작하기를 함께 쓴 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X29','K5-1-u1-X36']::text[],false,'{"seq":4,"concept":"K5-1-u1-C33","difficulty":3,"kind":"mc","stem":"고민 상담소에서 배려하며 듣기와 짐작하기를 함께 쓴 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"끝까지 듣고 마음을 알아준 뒤, 글에 적히지 않은 마음을 짐작해 맞는지 물어본다","correct":true},{"t":"고민을 다 듣기 전에 해결 방법부터 말한다","mis":"K5-1-u1-X06"},{"t":"짐작한 마음을 사실처럼 정해 말한다","mis":"K5-1-u1-X29"},{"t":"고민을 재미있게 다른 친구에게 들려준다","mis":"K5-1-u1-X36"}],"explanation":["끝까지 듣지 않았어요.","짐작은 물어 확인해요.","고민은 옮기지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#5','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C35',3,'error','auto','대답 ㉮를 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X38','K5-1-u1-X39']::text[],false,'{"seq":5,"concept":"K5-1-u1-C35","difficulty":3,"kind":"error","stem":"대답 ㉮를 두고 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「잘못을 분명히 알려 줬으니 가장 도움이 되는 대답이야.」","correct":true,"mis_target":"K5-1-u1-X38"},{"t":"「게으르다고 탓해서 마음이 더 상할 것 같아.」","mis":"K5-1-u1-X38"},{"t":"「해 볼 수 있는 방법이 빠져 있어.」","mis":"K5-1-u1-X39"}],"explanation":["탓하면 마음이 상해요.","방법이 빠졌어요.","잘못을 알려 주는 것은 조언의 요령이 아니에요."],"asset":{"type":"passage","lines":["고민 ①에 대한 대답","㉮ 「그건 네가 게을러서 그래. 일찍 자면 되잖아.」","㉯ 「아침마다 마음이 급하겠다. 나는 가방을 전날 밤에 싸 두니까 조금 나았어. 한번 해 볼래?」"],"title":"같은 고민, 다른 대답"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#6','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C37',3,'mc','auto','「이야기에서 짐작하기」 활동을 바르게 한 모습은 어느 것인가요?',ARRAY['K5-1-u1-X26','K5-1-u1-X27','K5-1-u1-X29']::text[],false,'{"seq":6,"concept":"K5-1-u1-C37","difficulty":3,"kind":"mc","stem":"「이야기에서 짐작하기」 활동을 바르게 한 모습은 어느 것인가요?","options":[{"t":"모둠이 책을 골라 대화 장면에서 생략된 내용을 짐작하고 서로 견주어 본다","correct":true},{"t":"책을 읽고 누가 가장 빨리 짐작했는지 겨룬다","mis":"K5-1-u1-X26"},{"t":"책 제목만 보고 내용을 정해 버린다","mis":"K5-1-u1-X27"},{"t":"혼자 짐작한 것을 정답이라고 알린다","mis":"K5-1-u1-X29"}],"explanation":["겨루기가 아니에요.","드러난 것을 먼저 읽어요.","짐작은 견주어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#7','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C36',3,'mc','auto','「모둠 활동에서 의견이 잘 받아들여지지 않는다」는 고민에 맞는 조언은 어느 것인가요?',ARRAY['K5-1-u1-X39','K5-1-u1-X37','K5-1-u1-X38']::text[],false,'{"seq":7,"concept":"K5-1-u1-C36","difficulty":3,"kind":"mc","stem":"「모둠 활동에서 의견이 잘 받아들여지지 않는다」는 고민에 맞는 조언은 어느 것인가요?","options":[{"t":"「의견을 말할 때 까닭을 함께 말해 보면 어떨까?」","correct":true},{"t":"「짝 앞에서 먼저 연습해 보면 어떨까?」","mis":"K5-1-u1-X39"},{"t":"「그냥 가만히 있는 게 편해.」","mis":"K5-1-u1-X37"},{"t":"「친구들이 틀렸다고 크게 말해.」","mis":"K5-1-u1-X38"}],"explanation":["발표 떨림에 맞는 조언이에요.","속상한 마음을 그대로 두게 해요.","의견이 받아들여지도록 까닭을 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#8','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C35',4,'mc','auto','고민 ①에 대한 대답 가운데 세 가지 요령을 모두 갖춘 것은 어느 것인가요?',ARRAY['K5-1-u1-X38','K5-1-u1-X39']::text[],false,'{"seq":8,"concept":"K5-1-u1-C35","difficulty":4,"kind":"mc","stem":"고민 ①에 대한 대답 가운데 세 가지 요령을 모두 갖춘 것은 어느 것인가요?","options":[{"t":"「아침마다 마음이 급하겠다. 나는 전날 밤에 가방을 싸 두니 조금 나았어. 너도 한번 해 보면 어떨까?」","correct":true},{"t":"「아침마다 급하겠다.」","mis":"K5-1-u1-X38"},{"t":"「전날 밤에 가방을 싸. 꼭 그렇게 해.」","mis":"K5-1-u1-X38"},{"t":"「나도 늦잠 자. 그냥 포기해.」","mis":"K5-1-u1-X39"}],"explanation":["마음만 알아주고 멈췄어요.","시키는 말투예요.","마음 → 해 본 방법 → 권하기를 모두 갖췄어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#9','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C34',4,'essay','teacher','다음 고민 쪽지에 적히지 않은 마음을 짐작해 쓰고, 그렇게 짐작한 단서와 건넬 조언을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u1-C34","difficulty":4,"kind":"essay","stem":"다음 고민 쪽지에 적히지 않은 마음을 짐작해 쓰고, 그렇게 짐작한 단서와 건넬 조언을 쓰세요.","answer_guide":{"answer":"예: 친구들과 어울리고 싶은데 먼저 말을 걸기 어려워 쓸쓸한 마음인 것 같다. 「사실 책이 그렇게 재미있지는 않아요」라는 말이 단서이다. 조언 — 「쉬는 시간마다 혼자라 쓸쓸했겠다. 나는 옆 친구에게 「같이 할래?」 한마디를 먼저 해 봤더니 조금 쉬워졌어. 너도 해 보면 어떨까?」","scoring_points":["적히지 않은 마음을 짐작했는가","고민 글에서 단서를 찾았는가","마음 → 방법 → 권하기로 조언했는가"]},"explanation":["「사실 …」이 단서예요.","마음을 먼저 알아줘요.","고를 여지를 남겨요."],"asset":{"type":"passage","lines":["고민 ⑤ 쉬는 시간에 다들 짝을 지어 노는데 저는 늘 책만 봅니다.","　　　 사실 책이 그렇게 재미있지는 않아요."],"title":"또 다른 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_L11_challenge#10','kor',5,1,'u1','L11','g5_1_kor_u1_L11_challenge','lesson_challenge','K5-1-u1-C35',4,'essay','teacher','친구에게 조언할 때 「이렇게 해 보면 어떨까?」처럼 권하는 말투가 왜 배려가 되는지, 배려하며 대화하는 방법과 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u1-C35","difficulty":4,"kind":"essay","stem":"친구에게 조언할 때 「이렇게 해 보면 어떨까?」처럼 권하는 말투가 왜 배려가 되는지, 배려하며 대화하는 방법과 이어 쓰세요.","answer_guide":{"answer":"예: 권하는 말투는 친구가 스스로 고를 여지를 남겨 준다. 「이렇게 해」라고 시키면 친구는 자기 마음을 몰라준다고 느낄 수 있지만, 권하는 말은 친구의 기분을 고려하며 말하는 것이어서 친구가 편하게 받아들이거나 다른 방법을 고를 수 있다.","scoring_points":["고를 여지를 남긴다는 점을 썼는가","시키는 말투와 견주었는가","배려하며 대화하는 방법과 이어 썼는가"]},"explanation":["시키는 말과 견줘요.","상대의 기분을 떠올려요.","고를 여지가 배려예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#1','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C1',1,'mc','auto','배려하며 대화할 때 가장 먼저 생각할 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X02','K5-1-u1-X01']::text[],false,'{"seq":1,"concept":"K5-1-u1-C1","difficulty":1,"kind":"mc","stem":"배려하며 대화할 때 가장 먼저 생각할 것은 어느 것인가요?","options":[{"t":"상대의 처지와 마음","correct":true},{"t":"내가 할 말의 길이","mis":"K5-1-u1-X11"},{"t":"대화에서 이기는 방법","mis":"K5-1-u1-X02"},{"t":"듣기 좋게 꾸미는 낱말","mis":"K5-1-u1-X01"}],"explanation":["길이가 아니에요.","이기려는 대화가 아니에요.","처지에서 생각하고 말과 태도를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#2','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C3',1,'mc','auto','「생략된 내용」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X03','K5-1-u1-X30']::text[],false,'{"seq":2,"concept":"K5-1-u1-C3","difficulty":1,"kind":"mc","stem":"「생략된 내용」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"말에 다 드러나지 않은 부분","correct":true},{"t":"잘못 말한 부분","mis":"K5-1-u1-X03"},{"t":"너무 길게 말한 부분","mis":"K5-1-u1-X03"},{"t":"거짓으로 말한 부분","mis":"K5-1-u1-X30"}],"explanation":["잘못 말한 것과 달라요.","길이와는 관계없어요.","드러나지 않은 빈 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#3','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C6',1,'mc','auto','상대의 말을 집중해서 듣는 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X10']::text[],false,'{"seq":3,"concept":"K5-1-u1-C6","difficulty":1,"kind":"mc","stem":"상대의 말을 집중해서 듣는 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"상대를 바라보며 고개를 끄덕인다","correct":true},{"t":"상대가 말할 때 다른 이야기를 꺼낸다","mis":"K5-1-u1-X06"},{"t":"휴대 전화를 보며 「응, 응.」 한다","mis":"K5-1-u1-X10"},{"t":"말이 끝나기 전에 결론을 내려 준다","mis":"K5-1-u1-X06"}],"explanation":["말을 끊었어요.","딴 곳을 보면 마음이 전해지지 않아요.","바라보고 끄덕이며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#4','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C10',1,'ox','auto','눈을 맞추고 고개를 끄덕이면 말수가 적어도 상대는 말이 받아들여졌다고 느껴요.',ARRAY['K5-1-u1-X11']::text[],false,'{"seq":4,"concept":"K5-1-u1-C10","difficulty":1,"kind":"ox","stem":"눈을 맞추고 고개를 끄덕이면 말수가 적어도 상대는 말이 받아들여졌다고 느껴요.","answer":"O","reason_options":[{"t":"배려는 말의 양이 아니라 태도에서 드러나기 때문에","correct":true},{"t":"말수가 적을수록 배려가 크기 때문에","mis":"K5-1-u1-X11"}],"mis":"K5-1-u1-X11","explanation":["맞는 말이에요.","말수와 배려의 크기는 관계없어요.","태도에서 배려가 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#5','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C17',1,'mc','auto','말할 내용을 정리하는 네 항목에 들지 않는 것은 어느 것인가요?',ARRAY['K5-1-u1-X19','K5-1-u1-X20']::text[],false,'{"seq":5,"concept":"K5-1-u1-C17","difficulty":1,"kind":"mc","stem":"말할 내용을 정리하는 네 항목에 들지 않는 것은 어느 것인가요?","options":[{"t":"상대가 할 대답","correct":true},{"t":"언제","mis":"K5-1-u1-X19"},{"t":"어디에서","mis":"K5-1-u1-X19"},{"t":"생각이나 느낌","mis":"K5-1-u1-X20"}],"explanation":["때는 항목이에요.","곳도 항목이에요.","상대의 대답은 내가 준비할 항목이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#6','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C22',1,'match','auto','짐작의 단서와 그 예를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-1-u1-C22","difficulty":1,"kind":"match","stem":"짐작의 단서와 그 예를 알맞게 이으세요.","pairs":[{"l":"말","r":"「오늘 늦게 갔어.」라는 말"},{"l":"행동","r":"연달아 하품하는 모습"},{"l":"경험이나 배경지식","r":"「나도 지난번에 그랬지.」"},{"l":"상황","r":"곧 체육 시간이라는 것"}],"mis":"K5-1-u1-X25","explanation":["들은 것과 본 것을 나누어요.","경험은 내가 떠올린 것이에요.","상황은 그때의 형편이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#7','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C35',1,'mc','auto','조언을 고르도록 권하는 말투로 맺은 것은 어느 것인가요?',ARRAY['K5-1-u1-X38']::text[],false,'{"seq":7,"concept":"K5-1-u1-C35","difficulty":1,"kind":"mc","stem":"조언을 고르도록 권하는 말투로 맺은 것은 어느 것인가요?","options":[{"t":"「한번 해 보면 어떨까?」","correct":true},{"t":"「꼭 그렇게 해.」","mis":"K5-1-u1-X38"},{"t":"「그것도 못 해?」","mis":"K5-1-u1-X38"},{"t":"「내 말대로만 해.」","mis":"K5-1-u1-X38"}],"explanation":["시키는 말이에요.","탓하는 말이에요.","고를 여지를 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#8','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C39',1,'mc','auto','길게 소리 내는 낱말에 붙이는 표시는 어느 것인가요?',ARRAY['K5-1-u1-X41']::text[],false,'{"seq":8,"concept":"K5-1-u1-C39","difficulty":1,"kind":"mc","stem":"길게 소리 내는 낱말에 붙이는 표시는 어느 것인가요?","options":[{"t":"[ː]","correct":true},{"t":"[!]","mis":"K5-1-u1-X41"},{"t":"[?]","mis":"K5-1-u1-X41"},{"t":"[～]","mis":"K5-1-u1-X41"}],"explanation":["느낌표가 아니에요.","물음표가 아니에요.","긴소리에는 [ː]를 붙여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#9','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C6',2,'mc','auto','찬솔이의 말과 태도에서 문제점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X11','K5-1-u1-X09','K5-1-u1-X07']::text[],false,'{"seq":9,"concept":"K5-1-u1-C6","difficulty":2,"kind":"mc","stem":"찬솔이의 말과 태도에서 문제점으로 알맞은 것은 어느 것인가요?","options":[{"t":"새별이의 말을 끝까지 듣지 않고 다른 이야기로 넘어갔다","correct":true},{"t":"새별이에게 너무 길게 말했다","mis":"K5-1-u1-X11"},{"t":"새별이에게 존댓말을 썼다","mis":"K5-1-u1-X09"},{"t":"새별이의 말을 이어서 물었다","mis":"K5-1-u1-X07"}],"explanation":["말은 오히려 짧았어요.","존댓말 이야기는 없어요.","숙제 이야기로 넘어가 말을 끊었어요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#10','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C7',2,'mc','auto','다래가 「어디서 마지막으로 봤어?」라고 물은 것이 좋은 까닭은 어느 것인가요?',ARRAY['K5-1-u1-X08','K5-1-u1-X02','K5-1-u1-X06']::text[],false,'{"seq":10,"concept":"K5-1-u1-C7","difficulty":2,"kind":"mc","stem":"다래가 「어디서 마지막으로 봤어?」라고 물은 것이 좋은 까닭은 어느 것인가요?","options":[{"t":"새별이가 이야기를 이어 갈 수 있게 되물었기 때문이다","correct":true},{"t":"새별이의 잘못을 따지려고 물었기 때문이다","mis":"K5-1-u1-X08"},{"t":"대화를 빨리 끝내려고 물었기 때문이다","mis":"K5-1-u1-X02"},{"t":"자기 이야기를 하려고 물었기 때문이다","mis":"K5-1-u1-X06"}],"explanation":["따지는 물음이 아니에요.","오히려 대화가 이어졌어요.","되묻기로 말할 길을 열었어요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#11','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C22',2,'mc','auto','다래가 「혹시 발목 아파?」라고 짐작한 단서로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X24','K5-1-u1-X25','K5-1-u1-X28']::text[],false,'{"seq":11,"concept":"K5-1-u1-C22","difficulty":2,"kind":"mc","stem":"다래가 「혹시 발목 아파?」라고 짐작한 단서로 알맞은 것은 어느 것인가요?","options":[{"t":"찬솔이가 발목을 만지작거리는 행동","correct":true},{"t":"피구를 한다는 다래의 말","mis":"K5-1-u1-X24"},{"t":"체육 시간이라는 때","mis":"K5-1-u1-X25"},{"t":"찬솔이가 어제 계단에 간 일","mis":"K5-1-u1-X28"}],"explanation":["그건 다래가 한 말이에요.","때만으로는 알 수 없어요.","계단 이야기는 짐작 뒤에 들었어요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#12','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C26',2,'mc','auto','다래가 짐작한 뒤 한 일로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X29']::text[],false,'{"seq":12,"concept":"K5-1-u1-C26","difficulty":2,"kind":"mc","stem":"다래가 짐작한 뒤 한 일로 알맞은 것은 어느 것인가요?","options":[{"t":"「혹시 발목 아파? 어디 다쳤어?」라고 물어 확인했다","correct":true},{"t":"짐작한 것을 친구들에게 알렸다","mis":"K5-1-u1-X29"},{"t":"짐작한 것을 사실로 정하고 피구를 하지 말라고 했다","mis":"K5-1-u1-X29"},{"t":"더 묻지 않고 대화를 끝냈다","mis":"K5-1-u1-X29"}],"explanation":["알리기 전에 확인해요.","단정하지 않았어요.","물어서 확인했어요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#13','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C18',2,'mc','auto','다래의 준비에서 빈칸에 들어갈 항목은 어느 것인가요?',ARRAY['K5-1-u1-X19']::text[],false,'{"seq":13,"concept":"K5-1-u1-C18","difficulty":2,"kind":"mc","stem":"다래의 준비에서 빈칸에 들어갈 항목은 어느 것인가요?","options":[{"t":"생각이나 느낌","correct":true},{"t":"언제","mis":"K5-1-u1-X19"},{"t":"어디에서","mis":"K5-1-u1-X19"},{"t":"무슨 일을","mis":"K5-1-u1-X19"}],"explanation":["「지난 일요일 오후에」가 있어요.","「아파트 앞 공원에서」가 있어요.","그때 든 마음이 비어 있어요."],"asset":{"type":"passage","lines":["대화 주제 — 동생에게 처음으로 자전거 타는 법을 알려 준 일","언제 — 지난 일요일 오후에","어디에서 — 아파트 앞 공원에서","무슨 일을 — 동생 자전거 뒤를 잡고 따라 뛰다가 살며시 손을 놓았는데,","　　동생이 혼자서 공원 끝까지 달렸다.","생각이나 느낌 — ?"],"title":"다래가 준비한 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#14','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C28',2,'mc','auto','「우산꽂이의 쪽지」 앞부분에서 글쓴이가 일부러 밝히지 않은 것은 어느 것인가요?',ARRAY['K5-1-u1-X31']::text[],false,'{"seq":14,"concept":"K5-1-u1-C28","difficulty":2,"kind":"mc","stem":"「우산꽂이의 쪽지」 앞부분에서 글쓴이가 일부러 밝히지 않은 것은 어느 것인가요?","options":[{"t":"노란 우산을 꽂아 둔 사람이 누구인지","correct":true},{"t":"비가 언제 쏟아졌는지","mis":"K5-1-u1-X31"},{"t":"해람이가 우산을 챙기지 않은 까닭","mis":"K5-1-u1-X31"},{"t":"쪽지에 적힌 말","mis":"K5-1-u1-X31"}],"explanation":["하교 시간이라고 나와 있어요.","그냥 뛰어나왔다고 나와 있어요.","누가 두었는지는 빈 곳이에요."],"asset":{"type":"passage","lines":["하교 시간에 갑자기 비가 쏟아졌다. 해람이는 현관에서 발을 동동 굴렀다.","아침에 엄마가 우산을 챙기라고 했는데, 그냥 뛰어나온 것이다.","그때 우산꽂이에 꽂힌 노란 우산 하나가 눈에 들어왔다.","손잡이에는 쪽지가 감겨 있었다. 「해람이에게 — 내일 돌려줘도 돼.」","쪽지의 글씨는 동글동글했다. 해람이는 어디서 본 듯한 글씨라고 생각했다."],"title":"「우산꽂이의 쪽지」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#15','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C30',2,'mc','auto','담우가 「나는 집이 가까워서 괜찮아.」라고 한 말에 생략된 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X33']::text[],false,'{"seq":15,"concept":"K5-1-u1-C30","difficulty":2,"kind":"mc","stem":"담우가 「나는 집이 가까워서 괜찮아.」라고 한 말에 생략된 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"우산을 빌려준 뒤 자기는 비를 맞고 갔다는 것","correct":true},{"t":"담우는 비를 아주 좋아한다는 것","mis":"K5-1-u1-X33"},{"t":"담우는 우산이 없다는 것","mis":"K5-1-u1-X33"},{"t":"해람이가 미웠다는 것","mis":"K5-1-u1-X33"}],"explanation":["좋아한다는 단서가 없어요.","우산을 내주었어요.","재채기와 잠긴 목소리가 단서예요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#16','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C34',2,'mc','auto','고민 ④에서 짐작할 수 있는 마음으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X37']::text[],false,'{"seq":16,"concept":"K5-1-u1-C34","difficulty":2,"kind":"mc","stem":"고민 ④에서 짐작할 수 있는 마음으로 알맞은 것은 어느 것인가요?","options":[{"t":"짝에게 서운하지만 사이가 나빠질까 봐 걱정된다","correct":true},{"t":"짝과 물건을 나누어 써서 즐겁다","mis":"K5-1-u1-X37"},{"t":"짝이 아주 밉다","mis":"K5-1-u1-X37"},{"t":"물건에 관심이 없다","mis":"K5-1-u1-X37"}],"explanation":["즐겁다는 단서가 없어요.","사이를 걱정하고 있어요.","「불편합니다」가 단서예요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#17','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C14',3,'mc','auto','찬솔이의 말을 배려하는 말로 알맞게 바꾼 것은 어느 것인가요?',ARRAY['K5-1-u1-X15','K5-1-u1-X13','K5-1-u1-X08']::text[],false,'{"seq":17,"concept":"K5-1-u1-C14","difficulty":3,"kind":"mc","stem":"찬솔이의 말을 배려하는 말로 알맞게 바꾼 것은 어느 것인가요?","options":[{"t":"「할머니께서 주신 거라 속상하겠다. 숙제는 나중에 하고 같이 찾아보자.」","correct":true},{"t":"「잃어버린 건 어쩔 수 없잖아.」","mis":"K5-1-u1-X15"},{"t":"(태블릿을 보며) 「아, 속상하겠다.」","mis":"K5-1-u1-X13"},{"t":"「그러게 잘 챙겼어야지.」","mis":"K5-1-u1-X08"}],"explanation":["마음을 가볍게 넘겼어요.","딴 곳을 보는 말은 전해지지 않아요.","마음을 받아 주고 도울 방법을 보탰어요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#18','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C23',3,'mc','auto','찬솔이의 「아…… 그래.」를 듣고 다른 친구가 「피구가 싫은가 보다」라고 짐작했어요. 이 짐작에 대해 알맞게 말한 것은 어느 것인가요?',ARRAY['K5-1-u1-X26','K5-1-u1-X04','K5-1-u1-X29']::text[],false,'{"seq":18,"concept":"K5-1-u1-C23","difficulty":3,"kind":"mc","stem":"찬솔이의 「아…… 그래.」를 듣고 다른 친구가 「피구가 싫은가 보다」라고 짐작했어요. 이 짐작에 대해 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「무엇을 보고 그렇게 생각했는지 서로 말해 보고 찬솔이에게 물어 확인하자.」","correct":true},{"t":"「다래가 맞혔으니 네 짐작은 틀렸어.」","mis":"K5-1-u1-X26"},{"t":"「짐작은 아무렇게나 해도 돼.」","mis":"K5-1-u1-X04"},{"t":"「둘 다 짐작했으니 묻지 않아도 돼.」","mis":"K5-1-u1-X29"}],"explanation":["맞고 틀림만 따지지 않아요.","근거가 있어야 해요.","단서를 견주고 물어 확인해요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#19','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C31',3,'mc','auto','「우산꽂이의 쪽지」를 차례대로 알맞게 간추린 것은 어느 것인가요?',ARRAY['K5-1-u1-X34']::text[],false,'{"seq":19,"concept":"K5-1-u1-C31","difficulty":3,"kind":"mc","stem":"「우산꽂이의 쪽지」를 차례대로 알맞게 간추린 것은 어느 것인가요?","options":[{"t":"우산이 없어 다급한 해람이가 쪽지 달린 노란 우산을 발견함 → 다음 날 담우의 재채기와 글씨를 봄 → 우산을 돌려주며 담우가 빌려준 것을 알게 됨","correct":true},{"t":"담우가 웃음 → 비가 쏟아짐 → 알림장을 봄","mis":"K5-1-u1-X34"},{"t":"현관에서 발을 동동 구름 → 엄마가 우산을 챙기라고 함 → 쪽지가 감겨 있음","mis":"K5-1-u1-X34"},{"t":"담우가 재채기를 함 → 노란 우산을 발견함 → 비가 쏟아짐","mis":"K5-1-u1-X34"}],"explanation":["차례가 뒤섞였어요.","앞부분만 늘어놓았어요.","처음 · 가운데 · 끝을 차례대로 골랐어요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#20','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C35',3,'mc','auto','고민 ④에 대한 조언 가운데 세 가지 요령을 모두 갖춘 것은 어느 것인가요?',ARRAY['K5-1-u1-X38','K5-1-u1-X39']::text[],false,'{"seq":20,"concept":"K5-1-u1-C35","difficulty":3,"kind":"mc","stem":"고민 ④에 대한 조언 가운데 세 가지 요령을 모두 갖춘 것은 어느 것인가요?","options":[{"t":"「혼자 참느라 불편했겠다. 나는 「쓰기 전에 말해 줄래?」라고 웃으며 말해 봤더니 괜찮았어. 너도 해 보면 어떨까?」","correct":true},{"t":"「혼자 참느라 불편했겠다.」","mis":"K5-1-u1-X38"},{"t":"「쓰기 전에 말해 달라고 해. 꼭.」","mis":"K5-1-u1-X38"},{"t":"「나도 그런 적 있어. 그냥 참아.」","mis":"K5-1-u1-X39"}],"explanation":["마음만 알아주고 멈췄어요.","시키는 말투예요.","마음 → 해 본 방법 → 권하기예요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#21','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C38',3,'mc','auto','「배려와 짐작은 서로를 돕는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X05']::text[],false,'{"seq":21,"concept":"K5-1-u1-C38","difficulty":3,"kind":"mc","stem":"「배려와 짐작은 서로를 돕는다」는 말의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"배려하니 말과 행동을 눈여겨보게 되고, 눈여겨보니 생략된 마음을 짐작할 수 있다","correct":true},{"t":"배려를 잘하면 짐작은 하지 않아도 된다","mis":"K5-1-u1-X05"},{"t":"짐작을 잘하면 배려는 하지 않아도 된다","mis":"K5-1-u1-X05"},{"t":"배려와 짐작은 서로 다른 시간에 배운다","mis":"K5-1-u1-X05"}],"explanation":["둘 다 필요해요.","둘 다 필요해요.","서로를 이끌어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#22','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C40',3,'match','auto','문장에 알맞은 발음을 이으세요.','{}'::text[],false,'{"seq":22,"concept":"K5-1-u1-C40","difficulty":3,"kind":"match","stem":"문장에 알맞은 발음을 이으세요.","pairs":[{"l":"눈이 소복이 쌓였다","r":"눈[눈ː]"},{"l":"눈에 티가 들어갔다","r":"눈[눈]"},{"l":"벌이 꽃 위를 날아다닌다","r":"벌[벌ː]"}],"mis":"K5-1-u1-X42","explanation":["하늘에서 내리는 눈은 길어요.","몸의 눈은 짧아요.","곤충 벌은 길게 소리 내요."],"asset":{"type":"passage","lines":["눈[눈] 보는 몸의 부분　　눈[눈ː] 하늘에서 내리는 하얀 얼음 알갱이","벌[벌] 잘못한 사람에게 주는 괴로움　　벌[벌ː] 꿀을 모으는 곤충","일[일] 하나　　일[일ː] 무엇을 이루려고 몸이나 마음을 쓰는 것"],"title":"장단이 다른 낱말 더 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#23','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C30',4,'mc','auto','「우산꽂이의 쪽지」에서 담우가 우산을 빌려주고도 직접 말하지 않은 까닭을 가장 알맞게 짐작한 것은 어느 것인가요?',ARRAY['K5-1-u1-X33','K5-1-u1-X28']::text[],false,'{"seq":23,"concept":"K5-1-u1-C30","difficulty":4,"kind":"mc","stem":"「우산꽂이의 쪽지」에서 담우가 우산을 빌려주고도 직접 말하지 않은 까닭을 가장 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"고마워하라고 한 일이 아니라서 드러내기 쑥스러웠을 것이다","correct":true},{"t":"해람이를 골탕 먹이려 했을 것이다","mis":"K5-1-u1-X33"},{"t":"우산을 돌려받고 싶지 않았을 것이다","mis":"K5-1-u1-X33"},{"t":"쪽지를 잘못 썼을 것이다","mis":"K5-1-u1-X28"}],"explanation":["그런 단서는 없어요.","「내일 돌려줘도 돼」라고 했어요.","머쓱한 웃음과 「들켰네」가 단서예요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#24','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C30',4,'essay','teacher','「우산꽂이의 쪽지」에서 생략된 내용 두 가지를 짐작해 쓰고, 각각 어떤 단서를 보고 짐작했는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u1-C30","difficulty":4,"kind":"essay","stem":"「우산꽂이의 쪽지」에서 생략된 내용 두 가지를 짐작해 쓰고, 각각 어떤 단서를 보고 짐작했는지 쓰세요.","answer_guide":{"answer":"예: 첫째, 노란 우산을 꽂아 둔 사람은 담우이다. 쪽지의 동글동글한 글씨가 담우 알림장의 글씨와 같았기 때문이다. 둘째, 담우는 우산을 빌려준 뒤 자기는 비를 맞고 집에 갔다. 다음 날 연달아 재채기를 하고 목소리가 잠겨 있었고, 「나는 집이 가까워서 괜찮아.」라고 말했기 때문이다.","scoring_points":["생략된 내용을 두 가지 짐작했는가","각 짐작의 단서를 이야기에서 찾았는가","단서와 짐작이 이어지는가"]},"explanation":["빈 곳을 찾아요.","흩어진 단서를 모아요.","단서와 짐작을 이어 써요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_a#25','kor',5,1,'u1','','g5_1_kor_u1_review_a','unit_review','K5-1-u1-C38',4,'essay','teacher','이 단원에서 배운 「배려하며 대화하기」와 「짐작하며 대화하기」의 방법을 각각 쓰고, 두 가지가 서로 어떻게 돕는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u1-C38","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「배려하며 대화하기」와 「짐작하며 대화하기」의 방법을 각각 쓰고, 두 가지가 서로 어떻게 돕는지 쓰세요.","answer_guide":{"answer":"예: 배려하며 대화하기 — 상대의 말을 집중해서 듣기 · 상대의 기분을 고려하며 말하기 · 대화 예절 지키기 · 상황에 어울리는 표정과 행동으로 대화하기. 짐작하며 대화하기 — 말과 행동에서 단서 찾기 · 경험과 배경지식 떠올리기 · 상황 고려하기. 상대를 배려하기 때문에 말과 행동을 눈여겨보게 되고, 눈여겨보기 때문에 말하지 않은 마음을 짐작할 수 있어 두 가지는 서로를 돕는다.","scoring_points":["배려하며 대화하는 방법을 썼는가","짐작하는 방법을 썼는가","서로 돕는 관계를 썼는가"]},"explanation":["두 갈래를 떠올려요.","방법을 하나씩 써요.","서로 돕는 관계로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#1','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C2',1,'ox','auto','배려는 대화를 기분 좋게 이어 가게 해 주는 태도예요.',ARRAY['K5-1-u1-X02']::text[],false,'{"seq":1,"concept":"K5-1-u1-C2","difficulty":1,"kind":"ox","stem":"배려는 대화를 기분 좋게 이어 가게 해 주는 태도예요.","answer":"O","reason_options":[{"t":"서로 기분이 상하지 않아 대화가 끊기지 않기 때문에","correct":true},{"t":"배려하면 대화에서 이기기 때문에","mis":"K5-1-u1-X02"}],"mis":"K5-1-u1-X02","explanation":["맞는 말이에요.","이기고 지는 일이 아니에요.","관계를 지키는 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#2','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C4',1,'sa','auto','짐작의 근거가 되는, 어떤 일을 풀 수 있는 실마리를 뜻하는 낱말을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K5-1-u1-C4","difficulty":1,"kind":"sa","stem":"짐작의 근거가 되는, 어떤 일을 풀 수 있는 실마리를 뜻하는 낱말을 쓰세요.","answer":["단서"],"explanation":["짐작에는 근거가 있어요.","말 · 행동 · 경험 · 상황이 그 예예요.","단서라고 해요."],"mis":"K5-1-u1-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#3','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C9',1,'match','auto','배려하며 대화하는 방법과 그 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K5-1-u1-C9","difficulty":1,"kind":"match","stem":"배려하며 대화하는 방법과 그 모습을 알맞게 이으세요.","pairs":[{"l":"집중해서 듣기","r":"끝까지 바라보며 듣는다"},{"l":"기분 고려하기","r":"탓하기 전에 마음을 헤아린다"},{"l":"대화 예절 지키기","r":"차례를 지켜 바른 말씨로 말한다"},{"l":"표정과 행동","r":"상황에 어울리는 얼굴로 대한다"}],"mis":"K5-1-u1-X09","explanation":["듣는 태도와 말하는 태도를 나누어요.","예절은 차례와 말씨예요.","표정과 행동도 말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#4','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C11',1,'mc','auto','배려하며 대화하는 방법에 대한 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X12']::text[],false,'{"seq":4,"concept":"K5-1-u1-C11","difficulty":1,"kind":"mc","stem":"배려하며 대화하는 방법에 대한 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"상황과 상대에 따라 배려하는 방법이 달라질 수 있다","correct":true},{"t":"네 가지만 외워 두면 언제나 된다","mis":"K5-1-u1-X12"},{"t":"정해진 방법 말고는 배려가 아니다","mis":"K5-1-u1-X12"},{"t":"배려하는 방법은 사람마다 같다","mis":"K5-1-u1-X12"}],"explanation":["외울 공식이 아니에요.","내가 찾은 방법도 배려예요.","상황과 상대에 따라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#5','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C16',1,'ox','auto','아직 겪지 않은 다음 주의 일도 「겪은 일」 주제로 이야기할 수 있어요.',ARRAY['K5-1-u1-X18']::text[],false,'{"seq":5,"concept":"K5-1-u1-C16","difficulty":1,"kind":"ox","stem":"아직 겪지 않은 다음 주의 일도 「겪은 일」 주제로 이야기할 수 있어요.","answer":"X","reason_options":[{"t":"겪은 일을 나누는 대화는 직접 겪은 일이어야 하기 때문에","correct":true},{"t":"다음 주의 일이 더 재미있기 때문에","mis":"K5-1-u1-X18"}],"mis":"K5-1-u1-X18","explanation":["아직 겪지 않았어요.","재미와는 관계없어요.","직접 겪은 일을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#6','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C26',1,'mc','auto','짐작한 내용을 확인하는 말로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X29','K5-1-u1-X08']::text[],false,'{"seq":6,"concept":"K5-1-u1-C26","difficulty":1,"kind":"mc","stem":"짐작한 내용을 확인하는 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「혹시 잠을 못 잤어?」","correct":true},{"t":"「너 잠 못 잤지? 다 알아.」","mis":"K5-1-u1-X29"},{"t":"「너는 늘 늦게 자더라.」","mis":"K5-1-u1-X08"},{"t":"(아무 말 없이 지나간다)","mis":"K5-1-u1-X29"}],"explanation":["단정하는 말이에요.","탓하는 말이에요.","물어서 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#7','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C33',1,'ox','auto','친구의 고민은 끝까지 들은 뒤 마음을 먼저 알아주어요.',ARRAY['K5-1-u1-X36']::text[],false,'{"seq":7,"concept":"K5-1-u1-C33","difficulty":1,"kind":"ox","stem":"친구의 고민은 끝까지 들은 뒤 마음을 먼저 알아주어요.","answer":"O","reason_options":[{"t":"잘 듣는 것이 상담의 절반이기 때문에","correct":true},{"t":"고민은 들을 필요 없이 방법만 주면 되기 때문에","mis":"K5-1-u1-X36"}],"mis":"K5-1-u1-X36","explanation":["맞는 말이에요.","방법만으로는 부족해요.","끝까지 듣고 마음을 알아줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#8','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C39',1,'ox','auto','글자가 같으면 소리의 길이도 언제나 같아요.',ARRAY['K5-1-u1-X41']::text[],false,'{"seq":8,"concept":"K5-1-u1-C39","difficulty":1,"kind":"ox","stem":"글자가 같으면 소리의 길이도 언제나 같아요.","answer":"X","reason_options":[{"t":"글자가 같아도 소리의 길이에 따라 뜻이 달라지는 낱말이 있기 때문에","correct":true},{"t":"우리말에는 긴소리가 없기 때문에","mis":"K5-1-u1-X41"}],"mis":"K5-1-u1-X41","explanation":["말과 밤이 그 예예요.","우리말에도 긴소리가 있어요.","길이로 뜻이 갈려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#9','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C10',2,'mc','auto','찬솔이가 「태블릿을 보며」 말한 행동이 문제가 되는 까닭은 어느 것인가요?',ARRAY['K5-1-u1-X04','K5-1-u1-X11','K5-1-u1-X10']::text[],false,'{"seq":9,"concept":"K5-1-u1-C10","difficulty":2,"kind":"mc","stem":"찬솔이가 「태블릿을 보며」 말한 행동이 문제가 되는 까닭은 어느 것인가요?","options":[{"t":"딴 곳을 보며 말해 새별이에게 마음이 전해지지 않기 때문이다","correct":true},{"t":"태블릿은 학교에서 쓰면 안 되기 때문이다","mis":"K5-1-u1-X04"},{"t":"말을 너무 많이 했기 때문이다","mis":"K5-1-u1-X11"},{"t":"목소리가 커졌기 때문이다","mis":"K5-1-u1-X10"}],"explanation":["규칙 이야기가 아니에요.","말의 양이 아니에요.","표정과 행동도 말이에요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#10','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C13',2,'mc','auto','다래의 말 「할머니께서 주신 거라 더 아끼던 거구나.」는 어떤 상황에 어울리는 배려의 말인가요?',ARRAY['K5-1-u1-X14','K5-1-u1-X08']::text[],false,'{"seq":10,"concept":"K5-1-u1-C13","difficulty":2,"kind":"mc","stem":"다래의 말 「할머니께서 주신 거라 더 아끼던 거구나.」는 어떤 상황에 어울리는 배려의 말인가요?","options":[{"t":"아끼던 것을 잃어 속상해할 때 마음을 알아주는 말","correct":true},{"t":"상을 받아 기뻐할 때 함께 기뻐하는 말","mis":"K5-1-u1-X14"},{"t":"부탁을 어렵게 꺼낼 때 편하게 해 주는 말","mis":"K5-1-u1-X14"},{"t":"잘못을 했을 때 따끔하게 짚는 말","mis":"K5-1-u1-X08"}],"explanation":["기쁜 상황이 아니에요.","부탁 상황도 아니에요.","속상한 마음을 알아주었어요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#11','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C27',2,'mc','auto','찬솔이의 「아…… 그래.」를 짐작하며 들어야 했던 까닭은 어느 것인가요?',ARRAY['K5-1-u1-X30','K5-1-u1-X04']::text[],false,'{"seq":11,"concept":"K5-1-u1-C27","difficulty":2,"kind":"mc","stem":"찬솔이의 「아…… 그래.」를 짐작하며 들어야 했던 까닭은 어느 것인가요?","options":[{"t":"피구 소식에 말이 갑자기 짧아지고 행동이 말과 어긋났기 때문이다","correct":true},{"t":"모든 말에는 숨은 뜻이 있기 때문이다","mis":"K5-1-u1-X30"},{"t":"찬솔이가 거짓말을 했기 때문이다","mis":"K5-1-u1-X04"},{"t":"다래가 원래 의심이 많기 때문이다","mis":"K5-1-u1-X04"}],"explanation":["모든 말을 짐작하진 않아요.","거짓말한 단서는 없어요.","짧아진 말이 신호였어요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#12','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C26',2,'ox','auto','다래가 물어 확인하지 않았다면 찬솔이가 다친 것을 몰랐을 수도 있어요.',ARRAY['K5-1-u1-X29']::text[],false,'{"seq":12,"concept":"K5-1-u1-C26","difficulty":2,"kind":"ox","stem":"다래가 물어 확인하지 않았다면 찬솔이가 다친 것을 몰랐을 수도 있어요.","answer":"O","reason_options":[{"t":"찬솔이가 「말하기가 좀 그랬어」라며 스스로 말하지 않았기 때문에","correct":true},{"t":"짐작은 묻지 않아도 늘 맞기 때문에","mis":"K5-1-u1-X29"}],"mis":"K5-1-u1-X29","explanation":["맞는 말이에요.","짐작은 틀릴 수 있어요.","물어 확인해서 알게 되었어요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#13','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C18',2,'mc','auto','다래의 준비에서 빈칸을 채울 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X20','K5-1-u1-X19']::text[],false,'{"seq":13,"concept":"K5-1-u1-C18","difficulty":2,"kind":"mc","stem":"다래의 준비에서 빈칸을 채울 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「손을 놓은 줄도 모르고 달리는 동생을 보니 대견하고 뭉클했다.」","correct":true},{"t":"「공원 끝까지 달렸다.」","mis":"K5-1-u1-X20"},{"t":"「지난 일요일 오후에」","mis":"K5-1-u1-X19"},{"t":"「아파트 앞 공원에서」","mis":"K5-1-u1-X19"}],"explanation":["있었던 일이에요.","때예요.","그때 든 마음을 담았어요."],"asset":{"type":"passage","lines":["대화 주제 — 동생에게 처음으로 자전거 타는 법을 알려 준 일","언제 — 지난 일요일 오후에","어디에서 — 아파트 앞 공원에서","무슨 일을 — 동생 자전거 뒤를 잡고 따라 뛰다가 살며시 손을 놓았는데,","　　동생이 혼자서 공원 끝까지 달렸다.","생각이나 느낌 — ?"],"title":"다래가 준비한 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#14','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C32',2,'mc','auto','「해람이는 현관에서 발을 동동 굴렀다」에서 「발을 동동 구르다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X35']::text[],false,'{"seq":14,"concept":"K5-1-u1-C32","difficulty":2,"kind":"mc","stem":"「해람이는 현관에서 발을 동동 굴렀다」에서 「발을 동동 구르다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"몹시 안타깝거나 다급해하다","correct":true},{"t":"신이 나서 춤을 추다","mis":"K5-1-u1-X35"},{"t":"추워서 몸을 녹이다","mis":"K5-1-u1-X35"},{"t":"화가 나서 소리를 지르다","mis":"K5-1-u1-X35"}],"explanation":["신나는 상황이 아니에요.","앞뒤에 추위 이야기는 없어요.","비가 쏟아지는데 우산이 없는 상황이 단서예요."],"asset":{"type":"passage","lines":["하교 시간에 갑자기 비가 쏟아졌다. 해람이는 현관에서 발을 동동 굴렀다.","아침에 엄마가 우산을 챙기라고 했는데, 그냥 뛰어나온 것이다.","그때 우산꽂이에 꽂힌 노란 우산 하나가 눈에 들어왔다.","손잡이에는 쪽지가 감겨 있었다. 「해람이에게 — 내일 돌려줘도 돼.」","쪽지의 글씨는 동글동글했다. 해람이는 어디서 본 듯한 글씨라고 생각했다."],"title":"「우산꽂이의 쪽지」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#15','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C32',2,'mc','auto','「담우가 머쓱한 듯 웃었다」에서 「머쓱하다」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X35']::text[],false,'{"seq":15,"concept":"K5-1-u1-C32","difficulty":2,"kind":"mc","stem":"「담우가 머쓱한 듯 웃었다」에서 「머쓱하다」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"쑥스럽고 어색하다","correct":true},{"t":"몹시 화가 나다","mis":"K5-1-u1-X35"},{"t":"배가 몹시 고프다","mis":"K5-1-u1-X35"},{"t":"아주 자랑스럽다","mis":"K5-1-u1-X35"}],"explanation":["웃으며 「들켰네」라고 했어요.","앞뒤와 맞지 않아요.","숨긴 일이 들켜 쑥스러운 마음이에요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#16','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C36',2,'mc','auto','고민 ④에 맞는 조언으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X39','K5-1-u1-X38']::text[],false,'{"seq":16,"concept":"K5-1-u1-C36","difficulty":2,"kind":"mc","stem":"고민 ④에 맞는 조언으로 알맞은 것은 어느 것인가요?","options":[{"t":"「쓰기 전에 먼저 물어봐 달라고 부드럽게 말해 보면 어떨까?」","correct":true},{"t":"「짝 앞에서 발표를 연습해 보면 어떨까?」","mis":"K5-1-u1-X39"},{"t":"「전날 밤에 가방을 싸 두면 어떨까?」","mis":"K5-1-u1-X39"},{"t":"「짝 물건도 말없이 가져다 써.」","mis":"K5-1-u1-X38"}],"explanation":["발표 고민에 맞는 말이에요.","아침 고민에 맞는 말이에요.","어려운 곳에 맞는 방법을 권했어요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#17','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C12',3,'error','auto','찬솔이에게 건넨 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X13','K5-1-u1-X10','K5-1-u1-X06']::text[],false,'{"seq":17,"concept":"K5-1-u1-C12","difficulty":3,"kind":"error","stem":"찬솔이에게 건넨 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「태블릿을 보면서라도 「속상하겠다」라고만 하면 돼.」","correct":true,"mis_target":"K5-1-u1-X13"},{"t":"「새별이를 바라보며 말했으면 좋았을 거야.」","mis":"K5-1-u1-X10"},{"t":"「숙제 이야기는 나중에 했으면 좋았을 거야.」","mis":"K5-1-u1-X06"}],"explanation":["바라보는 태도가 필요해요.","말을 끊지 않아야 해요.","흉내만으로는 마음이 전해지지 않아요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#18','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C25',3,'mc','auto','가온이와 루하의 대화를 보고 알맞게 짐작한 것은 어느 것인가요?',ARRAY['K5-1-u1-X28','K5-1-u1-X03']::text[],false,'{"seq":18,"concept":"K5-1-u1-C25","difficulty":3,"kind":"mc","stem":"가온이와 루하의 대화를 보고 알맞게 짐작한 것은 어느 것인가요?","options":[{"t":"㉯ — 원하는 순서가 달라 그대로 정하면 된다","correct":true},{"t":"㉮ — 순서를 두고 다투게 될 것이다","mis":"K5-1-u1-X28"},{"t":"둘 다 알 수 없다","mis":"K5-1-u1-X03"},{"t":"두 사람 모두 처음을 원한다","mis":"K5-1-u1-X28"}],"explanation":["다툴 근거가 없어요.","대화에 단서가 있어요.","「그럼 잘됐다」가 단서예요."],"asset":{"type":"passage","lines":["가온 — 「내일 모둠 발표 순서 정해야 하는데, 나는 마지막이 좋아.」","루하 — 「그래? 나는 처음이 편해. 그럼 잘됐다.」","친구의 짐작 ㉮ 두 사람은 순서를 두고 다투게 될 것이다.","친구의 짐작 ㉯ 두 사람은 원하는 순서가 달라서 그대로 정하면 된다."],"title":"가온이와 루하의 대화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#19','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C29',3,'mc','auto','해람이가 「담우가 우산을 빌려주었다」고 알게 되기까지 모은 단서로 알맞게 묶은 것은 어느 것인가요?',ARRAY['K5-1-u1-X32']::text[],false,'{"seq":19,"concept":"K5-1-u1-C29","difficulty":3,"kind":"mc","stem":"해람이가 「담우가 우산을 빌려주었다」고 알게 되기까지 모은 단서로 알맞게 묶은 것은 어느 것인가요?","options":[{"t":"동글동글한 쪽지 글씨와 알림장 글씨 · 재채기와 잠긴 목소리 · 창밖만 본 행동","correct":true},{"t":"하교 시간 · 현관 · 우산꽂이","mis":"K5-1-u1-X32"},{"t":"재채기 하나만","mis":"K5-1-u1-X32"},{"t":"엄마가 한 말 · 비가 쏟아진 때","mis":"K5-1-u1-X32"}],"explanation":["누가 두었는지와 관계없어요.","단서 하나로는 부족해요.","흩어진 단서를 모았어요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#20','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C36',3,'mc','auto','고민 ④를 쓴 친구가 가장 어려워하는 부분으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X39']::text[],false,'{"seq":20,"concept":"K5-1-u1-C36","difficulty":3,"kind":"mc","stem":"고민 ④를 쓴 친구가 가장 어려워하는 부분으로 알맞은 것은 어느 것인가요?","options":[{"t":"사이가 나빠질까 봐 짝에게 말을 꺼내기 어려운 것","correct":true},{"t":"물건이 너무 비싼 것","mis":"K5-1-u1-X39"},{"t":"짝 옆에 앉기 싫은 것","mis":"K5-1-u1-X39"},{"t":"물건을 자꾸 잃어버리는 것","mis":"K5-1-u1-X39"}],"explanation":["값 이야기는 없어요.","앉기 불편한 것은 그 결과예요.","말을 꺼내지 못하는 것이 어려운 곳이에요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#21','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C38',3,'mc','auto','다래의 두 대화에서 배려와 짐작이 함께 쓰인 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X06','K5-1-u1-X29','K5-1-u1-X12']::text[],false,'{"seq":21,"concept":"K5-1-u1-C38","difficulty":3,"kind":"mc","stem":"다래의 두 대화에서 배려와 짐작이 함께 쓰인 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"친구 곁에서 말과 행동을 눈여겨보고, 말하지 않은 마음을 짐작해 물어보았다","correct":true},{"t":"친구의 말을 끊고 짐작한 것을 알렸다","mis":"K5-1-u1-X06"},{"t":"짐작만 하고 아무 말도 하지 않았다","mis":"K5-1-u1-X29"},{"t":"배려하는 말만 외워서 그대로 했다","mis":"K5-1-u1-X12"}],"explanation":["끊고 알리면 배려가 아니에요.","짐작은 물어 확인해요.","배려와 짐작을 함께 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#22','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C40',3,'mc','auto','밑줄 친 낱말을 짧게 소리 내는 문장은 어느 것인가요? (밑줄 낱말 — 「일」)',ARRAY['K5-1-u1-X42']::text[],false,'{"seq":22,"concept":"K5-1-u1-C40","difficulty":3,"kind":"mc","stem":"밑줄 친 낱말을 짧게 소리 내는 문장은 어느 것인가요? (밑줄 낱말 — 「일」)","options":[{"t":"「일 더하기 일은 이야.」","correct":true},{"t":"「오늘 할 일을 먼저 끝냈다.」","mis":"K5-1-u1-X42"},{"t":"「일을 마치고 쉬었다.」","mis":"K5-1-u1-X42"},{"t":"「청소하는 일을 도왔다.」","mis":"K5-1-u1-X42"}],"explanation":["하는 노릇의 일은 길어요.","하는 노릇의 일은 길어요.","하나를 뜻하는 일은 짧아요."],"asset":{"type":"passage","lines":["눈[눈] 보는 몸의 부분　　눈[눈ː] 하늘에서 내리는 하얀 얼음 알갱이","벌[벌] 잘못한 사람에게 주는 괴로움　　벌[벌ː] 꿀을 모으는 곤충","일[일] 하나　　일[일ː] 무엇을 이루려고 몸이나 마음을 쓰는 것"],"title":"장단이 다른 낱말 더 보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#23','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C25',4,'mc','auto','찬솔이와 다래의 대화를 보고 한 짐작 가운데 근거가 있는 것만 모은 것은 어느 것인가요?',ARRAY['K5-1-u1-X28']::text[],false,'{"seq":23,"concept":"K5-1-u1-C25","difficulty":4,"kind":"mc","stem":"찬솔이와 다래의 대화를 보고 한 짐작 가운데 근거가 있는 것만 모은 것은 어느 것인가요?","options":[{"t":"찬솔이는 발목이 불편하다 · 피구를 하기 걱정된다","correct":true},{"t":"찬솔이는 다래를 싫어한다 · 피구를 하기 걱정된다","mis":"K5-1-u1-X28"},{"t":"찬솔이는 어제 학원에 늦었다 · 발목이 불편하다","mis":"K5-1-u1-X28"},{"t":"찬솔이는 피구를 아주 좋아한다 · 다래를 싫어한다","mis":"K5-1-u1-X28"}],"explanation":["싫어한다는 근거가 없어요.","학원 이야기는 없어요.","대화에 근거가 있는 것만 골랐어요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#24','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C34',4,'essay','teacher','고민 ④를 쓴 친구에게 상담 답장을 쓰세요. 글에 적히지 않은 마음을 짐작한 말과 세 가지 조언 요령을 모두 넣으세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u1-C34","difficulty":4,"kind":"essay","stem":"고민 ④를 쓴 친구에게 상담 답장을 쓰세요. 글에 적히지 않은 마음을 짐작한 말과 세 가지 조언 요령을 모두 넣으세요.","answer_guide":{"answer":"예: 짝에게 서운한데 사이가 나빠질까 봐 말도 못 하고 혼자 참느라 많이 불편했겠다. 나도 비슷한 일이 있었는데, 짝에게 「쓰기 전에 한 번만 말해 줄래?」라고 웃으며 말했더니 짝이 미안하다고 했어. 너도 기분 좋을 때 부드럽게 말해 보면 어떨까?","scoring_points":["적히지 않은 마음을 짐작해 썼는가","마음 → 해 본 방법 → 권하는 말투를 갖추었는가","고민의 어려운 곳에 맞는 방법인가"]},"explanation":["「불편합니다」가 단서예요.","마음을 먼저 알아줘요.","고를 여지를 남겨요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_b#25','kor',5,1,'u1','','g5_1_kor_u1_review_b','unit_review','K5-1-u1-C26',4,'essay','teacher','「짐작은 단정이 아니다」라는 말의 뜻을 쓰고, 이 단원에서 읽은 대화나 이야기 하나를 예로 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u1-C26","difficulty":4,"kind":"essay","stem":"「짐작은 단정이 아니다」라는 말의 뜻을 쓰고, 이 단원에서 읽은 대화나 이야기 하나를 예로 들어 설명하세요.","answer_guide":{"answer":"예: 짐작은 아직 맞는지 모르는 생각이라 「그럴 것이다」를 「그렇다」로 굳히지 말고 물어 확인해야 한다는 뜻이다. 다래는 찬솔이가 발목을 만지작거리는 것을 보고 다쳤다고 단정하지 않고 「혹시 발목 아파?」라고 물었다. 그래서 찬솔이가 계단에서 삐끗했다는 사실을 확인하고 선생님께 함께 말씀드릴 수 있었다.","scoring_points":["단정이 아니라는 뜻을 썼는가","단원의 대화나 이야기를 예로 들었는가","물어 확인하는 모습을 설명했는가"]},"explanation":["짐작의 성질을 떠올려요.","예를 찾아요.","확인으로 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#1','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C2',1,'mc','auto','배려하지 않은 말을 들었을 때 상대에게 생기기 쉬운 일은 어느 것인가요?',ARRAY['K5-1-u1-X02','K5-1-u1-X03']::text[],false,'{"seq":1,"concept":"K5-1-u1-C2","difficulty":1,"kind":"mc","stem":"배려하지 않은 말을 들었을 때 상대에게 생기기 쉬운 일은 어느 것인가요?","options":[{"t":"마음이 상해 말을 멈추게 된다","correct":true},{"t":"대화가 더 즐거워진다","mis":"K5-1-u1-X02"},{"t":"하고 싶은 말이 더 많아진다","mis":"K5-1-u1-X02"},{"t":"아무 일도 생기지 않는다","mis":"K5-1-u1-X03"}],"explanation":["즐거워지지 않아요.","도현이도 말을 멈췄어요.","마음이 상하면 대화가 끊겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#2','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C3',1,'ox','auto','우리는 서로 알고 있다고 여기는 부분을 줄여서 말하기도 해요.',ARRAY['K5-1-u1-X03']::text[],false,'{"seq":2,"concept":"K5-1-u1-C3","difficulty":1,"kind":"ox","stem":"우리는 서로 알고 있다고 여기는 부분을 줄여서 말하기도 해요.","answer":"O","reason_options":[{"t":"아는 것을 모두 말하지 않아 대화에 빈 곳이 생기기 때문에","correct":true},{"t":"말을 줄이는 것은 대화를 못 하는 사람뿐이기 때문에","mis":"K5-1-u1-X03"}],"mis":"K5-1-u1-X03","explanation":["맞는 말이에요.","누구나 줄여 말해요.","그래서 짐작이 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#3','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C9',1,'ox','auto','친한 친구끼리는 놀리는 말을 섞어도 대화 예절에 어긋나지 않아요.',ARRAY['K5-1-u1-X09']::text[],false,'{"seq":3,"concept":"K5-1-u1-C9","difficulty":1,"kind":"ox","stem":"친한 친구끼리는 놀리는 말을 섞어도 대화 예절에 어긋나지 않아요.","answer":"X","reason_options":[{"t":"친한 사이에서도 놀리는 말은 마음을 다치게 하기 때문에","correct":true},{"t":"친한 사이에는 예절이 필요 없기 때문에","mis":"K5-1-u1-X09"}],"mis":"K5-1-u1-X09","explanation":["친해도 마음은 다쳐요.","예절은 모든 대화에 필요해요.","바른 말씨를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#4','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C12',1,'mc','auto','「형식만 갖춘 배려」에 해당하는 것은 어느 것인가요?',ARRAY['K5-1-u1-X13','K5-1-u1-X07']::text[],false,'{"seq":4,"concept":"K5-1-u1-C12","difficulty":1,"kind":"mc","stem":"「형식만 갖춘 배려」에 해당하는 것은 어느 것인가요?","options":[{"t":"휴대 전화를 보며 「힘들었겠다.」라고만 한다","correct":true},{"t":"하던 일을 멈추고 바라보며 말한다","mis":"K5-1-u1-X13"},{"t":"상대의 처지를 실제로 생각해 본다","mis":"K5-1-u1-X13"},{"t":"언제부터 그랬는지 물어본다","mis":"K5-1-u1-X07"}],"explanation":["진심이 담긴 모습이에요.","처지를 생각하는 게 먼저예요.","말만 하고 마음은 딴 곳에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#5','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C15',1,'mc','auto','주제를 정하여 대화할 때 맨 먼저 할 일은 어느 것인가요?',ARRAY['K5-1-u1-X16']::text[],false,'{"seq":5,"concept":"K5-1-u1-C15","difficulty":1,"kind":"mc","stem":"주제를 정하여 대화할 때 맨 먼저 할 일은 어느 것인가요?","options":[{"t":"무엇을 이야기할지 주제를 정한다","correct":true},{"t":"대화를 잘했는지 점검한다","mis":"K5-1-u1-X16"},{"t":"친구를 칭찬한다","mis":"K5-1-u1-X16"},{"t":"바로 대화를 시작한다","mis":"K5-1-u1-X16"}],"explanation":["점검은 마지막이에요.","칭찬은 대화 뒤에 해요.","주제를 정하고 준비해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#6','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C22',1,'ox','auto','생략된 내용은 말뿐 아니라 행동이나 상황에서도 짐작할 수 있어요.',ARRAY['K5-1-u1-X24']::text[],false,'{"seq":6,"concept":"K5-1-u1-C22","difficulty":1,"kind":"ox","stem":"생략된 내용은 말뿐 아니라 행동이나 상황에서도 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"말 · 행동 · 경험과 배경지식 · 상황이 모두 단서가 되기 때문에","correct":true},{"t":"말에서만 단서를 찾아야 하기 때문에","mis":"K5-1-u1-X24"}],"mis":"K5-1-u1-X24","explanation":["맞는 말이에요.","말만이 단서가 아니에요.","네 가지 단서를 살펴요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#7','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C33',1,'mc','auto','고민을 들을 때 알맞은 태도는 어느 것인가요?',ARRAY['K5-1-u1-X36','K5-1-u1-X06']::text[],false,'{"seq":7,"concept":"K5-1-u1-C33","difficulty":1,"kind":"mc","stem":"고민을 들을 때 알맞은 태도는 어느 것인가요?","options":[{"t":"자세히 물어 확인한다","correct":true},{"t":"가벼운 일이라고 넘긴다","mis":"K5-1-u1-X36"},{"t":"다른 친구에게 옮긴다","mis":"K5-1-u1-X36"},{"t":"듣는 중에 내 고민을 꺼낸다","mis":"K5-1-u1-X06"}],"explanation":["가볍게 넘기면 마음이 다쳐요.","고민은 옮기지 않아요.","물어 확인하며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#8','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C40',1,'mc','auto','「밤나무에서 밤이 떨어졌다」의 「밤」은 어떻게 소리 내나요?',ARRAY['K5-1-u1-X42','K5-1-u1-X41']::text[],false,'{"seq":8,"concept":"K5-1-u1-C40","difficulty":1,"kind":"mc","stem":"「밤나무에서 밤이 떨어졌다」의 「밤」은 어떻게 소리 내나요?","options":[{"t":"[밤ː]","correct":true},{"t":"[밤]","mis":"K5-1-u1-X42"},{"t":"[바암]","mis":"K5-1-u1-X41"},{"t":"[반]","mis":"K5-1-u1-X41"}],"explanation":["짧은 [밤]은 해가 진 뒤예요.","길이를 [ː]로 나타내요.","열매 밤은 길게 소리 내요."],"asset":{"type":"passage","lines":["말[말] 사람이 타는 동물　　말[말ː] 생각을 나타내는 소리","밤[밤] 해가 진 뒤의 어두운 때　　밤[밤ː] 밤나무의 열매","길게 소리 낼 때에는 [ː] 표시를 합니다."],"title":"같은 글자, 다른 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#9','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C8',2,'mc','auto','「그거 또 사면 되잖아.」가 배려하지 않은 말인 까닭은 어느 것인가요?',ARRAY['K5-1-u1-X04','K5-1-u1-X08','K5-1-u1-X15']::text[],false,'{"seq":9,"concept":"K5-1-u1-C8","difficulty":2,"kind":"mc","stem":"「그거 또 사면 되잖아.」가 배려하지 않은 말인 까닭은 어느 것인가요?","options":[{"t":"할머니께서 주신 물건이라 아끼던 마음을 헤아리지 않았기 때문이다","correct":true},{"t":"머리핀 값을 말하지 않았기 때문이다","mis":"K5-1-u1-X04"},{"t":"새별이가 잘못을 했기 때문이다","mis":"K5-1-u1-X08"},{"t":"새로 사면 정말 다 해결되기 때문이다","mis":"K5-1-u1-X15"}],"explanation":["값 이야기가 아니에요.","탓할 일이 아니에요.","물건에 담긴 마음을 봐야 해요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#10','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C10',2,'mc','auto','다래가 「새별이 옆에 앉으며」 말한 행동이 알려 주는 것은 어느 것인가요?',ARRAY['K5-1-u1-X09','K5-1-u1-X04']::text[],false,'{"seq":10,"concept":"K5-1-u1-C10","difficulty":2,"kind":"mc","stem":"다래가 「새별이 옆에 앉으며」 말한 행동이 알려 주는 것은 어느 것인가요?","options":[{"t":"새별이의 이야기에 마음을 쓰고 있다","correct":true},{"t":"새별이를 놀리려 한다","mis":"K5-1-u1-X09"},{"t":"앉을 곳을 바꾸고 싶다","mis":"K5-1-u1-X04"},{"t":"숙제를 보여 달라고 하려 한다","mis":"K5-1-u1-X04"}],"explanation":["놀리는 단서가 없어요.","그런 단서가 없어요.","곁에 앉는 행동도 말이에요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#11','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C24',2,'mc','auto','다래가 짐작한 과정을 두 걸음으로 바르게 나눈 것은 어느 것인가요?',ARRAY['K5-1-u1-X27','K5-1-u1-X24']::text[],false,'{"seq":11,"concept":"K5-1-u1-C24","difficulty":2,"kind":"mc","stem":"다래가 짐작한 과정을 두 걸음으로 바르게 나눈 것은 어느 것인가요?","options":[{"t":"발목을 만지는 행동을 확인함 → 피구를 앞두고 말이 짧아진 상황과 이어 봄","correct":true},{"t":"바로 「다쳤구나」라고 정함 → 선생님께 알림","mis":"K5-1-u1-X27"},{"t":"피구가 싫은가 보다고 넘겨짚음 → 더 묻지 않음","mis":"K5-1-u1-X27"},{"t":"찬솔이의 말만 들음 → 행동은 보지 않음","mis":"K5-1-u1-X24"}],"explanation":["확인 없이 정했어요.","넘겨짚었어요.","드러난 것 → 연결이에요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#12','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C30',2,'mc','auto','찬솔이가 「말하기가 좀 그랬어.」라고 한 말에서 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u1-X33','K5-1-u1-X28']::text[],false,'{"seq":12,"concept":"K5-1-u1-C30","difficulty":2,"kind":"mc","stem":"찬솔이가 「말하기가 좀 그랬어.」라고 한 말에서 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"다친 것을 먼저 말하기가 쑥스럽거나 걱정되었다","correct":true},{"t":"다래가 싫었다","mis":"K5-1-u1-X33"},{"t":"발목이 하나도 아프지 않았다","mis":"K5-1-u1-X28"},{"t":"피구를 정말 하고 싶었다","mis":"K5-1-u1-X28"}],"explanation":["싫다는 단서는 없어요.","아프다고 했어요.","말하지 못한 까닭이 있었어요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#13','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C17',2,'match','auto','다래가 정리한 내용과 항목을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"K5-1-u1-C17","difficulty":2,"kind":"match","stem":"다래가 정리한 내용과 항목을 알맞게 이으세요.","pairs":[{"l":"지난 일요일 오후에","r":"언제"},{"l":"아파트 앞 공원에서","r":"어디에서"},{"l":"동생이 혼자서 공원 끝까지 달렸다","r":"무슨 일을"}],"mis":"K5-1-u1-X19","explanation":["때를 찾아요.","곳을 찾아요.","일어난 일을 찾아요."],"asset":{"type":"passage","lines":["대화 주제 — 동생에게 처음으로 자전거 타는 법을 알려 준 일","언제 — 지난 일요일 오후에","어디에서 — 아파트 앞 공원에서","무슨 일을 — 동생 자전거 뒤를 잡고 따라 뛰다가 살며시 손을 놓았는데,","　　동생이 혼자서 공원 끝까지 달렸다.","생각이나 느낌 — ?"],"title":"다래가 준비한 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#14','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C29',2,'mc','auto','쪽지를 남긴 사람을 짐작하는 데 단서가 될 만한 것은 어느 것인가요?',ARRAY['K5-1-u1-X32']::text[],false,'{"seq":14,"concept":"K5-1-u1-C29","difficulty":2,"kind":"mc","stem":"쪽지를 남긴 사람을 짐작하는 데 단서가 될 만한 것은 어느 것인가요?","options":[{"t":"쪽지의 동글동글한 글씨","correct":true},{"t":"하교 시간이라는 때","mis":"K5-1-u1-X32"},{"t":"엄마가 우산을 챙기라고 한 일","mis":"K5-1-u1-X32"},{"t":"우산꽂이가 현관에 있다는 것","mis":"K5-1-u1-X32"}],"explanation":["누가 두었는지 알려 주지 않아요.","쪽지와 관계없는 일이에요.","어디서 본 듯한 글씨가 단서예요."],"asset":{"type":"passage","lines":["하교 시간에 갑자기 비가 쏟아졌다. 해람이는 현관에서 발을 동동 굴렀다.","아침에 엄마가 우산을 챙기라고 했는데, 그냥 뛰어나온 것이다.","그때 우산꽂이에 꽂힌 노란 우산 하나가 눈에 들어왔다.","손잡이에는 쪽지가 감겨 있었다. 「해람이에게 — 내일 돌려줘도 돼.」","쪽지의 글씨는 동글동글했다. 해람이는 어디서 본 듯한 글씨라고 생각했다."],"title":"「우산꽂이의 쪽지」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#15','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C29',2,'mc','auto','담우가 우산을 빌려주었다고 볼 수 있는 단서가 아닌 것은 어느 것인가요?',ARRAY['K5-1-u1-X32']::text[],false,'{"seq":15,"concept":"K5-1-u1-C29","difficulty":2,"kind":"mc","stem":"담우가 우산을 빌려주었다고 볼 수 있는 단서가 아닌 것은 어느 것인가요?","options":[{"t":"담우가 해람이의 짝이라는 것","correct":true},{"t":"연달아 재채기를 하고 목소리가 잠긴 것","mis":"K5-1-u1-X32"},{"t":"알림장의 동글동글한 글씨","mis":"K5-1-u1-X32"},{"t":"노란 우산 이야기에 창밖만 본 것","mis":"K5-1-u1-X32"}],"explanation":["비를 맞은 흔적이에요.","쪽지 글씨와 같아요.","짝이라는 것만으로는 우산과 이어지지 않아요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#16','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C35',2,'mc','auto','고민 ④에 대한 조언을 시작하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X38']::text[],false,'{"seq":16,"concept":"K5-1-u1-C35","difficulty":2,"kind":"mc","stem":"고민 ④에 대한 조언을 시작하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「말하지 못하고 혼자 참느라 많이 불편했겠다.」","correct":true},{"t":"「그런 것도 말 못 해?」","mis":"K5-1-u1-X38"},{"t":"「그냥 참아.」","mis":"K5-1-u1-X38"},{"t":"「나라면 바로 화냈을 거야.」","mis":"K5-1-u1-X38"}],"explanation":["탓하는 말이에요.","마음을 알아주지 않았어요.","마음을 먼저 알아줘요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#17','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C14',3,'mc','auto','찬솔이와 다래의 말을 견주었을 때, 다래의 말에서 배울 점으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X10','K5-1-u1-X15','K5-1-u1-X08']::text[],false,'{"seq":17,"concept":"K5-1-u1-C14","difficulty":3,"kind":"mc","stem":"찬솔이와 다래의 말을 견주었을 때, 다래의 말에서 배울 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"먼저 마음을 받아 준 뒤 함께할 방법을 보탰다","correct":true},{"t":"찬솔이보다 목소리를 크게 했다","mis":"K5-1-u1-X10"},{"t":"잃어버린 까닭을 따져 물었다","mis":"K5-1-u1-X15"},{"t":"찬솔이의 말을 바로 고쳐 주었다","mis":"K5-1-u1-X08"}],"explanation":["목소리 이야기가 아니에요.","까닭을 따지지 않았어요.","마음 → 도울 방법의 차례예요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#18','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C24',3,'error','auto','가온이와 루하의 대화를 짐작한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X27','K5-1-u1-X24','K5-1-u1-X25']::text[],false,'{"seq":18,"concept":"K5-1-u1-C24","difficulty":3,"kind":"error","stem":"가온이와 루하의 대화를 짐작한 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「순서 이야기가 나오면 늘 다투니까 ㉮가 맞아.」","correct":true,"mis_target":"K5-1-u1-X27"},{"t":"「루하가 〈잘됐다〉고 한 말부터 확인하자.」","mis":"K5-1-u1-X24"},{"t":"「가온이는 마지막, 루하는 처음이 좋다고 했어.」","mis":"K5-1-u1-X25"}],"explanation":["드러난 말부터 확인했어요.","두 사람의 말을 정확히 붙잡았어요.","말을 확인하지 않고 넘겨짚었어요."],"asset":{"type":"passage","lines":["가온 — 「내일 모둠 발표 순서 정해야 하는데, 나는 마지막이 좋아.」","루하 — 「그래? 나는 처음이 편해. 그럼 잘됐다.」","친구의 짐작 ㉮ 두 사람은 순서를 두고 다투게 될 것이다.","친구의 짐작 ㉯ 두 사람은 원하는 순서가 달라서 그대로 정하면 된다."],"title":"가온이와 루하의 대화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#19','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C31',3,'mc','auto','「우산꽂이의 쪽지」를 간추릴 때 빼도 되는 내용은 어느 것인가요?',ARRAY['K5-1-u1-X34']::text[],false,'{"seq":19,"concept":"K5-1-u1-C31","difficulty":3,"kind":"mc","stem":"「우산꽂이의 쪽지」를 간추릴 때 빼도 되는 내용은 어느 것인가요?","options":[{"t":"해람이가 현관에서 발을 동동 굴렀다","correct":true},{"t":"노란 우산에 쪽지가 감겨 있었다","mis":"K5-1-u1-X34"},{"t":"담우의 알림장 글씨가 쪽지 글씨와 같았다","mis":"K5-1-u1-X34"},{"t":"해람이가 우산을 담우에게 돌려주었다","mis":"K5-1-u1-X34"}],"explanation":["사건의 시작이에요.","알게 되는 중요한 단서예요.","다급한 모습을 보여 주는 묘사는 빼도 돼요."],"asset":{"type":"passage","lines":["하교 시간에 갑자기 비가 쏟아졌다. 해람이는 현관에서 발을 동동 굴렀다.","아침에 엄마가 우산을 챙기라고 했는데, 그냥 뛰어나온 것이다.","그때 우산꽂이에 꽂힌 노란 우산 하나가 눈에 들어왔다.","손잡이에는 쪽지가 감겨 있었다. 「해람이에게 — 내일 돌려줘도 돼.」","쪽지의 글씨는 동글동글했다. 해람이는 어디서 본 듯한 글씨라고 생각했다."],"title":"「우산꽂이의 쪽지」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#20','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C33',3,'error','auto','고민 ④를 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X36']::text[],false,'{"seq":20,"concept":"K5-1-u1-C33","difficulty":3,"kind":"error","stem":"고민 ④를 들은 친구들의 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「그 짝이 누군지 반 친구들에게 알려 주자.」","correct":true,"mis_target":"K5-1-u1-X36"},{"t":"「언제부터 그랬는지 더 말해 줄래?」","mis":"K5-1-u1-X36"},{"t":"「말 못 하고 참느라 힘들었겠다.」","mis":"K5-1-u1-X36"}],"explanation":["물어 확인했어요.","마음을 알아주었어요.","고민은 다른 친구에게 옮기지 않아요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#21','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C5',3,'error','auto','이 단원에서 배운 것을 정리한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u1-X05','K5-1-u1-X06','K5-1-u1-X38']::text[],false,'{"seq":21,"concept":"K5-1-u1-C5","difficulty":3,"kind":"error","stem":"이 단원에서 배운 것을 정리한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「배려하며 대화하기와 짐작하며 대화하기는 서로 관계가 없어.」","correct":true,"mis_target":"K5-1-u1-X05"},{"t":"「잘 듣는 사람이 결국 대화를 이끌어.」","mis":"K5-1-u1-X06"},{"t":"「상대를 배려하니까 말과 행동을 눈여겨보게 돼.」","mis":"K5-1-u1-X38"}],"explanation":["잘 듣기가 바탕이에요.","배려가 눈여겨보기로 이어져요.","두 가지는 서로를 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#22','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C21',3,'mc','auto','대화를 마친 뒤 친구를 칭찬한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X23','K5-1-u1-X22','K5-1-u1-X09']::text[],false,'{"seq":22,"concept":"K5-1-u1-C21","difficulty":3,"kind":"mc","stem":"대화를 마친 뒤 친구를 칭찬한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「내가 머뭇거릴 때 〈그래서 어떻게 됐어?〉 하고 물어 줘서 말하기 편했어.」","correct":true},{"t":"「그냥 좋았어.」","mis":"K5-1-u1-X23"},{"t":"「다음엔 나도 많이 말하게 해 줘.」","mis":"K5-1-u1-X22"},{"t":"「네 이야기는 별로였어.」","mis":"K5-1-u1-X09"}],"explanation":["무엇이 좋았는지 빠졌어요.","칭찬이 아니에요.","잘한 점을 짚어 칭찬했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#23','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C14',4,'mc','auto','찬솔이가 새별이에게 다시 건넬 말로 배려와 짐작을 모두 담은 것은 어느 것인가요?',ARRAY['K5-1-u1-X15','K5-1-u1-X06','K5-1-u1-X29']::text[],false,'{"seq":23,"concept":"K5-1-u1-C14","difficulty":4,"kind":"mc","stem":"찬솔이가 새별이에게 다시 건넬 말로 배려와 짐작을 모두 담은 것은 어느 것인가요?","options":[{"t":"「아까 말을 끊어서 미안해. 할머니 생각이 나서 더 속상했겠다. 체육관부터 같이 가 볼까?」","correct":true},{"t":"「미안. 그런데 머리핀은 또 사면 되잖아.」","mis":"K5-1-u1-X15"},{"t":"「할머니가 주신 거구나. 숙제는 했어?」","mis":"K5-1-u1-X06"},{"t":"「너 그거 일부러 잃어버린 거 아니야?」","mis":"K5-1-u1-X29"}],"explanation":["다시 가볍게 넘겼어요.","또 말을 끊었어요.","사과하고 마음을 짐작하며 도울 방법을 보탰어요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#24','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C14',4,'essay','teacher','찬솔이가 되어 새별이에게 배려하며 다시 대답하는 말을 쓰고, 처음 대답에서 무엇을 고쳤는지 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u1-C14","difficulty":4,"kind":"essay","stem":"찬솔이가 되어 새별이에게 배려하며 다시 대답하는 말을 쓰고, 처음 대답에서 무엇을 고쳤는지 두 가지 쓰세요.","answer_guide":{"answer":"예: (태블릿을 내려놓고 새별이를 바라보며) 「할머니께서 주신 머리핀이라 정말 속상하겠다. 체육 시간 전까지 있었다면 체육관에 떨어졌을지도 몰라. 같이 가 보자.」 고친 점 — 첫째, 딴 곳을 보지 않고 바라보며 말했다. 둘째, 「또 사면 되잖아」처럼 가볍게 넘기지 않고 아끼던 마음을 먼저 알아준 뒤 함께 찾자고 했다.","scoring_points":["배려하는 대답을 썼는가","표정과 행동까지 고쳤는가","고친 점을 두 가지 밝혔는가"]},"explanation":["처음 대답의 문제를 떠올려요.","마음을 먼저 받아 줘요.","태도까지 고쳐요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_c#25','kor',5,1,'u1','','g5_1_kor_u1_review_c','unit_review','K5-1-u1-C11',4,'essay','teacher','「배려에는 정해진 공식이 없다」와 「형식만 갖춘 배려는 전해지지 않는다」를 함께 생각하여, 배려하며 대화할 때 가장 중요한 것이 무엇인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u1-C11","difficulty":4,"kind":"essay","stem":"「배려에는 정해진 공식이 없다」와 「형식만 갖춘 배려는 전해지지 않는다」를 함께 생각하여, 배려하며 대화할 때 가장 중요한 것이 무엇인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 배려하며 대화할 때 가장 중요한 것은 상대를 향한 진심이다. 배려하는 방법은 상황과 상대에 따라 달라지므로 정해진 방법을 외우는 것보다 상대의 처지를 실제로 생각해 보는 것이 먼저이다. 또 같은 말이라도 딴 곳을 보며 하면 마음이 없다는 것을 상대가 알아채기 때문이다.","scoring_points":["가장 중요한 것을 밝혔는가","공식이 없다는 뜻과 이었는가","형식만 갖춘 배려와 견주었는가"]},"explanation":["두 말을 함께 봐요.","방법보다 마음을 봐요.","까닭을 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#1','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C1',1,'blank','auto','배려하며 대화하기의 뜻에 맞게 빈칸에 들어갈 말은 어느 것인가요? — 상대의 (　)에서 생각하고 그 마음에 맞게 말과 태도를 고르는 것',ARRAY['K5-1-u1-X08','K5-1-u1-X10','K5-1-u1-X07']::text[],false,'{"seq":1,"concept":"K5-1-u1-C1","difficulty":1,"kind":"blank","stem":"배려하며 대화하기의 뜻에 맞게 빈칸에 들어갈 말은 어느 것인가요? — 상대의 (　)에서 생각하고 그 마음에 맞게 말과 태도를 고르는 것","options":[{"t":"처지","correct":true},{"t":"잘못","mis":"K5-1-u1-X08"},{"t":"목소리","mis":"K5-1-u1-X10"},{"t":"대답","mis":"K5-1-u1-X07"}],"explanation":["잘못을 찾는 게 아니에요.","목소리만의 일이 아니에요.","상대의 처지에서 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#2','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C4',1,'mc','auto','짐작에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X04']::text[],false,'{"seq":2,"concept":"K5-1-u1-C4","difficulty":1,"kind":"mc","stem":"짐작에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"짐작에는 늘 단서라는 근거가 있어야 한다","correct":true},{"t":"짐작은 느낌만으로 해도 된다","mis":"K5-1-u1-X04"},{"t":"짐작은 바라는 대로 하면 된다","mis":"K5-1-u1-X04"},{"t":"짐작에는 근거가 필요 없다","mis":"K5-1-u1-X04"}],"explanation":["느낌은 근거가 아니에요.","바람도 근거가 아니에요.","단서를 보고 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#3','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C8',1,'mc','auto','상대의 기분을 고려하며 말한 것은 어느 것인가요?',ARRAY['K5-1-u1-X08']::text[],false,'{"seq":3,"concept":"K5-1-u1-C8","difficulty":1,"kind":"mc","stem":"상대의 기분을 고려하며 말한 것은 어느 것인가요?","options":[{"t":"「많이 놀랐겠다. 괜찮아?」","correct":true},{"t":"「그러니까 내가 뭐랬어.」","mis":"K5-1-u1-X08"},{"t":"「그건 네 잘못이야.」","mis":"K5-1-u1-X08"},{"t":"「나는 그런 적 없는데.」","mis":"K5-1-u1-X08"}],"explanation":["탓하는 말이에요.","잘못을 먼저 짚었어요.","마음을 먼저 헤아렸어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#4','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C12',1,'ox','auto','배려하는 말을 흉내만 내도 상대는 마음이 담긴 것인지 알아채지 못해요.',ARRAY['K5-1-u1-X13']::text[],false,'{"seq":4,"concept":"K5-1-u1-C12","difficulty":1,"kind":"ox","stem":"배려하는 말을 흉내만 내도 상대는 마음이 담긴 것인지 알아채지 못해요.","answer":"X","reason_options":[{"t":"같은 말이라도 마음이 없으면 상대는 알아채기 때문에","correct":true},{"t":"배려는 말만으로 전해지기 때문에","mis":"K5-1-u1-X13"}],"mis":"K5-1-u1-X13","explanation":["상대는 알아채요.","태도가 함께 전해져요.","흉내보다 진심이 먼저예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#5','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C16',1,'mc','auto','대화 주제로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X18','K5-1-u1-X17']::text[],false,'{"seq":5,"concept":"K5-1-u1-C16","difficulty":1,"kind":"mc","stem":"대화 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"아끼던 화분이 시들어 속상했던 일","correct":true},{"t":"친구가 숨기고 싶어 하는 일","mis":"K5-1-u1-X18"},{"t":"아직 가 보지 않은 다음 달 여행","mis":"K5-1-u1-X18"},{"t":"특별한 상을 받은 일만","mis":"K5-1-u1-X17"}],"explanation":["친구의 비밀은 주제가 아니에요.","아직 겪지 않았어요.","슬펐던 일도 주제가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#6','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C26',1,'mc','auto','짐작한 내용이 어떤 생각인지 바르게 말한 것은 어느 것인가요?',ARRAY['K5-1-u1-X29']::text[],false,'{"seq":6,"concept":"K5-1-u1-C26","difficulty":1,"kind":"mc","stem":"짐작한 내용이 어떤 생각인지 바르게 말한 것은 어느 것인가요?","options":[{"t":"짐작은 아직 맞는지 모르는 생각이다","correct":true},{"t":"짐작은 이미 확인된 사실이다","mis":"K5-1-u1-X29"},{"t":"짐작은 틀릴 수 없다","mis":"K5-1-u1-X29"},{"t":"짐작한 것은 바로 알려도 된다","mis":"K5-1-u1-X29"}],"explanation":["확인 전이에요.","틀릴 수 있어요.","물어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#7','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C37',1,'mc','auto','배운 것을 실천할 활동을 정하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X40','K5-1-u1-X21']::text[],false,'{"seq":7,"concept":"K5-1-u1-C37","difficulty":1,"kind":"mc","stem":"배운 것을 실천할 활동을 정하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"반에서 함께 의논해 정한다","correct":true},{"t":"고민 상담소 하나로만 정해져 있다","mis":"K5-1-u1-X40"},{"t":"한 사람이 혼자 정한다","mis":"K5-1-u1-X21"},{"t":"정하지 않고 아무것도 하지 않는다","mis":"K5-1-u1-X40"}],"explanation":["여러 활동이 있어요.","함께 정해요.","대화 빙고 같은 활동도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#8','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C40',1,'mc','auto','「들판에 말 한 마리가 서 있다」의 「말」은 어떻게 소리 내나요?',ARRAY['K5-1-u1-X42','K5-1-u1-X41']::text[],false,'{"seq":8,"concept":"K5-1-u1-C40","difficulty":1,"kind":"mc","stem":"「들판에 말 한 마리가 서 있다」의 「말」은 어떻게 소리 내나요?","options":[{"t":"[말]","correct":true},{"t":"[말ː]","mis":"K5-1-u1-X42"},{"t":"[마알]","mis":"K5-1-u1-X41"},{"t":"[만]","mis":"K5-1-u1-X41"}],"explanation":["긴 [말ː]은 생각을 나타내는 소리예요.","길이는 [ː]로 나타내요.","타는 동물 말은 짧게 소리 내요."],"asset":{"type":"passage","lines":["말[말] 사람이 타는 동물　　말[말ː] 생각을 나타내는 소리","밤[밤] 해가 진 뒤의 어두운 때　　밤[밤ː] 밤나무의 열매","길게 소리 낼 때에는 [ː] 표시를 합니다."],"title":"같은 글자, 다른 길이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#9','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C3',2,'mc','auto','새별이가 「…….」 하고 말을 멈춘 데에 생략된 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X28']::text[],false,'{"seq":9,"concept":"K5-1-u1-C3","difficulty":2,"kind":"mc","stem":"새별이가 「…….」 하고 말을 멈춘 데에 생략된 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"찬솔이가 마음을 몰라주어 서운하다","correct":true},{"t":"수학 숙제를 다 해서 할 말이 없다","mis":"K5-1-u1-X28"},{"t":"머리핀을 벌써 찾았다","mis":"K5-1-u1-X28"},{"t":"찬솔이의 말에 기분이 좋아졌다","mis":"K5-1-u1-X28"}],"explanation":["숙제 이야기는 단서가 아니에요.","찾았다는 근거가 없어요.","말을 멈춘 것이 서운함의 단서예요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#10','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C1',2,'ox','auto','다래는 새별이의 처지에서 생각하고 그 마음에 맞게 말했어요.',ARRAY['K5-1-u1-X11']::text[],false,'{"seq":10,"concept":"K5-1-u1-C1","difficulty":2,"kind":"ox","stem":"다래는 새별이의 처지에서 생각하고 그 마음에 맞게 말했어요.","answer":"O","reason_options":[{"t":"물건에 담긴 마음을 알아주고 찾는 일을 함께하려 했기 때문에","correct":true},{"t":"다래가 찬솔이보다 말을 더 많이 했기 때문에","mis":"K5-1-u1-X11"}],"mis":"K5-1-u1-X11","explanation":["맞는 말이에요.","말의 양 때문이 아니에요.","처지에서 생각했어요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#11','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C22',2,'match','auto','찬솔이와 다래의 대화에서 단서와 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"K5-1-u1-C22","difficulty":2,"kind":"match","stem":"찬솔이와 다래의 대화에서 단서와 그 갈래를 알맞게 이으세요.","pairs":[{"l":"발목을 만지작거림","r":"행동"},{"l":"「아…… 그래.」라는 짧은 대답","r":"말"},{"l":"곧 피구를 하는 체육 시간","r":"상황"}],"mis":"K5-1-u1-X25","explanation":["본 것이 행동이에요.","들은 것이 말이에요.","그때의 형편이 상황이에요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#12','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C5',2,'mc','auto','다래가 찬솔이의 마음을 짐작할 수 있었던 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X24','K5-1-u1-X04','K5-1-u1-X05']::text[],false,'{"seq":12,"concept":"K5-1-u1-C5","difficulty":2,"kind":"mc","stem":"다래가 찬솔이의 마음을 짐작할 수 있었던 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"찬솔이를 배려하며 말과 행동을 눈여겨보았기 때문이다","correct":true},{"t":"찬솔이의 말만 들었기 때문이다","mis":"K5-1-u1-X24"},{"t":"짐작은 아무나 맞히기 때문이다","mis":"K5-1-u1-X04"},{"t":"배려와 짐작은 관계가 없기 때문이다","mis":"K5-1-u1-X05"}],"explanation":["행동도 보았어요.","근거가 있었어요.","배려하니 눈여겨보게 되었어요."],"asset":{"type":"speech","turns":[{"who":"다래","text":"오늘 체육 시간에 피구 한대!"},{"who":"찬솔","text":"(발목을 만지작거리며) 아…… 그래."},{"who":"다래","text":"혹시 발목 아파? 어디 다쳤어?"},{"who":"찬솔","text":"응, 어제 계단에서 살짝 삐끗했거든. 말하기가 좀 그랬어."},{"who":"다래","text":"그럼 선생님께 같이 말씀드리러 가자."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#13','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C16',2,'ox','auto','다래가 고른 주제는 크고 특별한 일이 아니어서 대화 주제로 알맞지 않아요.',ARRAY['K5-1-u1-X17']::text[],false,'{"seq":13,"concept":"K5-1-u1-C16","difficulty":2,"kind":"ox","stem":"다래가 고른 주제는 크고 특별한 일이 아니어서 대화 주제로 알맞지 않아요.","answer":"X","reason_options":[{"t":"직접 겪은 일이면 작은 일도 대화 주제가 될 수 있기 때문에","correct":true},{"t":"대화 주제는 특별한 일이어야 하기 때문에","mis":"K5-1-u1-X17"}],"mis":"K5-1-u1-X17","explanation":["작은 일도 괜찮아요.","직접 겪은 일이에요.","겪은 일이면 주제가 돼요."],"asset":{"type":"passage","lines":["대화 주제 — 동생에게 처음으로 자전거 타는 법을 알려 준 일","언제 — 지난 일요일 오후에","어디에서 — 아파트 앞 공원에서","무슨 일을 — 동생 자전거 뒤를 잡고 따라 뛰다가 살며시 손을 놓았는데,","　　동생이 혼자서 공원 끝까지 달렸다.","생각이나 느낌 — ?"],"title":"다래가 준비한 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#14','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C28',2,'ox','auto','앞부분만 읽어도 우산을 꽂아 둔 사람이 누구인지 바로 알 수 있어요.',ARRAY['K5-1-u1-X31']::text[],false,'{"seq":14,"concept":"K5-1-u1-C28","difficulty":2,"kind":"ox","stem":"앞부분만 읽어도 우산을 꽂아 둔 사람이 누구인지 바로 알 수 있어요.","answer":"X","reason_options":[{"t":"글쓴이가 누구인지 밝히지 않고 글씨라는 단서만 남겨 두었기 때문에","correct":true},{"t":"쪽지에 이름이 적혀 있기 때문에","mis":"K5-1-u1-X31"}],"mis":"K5-1-u1-X31","explanation":["빈 곳으로 남겨 두었어요.","이름은 적혀 있지 않아요.","단서를 모아 채우며 읽어요."],"asset":{"type":"passage","lines":["하교 시간에 갑자기 비가 쏟아졌다. 해람이는 현관에서 발을 동동 굴렀다.","아침에 엄마가 우산을 챙기라고 했는데, 그냥 뛰어나온 것이다.","그때 우산꽂이에 꽂힌 노란 우산 하나가 눈에 들어왔다.","손잡이에는 쪽지가 감겨 있었다. 「해람이에게 — 내일 돌려줘도 돼.」","쪽지의 글씨는 동글동글했다. 해람이는 어디서 본 듯한 글씨라고 생각했다."],"title":"「우산꽂이의 쪽지」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#15','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C30',2,'mc','auto','해람이가 말을 꺼내자 담우가 창밖만 바라본 행동에서 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u1-X28','K5-1-u1-X33']::text[],false,'{"seq":15,"concept":"K5-1-u1-C30","difficulty":2,"kind":"mc","stem":"해람이가 말을 꺼내자 담우가 창밖만 바라본 행동에서 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"자기가 한 일을 들키는 것이 쑥스러웠다","correct":true},{"t":"창밖에 비가 다시 오고 있었다","mis":"K5-1-u1-X28"},{"t":"해람이의 말을 듣지 못했다","mis":"K5-1-u1-X33"},{"t":"노란 우산을 처음 들었다","mis":"K5-1-u1-X33"}],"explanation":["비가 온다는 단서는 없어요.","들었기에 「괜찮아」라고 했어요.","시선을 피한 행동이 단서예요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#16','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C37',2,'ox','auto','고민 ④를 쓴 친구는 짝이 물건을 쓰는 것이 전혀 신경 쓰이지 않아요.',ARRAY['K5-1-u1-X37']::text[],false,'{"seq":16,"concept":"K5-1-u1-C37","difficulty":2,"kind":"ox","stem":"고민 ④를 쓴 친구는 짝이 물건을 쓰는 것이 전혀 신경 쓰이지 않아요.","answer":"X","reason_options":[{"t":"「요즘은 짝 옆에 앉기가 불편합니다」에 서운한 마음이 드러나기 때문에","correct":true},{"t":"고민 글에 적힌 말만 보면 되기 때문에","mis":"K5-1-u1-X37"}],"mis":"K5-1-u1-X37","explanation":["불편하다고 적었어요.","적히지 않은 마음도 봐요.","단서로 마음을 짐작해요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#17','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C12',3,'mc','auto','찬솔이가 「속상하겠다」라는 말만 보태고 계속 태블릿을 본다면 어떻게 될까요?',ARRAY['K5-1-u1-X13','K5-1-u1-X11','K5-1-u1-X10']::text[],false,'{"seq":17,"concept":"K5-1-u1-C12","difficulty":3,"kind":"mc","stem":"찬솔이가 「속상하겠다」라는 말만 보태고 계속 태블릿을 본다면 어떻게 될까요?","options":[{"t":"말은 바뀌어도 마음이 없어 새별이는 여전히 서운할 것이다","correct":true},{"t":"말을 바꾸었으니 새별이의 마음이 다 풀린다","mis":"K5-1-u1-X13"},{"t":"말이 길어져서 배려가 된다","mis":"K5-1-u1-X11"},{"t":"태블릿을 보는 것은 대화와 관계없다","mis":"K5-1-u1-X10"}],"explanation":["흉내로는 풀리지 않아요.","길이 문제가 아니에요.","형식보다 진심이 먼저예요."],"asset":{"type":"speech","turns":[{"who":"새별","text":"어제 할머니께서 주신 머리핀을 잃어버렸어. 계속 마음에 걸려."},{"who":"찬솔","text":"(태블릿을 보며) 그거 또 사면 되잖아. 그런데 수학 숙제 했어?"},{"who":"새별","text":"……."},{"who":"다래","text":"(새별이 옆에 앉으며) 할머니께서 주신 거라 더 아끼던 거구나. 어디서 마지막으로 봤어?"},{"who":"새별","text":"체육 시간 전까지는 있었어. 같이 찾아봐 줄래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#18','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C27',3,'mc','auto','다음 가운데 짐작하며 듣기보다 말 그대로 들으면 되는 말은 어느 것인가요?',ARRAY['K5-1-u1-X30']::text[],false,'{"seq":18,"concept":"K5-1-u1-C27","difficulty":3,"kind":"mc","stem":"다음 가운데 짐작하며 듣기보다 말 그대로 들으면 되는 말은 어느 것인가요?","options":[{"t":"「내일 준비물은 색연필이래.」","correct":true},{"t":"(눈을 피하며) 「응, 괜찮아…….」","mis":"K5-1-u1-X30"},{"t":"「아…… 그래.」 (발목을 만지작거리며)","mis":"K5-1-u1-X30"},{"t":"「그…… 그냥 그랬어요.」","mis":"K5-1-u1-X30"}],"explanation":["말과 표정이 어긋나요.","말이 짧아지고 행동이 어긋나요.","또렷한 알림은 그대로 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#19','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C30',3,'mc','auto','담우가 「……들켰네.」라고 말한 데서 알 수 있는 것은 어느 것인가요?',ARRAY['K5-1-u1-X33']::text[],false,'{"seq":19,"concept":"K5-1-u1-C30","difficulty":3,"kind":"mc","stem":"담우가 「……들켰네.」라고 말한 데서 알 수 있는 것은 어느 것인가요?","options":[{"t":"담우가 우산을 빌려준 일을 일부러 말하지 않고 감추어 왔다","correct":true},{"t":"담우가 해람이의 우산을 숨겼다","mis":"K5-1-u1-X33"},{"t":"담우가 노란 우산을 처음 보았다","mis":"K5-1-u1-X33"},{"t":"담우는 해람이와 놀고 싶지 않다","mis":"K5-1-u1-X33"}],"explanation":["빌려준 것이지 숨긴 게 아니에요.","쪽지를 쓴 사람이에요.","감추어 온 마음이 드러났어요."],"asset":{"type":"passage","lines":["다음 날 아침, 짝 담우가 연달아 재채기를 했다. 목소리도 잠겨 있었다.","해람이는 담우의 알림장을 보았다. 동글동글한 글씨가 가지런히 적혀 있었다.","「혹시 어제 노란 우산……」 해람이가 말을 꺼내자 담우는 창밖만 바라보았다.","「나는 집이 가까워서 괜찮아.」","해람이는 노란 우산을 담우의 책상 옆에 살며시 걸어 두었다.","담우가 머쓱한 듯 웃었다. 「……들켰네.」"],"title":"「우산꽂이의 쪽지」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#20','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C34',3,'mc','auto','고민 ④를 쓴 친구의 마음을 짐작한 뒤 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X29','K5-1-u1-X36','K5-1-u1-X39']::text[],false,'{"seq":20,"concept":"K5-1-u1-C34","difficulty":3,"kind":"mc","stem":"고민 ④를 쓴 친구의 마음을 짐작한 뒤 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「혹시 짝한테 서운한데 말을 못 해서 답답한 거야?」","correct":true},{"t":"「너 짝이 싫구나. 다 알아.」","mis":"K5-1-u1-X29"},{"t":"「물건 하나쯤은 괜찮잖아.」","mis":"K5-1-u1-X36"},{"t":"「짝을 바꿔 달라고 해.」","mis":"K5-1-u1-X39"}],"explanation":["단정하는 말이에요.","가볍게 넘겼어요.","짐작한 마음을 물어 확인해요."],"asset":{"type":"passage","lines":["고민 ④ 짝이 제 물건을 말없이 가져다 씁니다.","　　　 말하려다가도 사이가 나빠질까 봐 그만둡니다. 요즘은 짝 옆에 앉기가 불편합니다."],"title":"새로 들어온 고민 쪽지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#21','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C38',3,'ox','auto','상대를 배려하는 사람은 상대의 말과 행동을 눈여겨보게 되어 생략된 마음을 더 잘 짐작할 수 있어요.',ARRAY['K5-1-u1-X05']::text[],false,'{"seq":21,"concept":"K5-1-u1-C38","difficulty":3,"kind":"ox","stem":"상대를 배려하는 사람은 상대의 말과 행동을 눈여겨보게 되어 생략된 마음을 더 잘 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"배려하기 때문에 눈여겨보고, 눈여겨보기 때문에 짐작할 수 있기 때문에","correct":true},{"t":"배려하면 짐작할 일이 사라지기 때문에","mis":"K5-1-u1-X05"}],"mis":"K5-1-u1-X05","explanation":["맞는 말이에요.","짐작이 사라지지 않아요.","배려와 짐작은 서로를 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#22','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C19',3,'mc','auto','두 친구가 대화 주제를 정하는 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X21','K5-1-u1-X16']::text[],false,'{"seq":22,"concept":"K5-1-u1-C19","difficulty":3,"kind":"mc","stem":"두 친구가 대화 주제를 정하는 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 하고 싶은 주제를 말해 보고 둘 다 이야기하고 싶은 것으로 정한다","correct":true},{"t":"목소리가 큰 친구의 주제로 정한다","mis":"K5-1-u1-X21"},{"t":"먼저 온 친구의 주제로 정한다","mis":"K5-1-u1-X21"},{"t":"주제 없이 생각나는 대로 말한다","mis":"K5-1-u1-X16"}],"explanation":["한 사람이 빠져요.","한 사람이 빠져요.","함께 의논해 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#23','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C38',4,'mc','auto','이 단원에서 배운 것을 모두 쓴 친구의 모습으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u1-X08','K5-1-u1-X29','K5-1-u1-X10']::text[],false,'{"seq":23,"concept":"K5-1-u1-C38","difficulty":4,"kind":"mc","stem":"이 단원에서 배운 것을 모두 쓴 친구의 모습으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말이 짧아진 친구 곁에서 눈을 맞추고 들으며, 행동을 단서로 마음을 짐작해 「혹시 무슨 일 있어?」라고 묻는다","correct":true},{"t":"말이 짧아진 친구에게 「왜 그렇게 짧게 말해?」라고 따진다","mis":"K5-1-u1-X08"},{"t":"친구의 마음을 짐작해 반 친구들에게 알려 준다","mis":"K5-1-u1-X29"},{"t":"친구가 말할 때 휴대 전화를 보며 「응.」이라고 한다","mis":"K5-1-u1-X10"}],"explanation":["따지는 말이에요.","짐작은 알리지 않고 확인해요.","배려하며 듣고 짐작해 물었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#24','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C18',4,'essay','teacher','다래의 준비에서 빈칸을 채워 쓰고, 다래와 대화하는 친구가 할 반응하는 말을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u1-C18","difficulty":4,"kind":"essay","stem":"다래의 준비에서 빈칸을 채워 쓰고, 다래와 대화하는 친구가 할 반응하는 말을 두 가지 쓰세요.","answer_guide":{"answer":"예: 생각이나 느낌 — 손을 놓은 줄도 모르고 혼자 달리는 동생을 보니 대견하고 가슴이 뭉클했다. 반응하는 말 — 「동생이 손 놓은 걸 알았을 때 뭐라고 했어?」(이어 묻기), 「옆에서 같이 뛰어 줬으니 더 뿌듯했겠다.」(마음 알아주기)","scoring_points":["생각이나 느낌을 알맞게 채웠는가","이어 묻는 반응을 썼는가","마음을 알아주는 반응을 썼는가"]},"explanation":["그때 든 마음을 채워요.","이어받아 물어요.","마음을 알아줘요."],"asset":{"type":"passage","lines":["대화 주제 — 동생에게 처음으로 자전거 타는 법을 알려 준 일","언제 — 지난 일요일 오후에","어디에서 — 아파트 앞 공원에서","무슨 일을 — 동생 자전거 뒤를 잡고 따라 뛰다가 살며시 손을 놓았는데,","　　동생이 혼자서 공원 끝까지 달렸다.","생각이나 느낌 — ?"],"title":"다래가 준비한 내용"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u1_review_d#25','kor',5,1,'u1','','g5_1_kor_u1_review_d','unit_review','K5-1-u1-C27',4,'essay','teacher','모든 대화를 짐작하며 들을 필요는 없는 까닭을 쓰고, 짐작하며 들어야 하는 때를 두 가지 이상 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u1-C27","difficulty":4,"kind":"essay","stem":"모든 대화를 짐작하며 들을 필요는 없는 까닭을 쓰고, 짐작하며 들어야 하는 때를 두 가지 이상 쓰세요.","answer_guide":{"answer":"예: 대부분의 말은 말한 그대로가 전부이고, 아무 말에나 숨은 뜻을 붙이면 오히려 오해가 생기기 때문이다. 짐작하며 들어야 하는 때는 말이 갑자기 짧아질 때, 말과 표정이 어긋날 때, 되물어야 이해될 때이다.","scoring_points":["짐작하지 않아도 되는 까닭을 썼는가","짐작이 필요한 때를 두 가지 이상 썼는가","오해와 이어 설명했는가"]},"explanation":["대부분은 말 그대로예요.","신호를 떠올려요.","오해와 이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
